    Paladin = {{n="Holy", c="神圣", t={{n="Divine Strength", c="神圣之力", m=5, r=1, col=2, s="same", i="ability_golemthunderclap", d="使你的力量提高10%。", dEn="Increases your Strength by 10%.", rq=nil}, {n="Divine Intellect", c="神圣智慧", m=5, r=1, col=3, s="same", i="spell_nature_sleep", d="使你的智力值上限提高10%。", dEn="Increases your total Intellect by 10%.", rq=nil}, {n="Healing Light", c="治疗之光", m=3, r=2, col=1, s="changed", i="spell_holy_holybolt", d="使你的圣光术、圣光闪现和神圣震击的治疗量提高12%。", dEn="Increases the amount healed by your Holy Light, Flash of Light, and Holy Shock spells by 12%.", rq=nil}, {n="Spiritual Focus", c="精神集中", m=2, r=2, col=2, s="changed", i="spell_arcane_blink", d="使你的圣光闪现、圣光术和圣光守望有70%的几率在受到伤害时不损失施法时间。", dEn="Gives your Flash of Light, Holy Light, and Light's Vigil spells a 70% chance to not lose casting time when you take damage.", rq=nil}, {n="Improved Seals", c="强化圣印", m=3, r=2, col=3, s="changed", i="ability_thunderbolt", d="使你的圣印和审判造成的伤害提高15%。", dEn="Increases the damage done by your Seals and Judgements by 15%.", rq=nil}, {n="Unyielding Faith", c="不灭信仰", m=2, r=2, col=4, s="changed", i="spell_holy_unyieldingfaith", d="使你受到的恐惧和迷惑效果的持续时间缩短30%。", dEn="Reduces the duration of Fear and Disorient effects on you by 30%.", rq=nil}, {n="Voice of Truth", c="真理之音", m=1, r=3, col=1, s="new", i="inv_misc_horn_03", d="使你对沉默和打断效果免疫，持续6秒。", dEn="Grants you immunity to Silence and Interrupt effects for 6 sec.", rq=nil}, {n="Reverence", c="敬畏", m=3, r=3, col=2, s="new", i="spell_holy_divineillumination", d="使你在施法时仍保持30%的法力值恢复速度。", dEn="Allows 30% of your Mana regeneration to continue while casting.", rq=nil}, {n="Purifying Power", c="净化之力", m=2, r=3, col=3, s="new", i="spell_holy_purifyingpower", d="使你的清洁术和纯净术法力消耗降低20%，并使驱邪术和神圣愤怒的冷却时间缩短33%。", dEn="Reduces the mana cost of your Cleanse and Purify spells by 20% and reduces the cooldown of your Exorcism and Holy Wrath spells by 33%.", rq=nil}, {n="Infusion of Light", c="圣光灌注", m=2, r=4, col=1, s="new", i="ability_paladin_infusionoflight", d="你的神圣震击和圣光闪现造成爆击时，使你在15秒内下一次圣光术的施法时间缩短1秒。", dEn="Your Holy Shock and Flash of Light critical hits reduce the cast time of your next Holy Light cast within 15 sec by 1 sec.", rq=nil}, {n="Illumination", c="启发", m=5, r=4, col=2, s="changed", i="spell_holy_greaterheal", d="在你的圣光闪现、圣光术、圣光守夜或神圣震击治疗法术造成爆击效果后，你有100%的几率回复相当于该法术基础消耗50%的法力值。", dEn="After getting a critical effect from your Flash of Light, Holy Light, Light's Vigil, or Holy Shock heal spell you have a 100% chance to gain Mana equal to 50% of the base cost of the spell.", rq={3, 2}}, {n="Divine Favor", c="神恩术", m=1, r=4, col=3, s="moved", i="spell_holy_heal", d="激活之后，使你的下一个圣光闪现、圣光术或神圣震击有100%的几率造成极效治疗效果。", dEn="When activated, gives your next Flash of Light, Holy Light, or Holy Shock spell a 100% critical effect chance.", rq=nil}, {n="Divine Precision", c="神圣精准", m=3, r=5, col=1, s="new", i="spell_holy_healingfocus", d="使你的神圣法术命中几率提高18%。", dEn="Improves your chance to hit with Holy spells by 18%.", rq={5, 2}}, {n="Holy Shock", c="神圣震击", m=1, r=5, col=2, s="changed", i="spell_holy_searinglight", d="用神圣能量冲击目标，对敌人造成129到139点神圣伤害，或为友方目标恢复110到118点生命值。", dEn="Blasts the target with Holy energy, causing 129 to 139 Holy damage to an enemy, or 110 to 118 healing to an ally.", rq=nil}, {n="Consecrated Ground", c="奉献之地", m=2, r=5, col=3, s="new", i="spell_holy_innerfire", d="使你的神圣法术对最先进入你的奉献的4个敌人造成的伤害提高10%。", dEn="Gives your Holy spells 10% increased damage against the first 4 enemies that enter your Consecration.", rq=nil}, {n="Holy Power", c="神圣能量", m=5, r=6, col=3, s="changed", i="spell_holy_power", d="使你的神圣震击和神圣打击的爆击几率提高15%，其他所有法术的爆击几率提高5%。", dEn="Increases the critical strike chance of your Holy Shock and Holy Strike spells by 15%, and all other spells by 5%.", rq=nil}, {n="Light's Vigil", c="圣光守望", m=1, r=7, col=2, s="new", i="ability_paladin_judgementofthepure", d="对目标施加圣光守望，持续30秒。你对其施放的下一个神圣震击不会触发冷却：若目标为敌人，则对其造成175到189点神圣伤害，并返还圣光守望75%的法力消耗；若目标为友方，则为其小队恢复325到343点生命值。每个小队同时只能存在一个圣光守望。", dEn="Applies Light's Vigil to the target for 30 sec. Your next Holy Shock cast on them triggers no cooldown and causes enemy targets to suffer 175 to 189 Holy damage and refund 75% of Light's Vigil's Mana cost, or allied targets to heal their party for 325 to 343. You may only have one Light's Vigil active per party.", rq={5, 2}}}}, {n="Protection", c="防护", t={{n="Toughness", c="坚韧", m=5, r=1, col=2, s="moved", i="spell_holy_devotion", d="使你因装备而获得的护甲值提高10%。", dEn="Increases your armor value from items by 10%.", rq=nil}, {n="Redoubt", c="盾牌壁垒", m=5, r=1, col=3, s="changed", i="ability_defend", d="对你造成伤害的近战攻击有10%的几率使你的格挡几率提高20%。持续10秒或格挡5次。", dEn="Damaging melee attacks against you have a 10% chance to increase your chance to block by 20%. Lasts 10 sec or 5 blocks.", rq=nil}, {n="Precision", c="精准", m=3, r=2, col=1, s="changed", i="ability_rogue_ambush", d="使你击中目标的几率提高3%。", dEn="Improves your chance to hit by 3%.", rq=nil}, {n="Guardian's Favor", c="守护者的宠爱", m=2, r=2, col=2, s="changed", i="spell_holy_sealofprotection", d="使你的保护祝福冷却时间缩短2分钟，并使自由祝福持续时间延长6秒。", dEn="Reduces the cooldown of your Blessing of Protection by 2 min and increases the duration of your Blessing of Freedom by 6 sec.", rq=nil}, {n="Anticipation", c="预知", m=5, r=2, col=4, s="changed", i="spell_magic_lesserinvisibilty", d="使你的防御技能提高20点。", dEn="Increases your Defense Skill by 20.", rq=nil}, {n="Improved Seal of Fury", c="强化愤怒圣印", m=1, r=3, col=1, s="new", i="spell_holy_righteousnessaura", d="愤怒圣印提供的护盾被完全吸收时，恢复60点法力值。攻击者每比你高一级，恢复量提高15%，最高提高45%。", dEn="When Seal of Fury's shield is fully absorbed, restore 60 Mana, increased by 15% per level the attacker is above you, up to 45%.", rq=nil}, {n="Improved Righteous Fury", c="强化正义之怒", m=3, r=3, col=2, s="changed", i="spell_holy_sealoffury", d="当正义之怒处于激活状态时，你所承受的一切伤害降低6%。", dEn="While Righteous Fury is active, all damage taken is reduced by 6%.", rq=nil}, {n="Shield Specialization", c="盾牌专精", m=3, r=3, col=3, s="changed", i="inv_shield_06", d="使你的盾牌吸收的伤害提高30%，并使你的格挡有100%的几率恢复最大法力值的6%。每3秒最多触发一次。", dEn="Increases the amount of damage absorbed by your shield by 30%, and gives your blocks a 100% chance to restore 6% of your maximum Mana. May only occur once every 3 sec.", rq={1, 3}}, {n="Sacred Duty", c="神圣职责", m=2, r=3, col=4, s="new", i="spell_holy_divineintervention", d="使你的耐力总值提高4%，并使圣盾术、圣佑术和圣殿骑士壁垒的冷却时间缩短60秒。", dEn="Increases your total Stamina by 4% and reduces the cooldown of your Divine Shield, Divine Protection, and Templar's Bulwark spells by 60 sec.", rq=nil}, {n="Swift Judgement", c="迅捷审判", m=1, r=4, col=1, s="new", i="ability_paladin_judgementred", d="结束审判的剩余冷却时间，并使你下一次审判消耗的法力值降低100%。", dEn="Finishes the remaining cooldown on your Judgement ability and reduces the Mana cost of your next Judgement by 100%.", rq={3, 1}}, {n="One-Handed Weapon Specialization", c="单手武器专精", m=3, r=4, col=2, s="changed", i="inv_sword_20", d="使你的单手近战武器所能造成的伤害提高10%。", dEn="Increases the damage you deal with one-handed melee weapons by 10%.", rq=nil}, {n="Improved Hammer of Justice", c="强化制裁之锤", m=3, r=4, col=3, s="same", i="spell_holy_sealofmight", d="使你的制裁之锤的冷却时间减少15秒。", dEn="Decreases the cooldown of your Hammer of Justice spell by 15 sec.", rq=nil}, {n="Templar's Bulwark", c="圣殿骑士壁垒", m=1, r=5, col=2, s="new", i="ability_paladin_shieldofthetemplar", d="激活后，为你提供一个相当于你最大生命值100%的吸收护盾，持续8秒。施加自律效果1分钟。自律效果激活期间无法施放。", dEn="When activated, this ability grants you an absorb shield equal to 100% of your maximum health for 8 sec. Applies Forbearance for 1 min. Cannot be cast while Forbearance is active.", rq=nil}, {n="Reckoning", c="清算", m=5, r=5, col=3, s="changed", i="spell_holy_blessingofstrength", d="使你在格挡一次近战攻击后有40%的几率获得一次额外攻击，受到非周期性爆击之后有100%%的几率获得一次额外攻击。", dEn="Gives you a 40% chance to gain an extra attack after Blocking a melee attack and a 100% chance to gain an extra attack after being the victim of a non-periodic critical strike.", rq=nil}, {n="Iron Creed", c="钢铁信条", m=5, r=6, col=3, s="new", i="spell_holy_improvedresistanceauras", d="使你的神圣打击产生的威胁值提高25%。正义之怒生效时，神圣打击还会使你受到的伤害降低10%，持续6秒。", dEn="Increases the threat generated by your Holy Strike ability by 25%. While Righteous Fury is active, Holy Strike also reduces your damage taken by 10% for 6 sec.", rq=nil}, {n="Holy Shield", c="神圣之盾", m=1, r=7, col=2, s="changed", i="spell_holy_blessingofprotection", d="使你的格挡几率提高30%，持续10秒。在此期间每次成功格挡都会对攻击者造成110点神圣伤害。神圣之盾造成的伤害额外产生20%的威胁值。每次格挡消耗一层充能。共4层。", dEn="Increases chance to block by 30% for 10 sec, and deals 110 Holy damage for each attack blocked while active. Damage caused by Holy Shield causes 20% additional threat. Each block expends a charge. 4 charges.", rq={5, 2}}}}, {n="Retribution", c="惩戒", t={{n="Deflection", c="偏斜", m=5, r=1, col=2, s="moved", i="ability_parry", d="使你的招架几率提高5%。", dEn="Increases your Parry chance by 5%.", rq=nil}, {n="Benediction", c="祈福", m=5, r=1, col=3, s="changed", i="spell_frost_windwalkon", d="使你所有瞬发法术和技能所消耗的法力值降低10%。", dEn="Reduces the Mana cost of all instant cast spells and abilities by 10%.", rq=nil}, {n="Improved Judgement", c="强化审判", m=2, r=2, col=1, s="changed", i="spell_holy_righteousfury", d="使你的审判技能冷却时间缩短2秒。", dEn="Decreases the cooldown of your Judgement ability by 2 sec.", rq=nil}, {n="Holy Conduit", c="神圣导能", m=2, r=2, col=2, s="new", i="spell_holy_devineaegis", d="使你的奉献、神圣愤怒、驱邪术和愤怒之锤法力消耗降低40%。", dEn="Reduces the mana cost of your Consecration, Holy Wrath, Exorcism, and Hammer of Wrath spells by 40%.", rq=nil}, {n="Conviction", c="定罪", m=5, r=2, col=3, s="changed", i="spell_holy_retributionaura", d="使你的近战攻击造成爆击的几率提高5%。", dEn="Improves your chance to get a critical strike with melee attacks by 5%.", rq=nil}, {n="Vindication", c="辩护", m=3, r=3, col=1, s="changed", i="spell_holy_vindication", d="使你的伤害性近战攻击有几率令目标的攻击强度降低200点，并使你的攻击强度提高3%，持续30秒。", dEn="Gives your damaging melee attacks a chance to reduce the target's Attack Power by 200, and increase your Attack Power by 3% for 30 sec.", rq=nil}, {n="Sanctified Judgement", c="神圣审判", m=3, r=3, col=2, s="new", i="ability_paladin_judgementblue", d="使你的审判有100%几率返还被审判圣印法力消耗的60%。", dEn="Gives your Judgement ability a 100% chance to return 60% of the Mana cost of the judged seal.", rq=nil}, {n="Seal of Command", c="命令圣印", m=1, r=3, col=3, s="changed", i="ability_warrior_innerrage", d="使圣骑士有几率造成相当于普通武器伤害70%的额外神圣伤害。圣骑士同一时间只能激活一个圣印。持续30秒。\n\n释放此圣印的能量将审判敌人，立即造成68到73点神圣伤害；若目标处于昏迷或瘫痪状态，则造成137到145点伤害。", dEn="Gives the Paladin a chance to deal additional Holy damage equal to 70% of normal weapon damage. Only one Seal can be active on the Paladin at any one time. Lasts 30 sec.\n\nUnleashing this Seal's energy will judge an enemy, instantly causing 68 to 73 Holy damage, 137 to 145 if the target is stunned or incapacitated.", rq=nil}, {n="Pursuit of Justice", c="正义追击", m=2, r=3, col=4, s="changed", i="spell_holy_persuitofjustice", d="使你的移动速度和坐骑移动速度提高15%。这个效果不与其它同类效果叠加。", dEn="Increases movement speed and mounted movement speed by 15%. This does not stack with other movement speed increasing effects.", rq=nil}, {n="Eye for an Eye", c="以眼还眼", m=2, r=4, col=1, s="changed", i="spell_holy_eyeforaneye", d="所有对你造成的爆击也会对攻击者造成相当于你所受伤害10%的伤害。以眼还眼造成的伤害不会超过圣骑士总生命值的50%。", dEn="All critical strikes against you cause 10% of the damage taken to the attacker as well. The damage caused by Eye for an Eye will not exceed 50% of the Paladin's total health.", rq=nil}, {n="Sacred Arbiter", c="神圣仲裁者", m=1, r=4, col=3, s="new", i="inv_sword_08", d="使你的神圣打击造成的伤害提高20%，并刷新目标身上的所有审判效果。", dEn="Increases the damage of your Holy Strike ability by 20% and causes it to refresh all Judgement effects on the target.", rq=nil}, {n="Two-Handed Weapon Specialization", c="双手武器专精", m=3, r=5, col=1, s="same", i="inv_hammer_04", d="使你的双手近战武器造成的伤害提高6%。", dEn="Increases the damage you deal with two-handed melee weapons by 6%.", rq=nil}, {n="Vengeance", c="复仇", m=3, r=5, col=2, s="changed", i="ability_racial_avatar", d="非周期性伤害造成爆击后，你造成的物理和神圣伤害提高3%，持续30秒。最多叠加3次。", dEn="Increases your Physical and Holy damage dealt by 3% for 30 sec after landing a non-periodic critical strike. Stacks up to 3 times.", rq={3, 2}}, {n="Repentance", c="忏悔", m=1, r=5, col=3, s="moved", i="spell_holy_prayerofhealing", d="使敌方目标进入冥想状态，最多瘫痪6秒。造成任何伤害都会唤醒目标。只对人型生物有效。", dEn="Puts the enemy target in a state of meditation, incapacitating them for up to 6 sec. Any damage caused will awaken the target. Only works against Humanoids.", rq=nil}, {n="Champion of the Light", c="光芒勇士", m=3, r=6, col=2, s="new", i="ability_paladin_enlightenedjudgements", d="使你的法术伤害提高，数值最多相当于你智力的60%。", dEn="Increases your spell damage by up to 60% of your Intellect.", rq=nil}, {n="Instrument of Law", c="律法之器", m=2, r=6, col=3, s="new", i="spell_holy_divinepurpose", d="使你的愤怒之锤施法时间缩短1秒，并在正义之怒未激活时，你产生的所有威胁值降低20%。", dEn="Reduces the cast time of your Hammer of Wrath by 1 sec, and reduces all threat you generate by 20% while Righteous Fury is not active.", rq=nil}, {n="Twist of Light", c="圣光扭转", m=1, r=7, col=2, s="new", i="spell_holy_blessedresillience", d="使你的圣印法术的法力消耗降低20%。当你把命令圣印、正义圣印、狂怒圣印或公正圣印换成另一个圣印时，会获得那个圣印的回响：你的下一次近战攻击会附带被替换圣印的效果，并消耗回响。", dEn="Reduces the Mana cost of your Seal spells by 20%, and when you replace your Seal of Command, Seal of Righteousness, Seal of Fury, or Seal of Justice with a different Seal, you gain an Echo of that Seal. Your next melee attack applies the replaced Seal's effects, consuming the Echo.", rq=nil}}}},
    Hunter = {{n="Beast Mastery", c="野兽控制", t={{n="Deadly Aspects", c="致命守护", m=5, r=1, col=2, s="changed", i="spell_nature_ravenform", d="雄鹰守护激活时，自动射击有10%的几率使远程攻击速度提高30%，持续12秒。野兽守护激活时，所有近战自动攻击都有10%的几率使近战攻击速度提高30%，持续12秒。", dEn="While Aspect of the Hawk is active, Auto Shot has a 10% chance of increasing ranged attack speed by 30% for 12 sec. While Aspect of the Beast is active, all melee auto attacks have a 10% chance of increasing melee attack speed by 30% for 12 sec.", rq=nil}, {n="Endurance Training", c="耐久训练", m=5, r=1, col=3, s="changed", i="spell_nature_reincarnation", d="使你的宠物生命值和护甲提高15%。", dEn="Increases the Health and Armor of your pets by 15%.", rq=nil}, {n="Focused Fire", c="集中火力", m=2, r=2, col=1, s="new", i="inv_weapon_crossbow_10", d="宠物激活时，使你和宠物造成的所有伤害提高2%。", dEn="Increases all damage you and your pet deal by 2% while your pet is active.", rq=nil}, {n="Improved Aspect of the Monkey", c="强化灵猴守护", m=3, r=2, col=2, s="changed", i="ability_hunter_aspectofthemonkey", d="使你的灵猴守护提供的躲闪加成提高6%。此外，你的宠物获得灵猴守护效果的50%。", dEn="Increases the Dodge bonus of your Aspect of the Monkey by 6%. Additionally, your pet gains 50% of the effect of your Aspect of the Monkey ability.", rq=nil}, {n="Pathfinding", c="寻路", m=2, r=2, col=3, s="moved", i="ability_mount_jungletiger", d="使你的猎豹守护和豹群守护的速度加成效果提高6%。", dEn="Increases the speed bonus of your Aspect of the Cheetah and Aspect of the Pack by 6%.", rq=nil}, {n="Improved Revive Pet", c="强化复活宠物", m=2, r=2, col=4, s="same", i="ability_hunter_beastsoothe", d="使你的复活宠物法术的施法时间减少6秒，法力值消耗降低40%，宠物复活后的生命值提高30%。", dEn="Revive Pet's casting time is reduced by 6 sec, mana cost is reduced by 40%, and increases the health your pet returns with by an additional 30%.", rq=nil}, {n="Bestial Swiftness", c="野兽迅捷", m=1, r=3, col=2, s="changed", i="ability_druid_dash", d="使你的宠物移动速度提高30%。", dEn="Increases the movement speed of your pets by 30%.", rq=nil}, {n="Unleashed Fury", c="狂怒释放", m=5, r=3, col=3, s="changed", i="ability_bullrush", d="使你的宠物和雄鹰造成的伤害提高15%。", dEn="Increases the damage done by your pets and hawks by 15%.", rq=nil}, {n="Improved Mend Pet", c="强化治疗宠物", m=2, r=4, col=1, s="changed", i="ability_hunter_mendpet", d="使你的治疗宠物每次治疗时有50%的几率净化宠物身上的1个诅咒、疾病、魔法或中毒效果，并使法力消耗降低20%。", dEn="Gives your Mend Pet spell a 50% chance of cleansing 1 Curse, Disease, Magic, or Poison effect from your pet each time it heals and reduces the Mana cost by 20%.", rq=nil}, {n="Ferocity", c="凶暴", m=5, r=4, col=3, s="changed", i="inv_misc_monsterclaw_04", d="使你的宠物和雄鹰的爆击几率提高10%。", dEn="Increases the critical strike chance of your pets and hawks by 10%.", rq=nil}, {n="Summon Hawk", c="召唤雄鹰", m=1, r=4, col=4, s="new", i="ability_hunter_animalhandler", d="命令一只雄鹰俯冲轰炸目标敌人，造成32点物理伤害并继续攻击18秒。同时最多只能激活2只雄鹰。召唤雄鹰与奥术射击共享冷却时间。", dEn="Command a hawk to dive-bomb your targeted enemy, dealing 32 Physical damage and continuing its assault for 18 sec. Only 2 hawks can be active at once. Summon Hawk shares its cooldown with Arcane Shot.", rq=nil}, {n="Spirit Bond", c="灵魂联结", m=2, r=5, col=1, s="same", i="ability_druid_demoralizingroar", d="当你的宠物被激活后，你和你的宠物都会每5秒回复1%的生命值。", dEn="While your pet is active, you and your pet will regenerate 1% of total health every 5 sec.", rq=nil}, {n="Intimidation", c="胁迫", m=1, r=5, col=2, s="changed", i="ability_devour", d="命令你的宠物在下次成功攻击时使目标昏迷3秒，且该次攻击的爆击几率提高100%。产生大量威胁值。", dEn="Command your pet to Stun the target for 3 sec on its next successful attack, which also gains 100% increased critical strike chance. Generates high threat.", rq={3, 2}}, {n="Bestial Discipline", c="野兽戒律", m=2, r=5, col=4, s="changed", i="spell_nature_abolishmagic", d="使你的宠物的集中值回复速度提高20%，并使你在施法时仍可保持50%的法力回复。", dEn="Increases the Focus regeneration of your pets by 20% and allows 50% of your Mana regeneration to continue while casting.", rq=nil}, {n="Frenzy", c="狂乱", m=5, r=6, col=3, s="same", i="inv_misc_monsterclaw_03", d="使你的宠物有100%的几率在对敌人造成爆击后获得攻击速度提高30%的效果，持续8秒。", dEn="Gives your pet a 100% chance to gain a 30% attack speed increase for 8 sec after dealing a critical strike.", rq={4, 3}}, {n="Bestial Wrath", c="狂野怒火", m=1, r=7, col=2, s="same", i="ability_druid_ferociousbite", d="使宠物进入疯狂状态，对目标造成的伤害提高50%，持续18秒。在这种状态下，宠物不会有任何恐惧或怜悯，也无法停止下来，除非被杀死。", dEn="Send your pet into a rage causing 50% additional damage for 18 sec. While enraged, the beast does not feel pity or remorse or fear and it cannot be stopped unless killed.", rq={5, 2}}}}, {n="Marksmanship", c="射击", t={{n="Hawk Eye", c="鹰眼", m=3, r=1, col=1, s="moved", i="ability_townwatch", d="使你的远程武器的射程延长6码。", dEn="Increases the range of your ranged weapons by 6 yards.", rq=nil}, {n="Improved Concussive Shot", c="强化震荡射击", m=5, r=1, col=2, s="same", i="spell_frost_stun", d="使你的震荡射击有20%的几率令目标昏迷3秒。", dEn="Gives your Concussive Shot a 20% chance to stun the target for 3 sec.", rq=nil}, {n="Lethal Attacks", c="致命攻击", m=5, r=1, col=3, s="changed", i="ability_searingarrow", d="使你的所有攻击造成爆击的几率提高5%。", dEn="Increases your critical strike chance with all attacks by 5%.", rq=nil}, {n="Improved Stings", c="强化钉刺", m=3, r=2, col=1, s="changed", i="ability_hunter_quickshot", d="使你的毒蛇钉刺的伤害提高20%，蝰蛇钉刺的冷却时间缩短6秒，毒蝎钉刺的持续时间延长45秒。", dEn="Increases the damage of your Serpent Sting ability by 20%, reduces the cooldown of your Viper Sting ability by 6 sec, and increases the duration of your Scorpid Sting ability by 45 sec.", rq=nil}, {n="Efficiency", c="效率", m=5, r=2, col=2, s="changed", i="spell_frost_wizardmark", d="使你的射击、钉刺和近战技能所消耗的法力值降低15%。", dEn="Reduces the Mana cost of your Shots, Stings, and melee abilities by 15%.", rq=nil}, {n="Careful Aim", c="精确瞄准", m=5, r=2, col=3, s="new", i="ability_hunter_zenarchery", d="使你的攻击强度提高，数值相当于你的智力值的100%。", dEn="Increases your Attack Power by 100% of your Intellect.", rq=nil}, {n="Rapid Killing", c="疾速杀戮", m=2, r=3, col=1, s="new", i="ability_hunter_rapidkilling", d="使你的急速射击冷却时间缩短2分钟。此外，当你消灭一个能为你提供经验值或荣誉值的敌人，或其在受到你的毒蛇钉刺影响时死亡，你获得疾速杀戮，使你在20秒内的下一个射击技能造成的伤害提高20%。", dEn="Reduces the cooldown on your Rapid Fire ability by 2 min. In addition, when you kill a non-trivial enemy or it dies while afflicted by your Serpent Sting, you gain Rapid Killing, increasing the damage of your next Shot ability within 20 sec by 20%.", rq=nil}, {n="Improved Arcane Shot", c="强化奥术射击", m=5, r=3, col=2, s="changed", i="ability_impalingbolt", d="使你的奥术射击的冷却时间缩短1.5秒。不影响与奥术射击共享冷却时间的技能。", dEn="Reduces the cooldown of your Arcane Shot by 1.5 sec. Does not affect the cooldown of abilities which share a cooldown with Arcane Shot.", rq=nil}, {n="Lone Wolf", c="独来独往", m=1, r=3, col=4, s="new", i="ability_mount_whitedirewolf", d="没有激活的宠物时，你的所有攻击造成的伤害提高20%。", dEn="You deal 20% increased damage with all attacks while you do not have an active pet.", rq=nil}, {n="Trueshot Aura", c="强击光环", m=1, r=4, col=2, s="changed", i="ability_trueshot", d="使45码内小队成员的远程攻击强度提高30。", dEn="Increases the Ranged Attack Power of party members within 45 yds by 30.", rq=nil}, {n="Mortal Shots", c="致死射击", m=5, r=4, col=3, s="changed", i="ability_piercedamage", d="使你所有远程技能的爆击伤害加成提高30%。", dEn="Increases the critical strike damage bonus on all ranged abilities by 30%.", rq={2, 3}}, {n="Rapid Recuperation", c="急速恢复", m=2, r=5, col=1, s="new", i="ability_hunter_rapidregeneration", d="用毒蛇钉刺命中目标时使你获得50%、消耗疾速杀戮时使你获得100%的施法时法力回复，持续15秒。", dEn="Hitting a target with your Serpent Sting ability grants you 50% and consuming Rapid Killing grants you 100% of your Mana regeneration while casting for the next 15 sec.", rq={3, 1}}, {n="Barrage", c="弹幕", m=3, r=5, col=3, s="changed", i="ability_upgrademoonglaive", d="使你的多重射击、瞄准射击和乱射技能造成的伤害提高10%。", dEn="Increases the damage done by your Multi-Shot, Aimed Shot, and Volley abilities by 10%.", rq=nil}, {n="Scatter Shot", c="驱散射击", m=1, r=5, col=4, s="same", i="ability_golemstormbolt", d="短程射击，对目标造成50%的武器伤害，并使其困惑4秒。任何伤害都会打断该效果。使用之后结束你的攻击。", dEn="A short-range shot that deals 50% weapon damage and disorients the target for 4 sec. Any damage caused will remove the effect. Turns off your attack when used.", rq=nil}, {n="Ranged Weapon Specialization", c="远程武器专精", m=5, r=6, col=3, s="same", i="inv_weapon_rifle_06", d="使你的远程武器造成的伤害提高5%。", dEn="Increases the damage you deal with ranged weapons by 5%.", rq=nil}, {n="Sniper Shot", c="狙击", m=1, r=7, col=2, s="changed", i="hunter_pvp_snipershot", d="一次远距离射击，造成远程伤害外加160点，并使你接下来的3次射击的射程提高10码，持续10秒。", dEn="A long-range shot that deals ranged damage plus 160 and increases the range of your next 3 Shots by 10 yards for 10 sec.", rq={4, 2}}}}, {n="Survival", c="生存", t={{n="Improved Tracking", c="强化追踪", m=5, r=1, col=2, s="new", i="inv_misc_head_dragon_black", d="在追踪野兽、恶魔、龙类、元素生物、巨人、人型生物或亡灵时，你对该被追踪生物类型造成的所有伤害提高5%。", dEn="While tracking Beasts, Demons, Dragonkin, Elementals, Giants, Humanoids, or Undead, all damage you deal to the tracked creature type is increased by 5%.", rq=nil}, {n="Deflection", c="偏斜", m=5, r=1, col=3, s="same", i="ability_parry", d="使你的招架几率提高5%。", dEn="Increases your Parry chance by 5%.", rq=nil}, {n="Entrapment", c="诱捕", m=5, r=2, col=1, s="changed", i="spell_nature_stranglevines", d="当你的陷阱被触发时，所有受影响的目标被诱捕，无法移动，持续5秒。", dEn="When your traps are triggered, all affected targets are Entrapped, preventing them from moving for 5 sec.", rq=nil}, {n="Savage Strikes", c="野蛮打击", m=2, r=2, col=2, s="changed", i="ability_racial_bloodrage", d="使你所有近战技能的爆击几率提高4%。", dEn="Increases the critical strike chance of all your melee abilities by 4%.", rq=nil}, {n="Survivalist", c="生存专家", m=5, r=2, col=3, s="changed", i="spell_shadow_twilight", d="使你的总生命值提高10%。", dEn="Increases your total Health by 10%.", rq=nil}, {n="Improved Wing Clip", c="强化摔绊", m=3, r=2, col=4, s="changed", i="ability_rogue_trip", d="使你的摔绊技能有20%的几率令目标在5秒内无法移动。", dEn="Gives your Wing Clip ability a 20% chance to immobilize the target for 5 sec.", rq=nil}, {n="Clever Traps", c="灵巧陷阱", m=2, r=3, col=1, s="same", i="spell_nature_timestop", d="使你的冰冻陷阱和冰霜陷阱的效果持续时间提高30%，献祭陷阱和爆炸陷阱所造成的伤害提高30%。", dEn="Increases the duration of Freezing and Frost trap effects by 30% and the damage of Immolation and Explosive trap effects by 30%.", rq=nil}, {n="Surefooted", c="稳固", m=3, r=3, col=2, s="changed", i="ability_kick", d="使你的命中几率提高3%，并使你受到的移动限制效果的持续时间缩短30%。", dEn="Increases your hit chance by 3% and reduces the duration of movement impairing effects on you by 30%.", rq=nil}, {n="Deterrence", c="威慑", m=1, r=3, col=3, s="same", i="ability_whirlwind", d="激活之后，使你的躲闪和招架几率提高25%，持续10秒。", dEn="When activated, increases your Dodge and Parry chance by 25% for 10 sec.", rq=nil}, {n="Survival Tactics", c="生存战术", m=2, r=4, col=1, s="new", i="ability_ensnare", d="使你的陷阱和假死的命中几率提高10%。", dEn="Increases your chance to hit with your Trap and Feign Death abilities by 10%.", rq=nil}, {n="Predator's Edge", c="掠食者之锋", m=5, r=4, col=2, s="new", i="ability_dualwield", d="使你的近战爆击伤害提高30%，副手武器伤害提高50%。", dEn="Increases your melee critical strike damage by 30% and your Off Hand weapon damage by 50%.", rq=nil}, {n="Counterattack", c="反击", m=1, r=4, col=3, s="changed", i="ability_warrior_challange", d="招架对手的攻击后可使用。该攻击造成50%武器伤害外加13点伤害，并使目标无法移动5秒。反击无法被格挡、躲闪或招架。", dEn="A strike that becomes active after parrying an opponent's attack. This attack deals 50% weapon damage plus 13 and immobilizes the target for 5 sec. Counterattack cannot be blocked, dodged, or parried.", rq={3, 3}}, {n="Resourcefulness", c="游刃有余", m=2, r=5, col=1, s="new", i="ability_hunter_resourcefulness", d="使你的陷阱技能和近战技能消耗的法力值降低60%。此外，你的爆击有60%的几率使你在施法时仍可保持50%的法力回复速度，持续30秒。", dEn="Reduces the mana cost of your Trap abilities and melee abilities by 60%. In addition, your critical strikes have a 60% chance to allow 50% of your Mana regeneration to continue while casting for 30 sec.", rq=nil}, {n="Expose Prey", c="暴露猎物", m=2, r=5, col=2, s="new", i="ability_hunter_swiftstrike", d="你对带有猎人印记的目标的攻击有10%的几率激活猫鼬撕咬，持续5秒。", dEn="Your attacks against targets with Hunter's Mark have a 10% chance to activate your Mongoose Bite for 5 sec.", rq=nil}, {n="Survivalist's Discipline", c="生存专家的戒律", m=2, r=5, col=3, s="new", i="ability_hunter_mastertactitian", d="使你的陷阱和威慑技能的冷却时间缩短40%。", dEn="Reduces the cooldown of your Trap and Deterrence abilities by 40%.", rq=nil}, {n="Strider Kick", c="陆行鸟踢击", m=1, r=5, col=4, s="new", i="ability_hunter_pet_tallstrider", d="一记强力的踢击，造成100%的近战武器伤害，并使移动速度提高30%，持续3秒。", dEn="A powerful kick that deals 100% melee weapon damage and increases movement speed by 30% for 3 sec.", rq=nil}, {n="Lightning Reflexes", c="闪电反射", m=5, r=6, col=3, s="changed", i="spell_nature_invisibilty", d="使你的敏捷提高10%。", dEn="Increases your Agility by 10%.", rq=nil}, {n="Lacerating Strikes", c="裂伤打击", m=1, r=7, col=2, s="new", i="ability_gouge", d="你的猫鼬撕咬还会使目标流血，在21秒内造成相当于猫鼬撕咬伤害40%的伤害", dEn="Your Mongoose Bite also causes the target to Bleed for damage equal to 40% of the damage done by Mongoose Bite over 21 sec", rq={5, 2}}}}},
    Rogue = {{n="Assassination", c="刺杀", t={{n="Improved Gouge", c="强化凿击", m=3, r=1, col=1, s="changed", i="ability_gouge", d="使你的凿击技能持续时间延长1.5秒。", dEn="Increases the duration of your Gouge ability by 1.5 sec.", rq=nil}, {n="Remorseless Attacks", c="冷酷攻击", m=2, r=1, col=2, s="changed", i="ability_fiegndead", d="击杀一个能为你提供经验值或荣誉值的敌人后，使你的下一次邪恶攻击、背刺、伏击、毁伤或鬼魅攻击的爆击几率提高40%。持续20秒。", dEn="After killing a non-trivial enemy, gives you a 40% increased critical strike chance on your next Sinister Strike, Backstab, Ambush, Mutilate, or Ghostly Strike. Lasts 20 sec.", rq=nil}, {n="Malice", c="恶意", m=5, r=1, col=3, s="changed", i="ability_racial_bloodrage", d="使你所有攻击和毒药的爆击几率提高5%。", dEn="Increases your critical strike chance with all attacks and Poisons by 5%.", rq=nil}, {n="Ruthlessness", c="无情", m=3, r=2, col=1, s="same", i="ability_druid_disembowel", d="使你的终结技有60%的几率为目标增加一个连击点数。", dEn="Gives your finishing moves a 60% chance to add a Combo Point to your target.", rq=nil}, {n="Murder", c="密谋", m=2, r=2, col=2, s="changed", i="spell_shadow_deathscream", d="对人型和巨人目标造成的所有伤害提高4%。", dEn="Increases all damage dealt by 4% against Humanoid and Giant targets.", rq=nil}, {n="Improved Slice and Dice", c="强化切割", m=3, r=2, col=4, s="same", i="ability_rogue_slicedice", d="使你的切割技能的效果持续时间延长45%。", dEn="Increases the duration of your Slice and Dice ability by 45%.", rq=nil}, {n="Relentless Strikes", c="无情打击", m=1, r=3, col=1, s="same", i="ability_warrior_decisivestrike", d="你的终结技每消耗一个连击点数都有20%的几率恢复25点能量。", dEn="Your finishing moves have a 20% chance per Combo Point to restore 25 Energy.", rq=nil}, {n="Improved Expose Armor", c="强化破甲", m=2, r=3, col=2, s="changed", i="ability_warrior_riposte", d="使你的破甲消耗的能量值降低10点，并在以5个连击点数施放时返还2个连击点。", dEn="Reduces the Energy cost of your Expose Armor ability by 10, and refunds 2 Combo Points when cast with 5 Combo Points.", rq=nil}, {n="Lethality", c="致命偷袭", m=5, r=3, col=3, s="changed", i="ability_criticalstrike", d="使你的邪恶攻击、凿击、背刺、毁伤、鬼魅攻击和出血技能的爆击伤害加成提高20%。", dEn="Increases the critical strike damage bonus of your Sinister Strike, Gouge, Backstab, Mutilate, Ghostly Strike, and Hemorrhage abilities by 20%.", rq={1, 3}}, {n="Vile Poisons", c="恶性毒药", m=5, r=4, col=1, s="same", i="ability_rogue_feigndeath", d="使你的毒素所造成的伤害提高20%，并使你的毒药抵抗驱散效果的几率提高40%。", dEn="Increases the damage dealt by your poisons by 20% and gives your poisons an additional 40% chance to resist dispel effects.", rq=nil}, {n="Cold Blood", c="冷血", m=1, r=4, col=2, s="changed", i="spell_ice_lament", d="激活后，使你的下一次邪恶攻击、背刺、伏击、刺骨或毁伤的爆击几率提高100%。", dEn="When activated, increases the critical strike chance of your next Sinister Strike, Backstab, Ambush, Eviscerate, or Mutilate by 100%.", rq=nil}, {n="Improved Poisons", c="强化毒药", m=5, r=4, col=3, s="changed", i="ability_poisons", d="使你对目标施加毒药的几率提高10%，并使毒药生效时有50%的几率不消耗使用次数。", dEn="Increases the chance to apply Poisons to your target by 10%, and gives Poison applications a 50% chance to not consume a charge.", rq=nil}, {n="Vigor", c="精力", m=2, r=5, col=1, s="changed", i="spell_nature_earthbindtotem", d="使你的能量值上限提高10点。", dEn="Increases your maximum Energy by 10.", rq=nil}, {n="Mutilate", c="毁伤", m=1, r=5, col=2, s="new", i="ability_rogue_deadlybrew", d="立即用两把武器攻击，每把武器造成75%武器伤害，外加13点伤害。对中毒目标造成的伤害提高20%。奖励2个连击点。", dEn="Instantly attacks with both weapons for 75% weapon damage plus an additional 13 with each weapon. Damage increased by 20% against Poisoned targets. Awards 2 Combo Points.", rq=nil}, {n="Improved Kidney Shot", c="强化肾击", m=2, r=5, col=3, s="changed", i="ability_rogue_kidneyshot", d="被你的肾击昏迷的敌人，受到你的毒药和攻击的伤害提高10%。", dEn="Enemies Stunned by your Kidney Shot ability take 10% increased damage from your poisons and attacks.", rq=nil}, {n="Seal Fate", c="封印命运", m=5, r=6, col=3, s="same", i="spell_shadow_chilltouch", d="可增加连击点数的技能造成爆击时，有100%的几率额外增加一个连击点数。", dEn="Your critical strikes from abilities that add Combo Points have a 100% chance to add an additional Combo Point.", rq=nil}, {n="Venom", c="毒针", m=1, r=7, col=2, s="new", i="inv_sword_31", d="终结技，使你的毒药伤害提高30%，施加毒药的几率提高10%。连击点数越多，持续时间越长：\n 1点：9秒\n 2点：12秒\n 3点：15秒\n 4点：18秒\n 5点：21秒", dEn="Finishing move that increases the damage of your Poisons by 30% and your chance to apply Poisons by 10%. Lasts longer per combo point:\n 1 point : 9 sec\n 2 points: 12 sec\n 3 points: 15 sec\n 4 points: 18 sec\n 5 points: 21 sec", rq={5, 2}}}}, {n="Combat", c="战斗", t={{n="Improved Eviscerate", c="强化刺骨", m=3, r=1, col=1, s="changed", i="ability_rogue_eviscerate", d="使你的刺骨技能所造成的伤害提高20%。", dEn="Increases the damage done by your Eviscerate ability by 20%.", rq=nil}, {n="Improved Sinister Strike", c="强化邪恶攻击", m=2, r=1, col=2, s="same", i="spell_shadow_ritualofsacrifice", d="使你的邪恶攻击技能所消耗的能量值减少5点。", dEn="Reduces the Energy cost of your Sinister Strike ability by 5.", rq=nil}, {n="Lightning Reflexes", c="闪电反射", m=5, r=1, col=3, s="same", i="spell_nature_invisibilty", d="使你的躲闪几率提高5%。", dEn="Increases your Dodge chance by 5%.", rq=nil}, {n="Puncturing Wounds", c="穿刺之伤", m=3, r=2, col=1, s="changed", i="ability_backstab", d="使你的背刺爆击几率提高30%、毁伤爆击几率提高15%，并使背刺有45%的几率额外增加一个连击点数。", dEn="Increases the critical strike chance of your Backstab by 30% and your Mutilate by 15%, and gives Backstab a 45% chance to add an additional Combo Point.", rq=nil}, {n="Deflection", c="偏斜", m=3, r=2, col=2, s="changed", i="ability_parry", d="使你的招架几率提高6%。", dEn="Increases your Parry chance by 6%.", rq=nil}, {n="Precision", c="精准", m=3, r=2, col=3, s="changed", i="ability_marksmanship", d="使你击中目标的几率提高3%。", dEn="Improves your chance to hit by 3%.", rq=nil}, {n="Endurance", c="耐久", m=2, r=3, col=1, s="changed", i="spell_shadow_shadowward", d="使你的疾跑和闪避技能冷却时间缩短60%。", dEn="Reduces the cooldown of your Sprint and Evasion abilities by 60%.", rq=nil}, {n="Riposte", c="还击", m=1, r=3, col=2, s="same", i="ability_warrior_challange", d="在招架了敌人的攻击之后可以使用的技能，对目标造成150%的武器伤害，并使其被缴械，持续6秒。", dEn="A strike that becomes active after parrying an opponent's attack. This attack deals 150% weapon damage and disarms the target for 6 sec.", rq={2, 2}}, {n="Improved Sprint", c="强化疾跑", m=2, r=3, col=4, s="same", i="ability_rogue_sprint", d="使你在启动疾跑技能时有100%的几率移除所有移动限制效果。", dEn="Gives a 100% chance to remove all movement impairing effects when you activate your Sprint ability.", rq=nil}, {n="Improved Kick", c="强化脚踢", m=2, r=4, col=1, s="same", i="ability_kick", d="使你的脚踢技能有100%的几率令目标沉默2秒。", dEn="Gives your Kick ability a 100% chance to Silence the target for 2 sec.", rq=nil}, {n="Flawless Execution", c="完美处刑", m=1, r=4, col=2, s="new", i="inv_sword_35", d="使你的刺骨消耗的能量值降低10点。", dEn="Reduces the Energy cost of your Eviscerate ability by 10.", rq=nil}, {n="Dual Wield Specialization", c="双武器专精", m=5, r=4, col=3, s="changed", i="ability_dualwield", d="使你的副手武器造成的伤害提高25%。", dEn="Increases the damage done by your off-hand weapon by 25%.", rq={2, 3}}, {n="Blade Flurry", c="剑刃乱舞", m=1, r=5, col=2, s="changed", i="ability_warrior_punishingblow", d="使你的近战攻击速度提高20%，并使你的近战攻击命中附近的一个额外对手。持续15秒。", dEn="Increases your melee attack speed by 20% and your melee attacks strike an additional nearby opponent. Lasts 15 sec.", rq=nil}, {n="Hack and Slash", c="劈斩", m=5, r=5, col=3, s="new", i="inv_sword_27", d="使你的近战武器攻击根据武器类型获得不同的加成。\n\n 斧/剑：你的近战攻击命中后有5%的几率对目标发动一次额外攻击。\n\n 匕首/拳套：使你的爆击几率提高5%。\n\n 锤：你的攻击无视目标15%的护甲。", dEn="Gives your melee weapon attacks a benefit depending on the weapon.\n\n Axe/Sword: Your successful\n melee attacks have a 5% chance\n to trigger an extra attack on the \n target.\n\n Dagger/Fist: Increases your\n critical strike chance by 5%.\n\n Mace: Your attacks ignore 15% of\n your target's armor.", rq=nil}, {n="Weapon Expertise", c="武器专家", m=2, r=6, col=2, s="changed", i="spell_holy_blessingofstrength", d="使你的攻击被躲闪或招架的几率降低2%。", dEn="Reduces the chance for your attacks to be Dodged or Parried by 2%.", rq={5, 2}}, {n="Aggression", c="侵略", m=3, r=6, col=3, s="changed", i="ability_racial_avatar", d="使你的影袭、背刺和刺骨技能的伤害提高6%。", dEn="Increases the damage of your Sinister Strike, Backstab, and Eviscerate abilities by 6%.", rq=nil}, {n="Adrenaline Rush", c="冲动", m=1, r=7, col=2, s="same", i="spell_shadow_shadowworddominate", d="使你的能量值回复速度提高100%，持续15秒。", dEn="Increases your Energy regeneration rate by 100% for 15 sec.", rq=nil}}}, {n="Subtlety", c="敏锐", t={{n="Camouflage", c="伪装", m=5, r=1, col=1, s="changed", i="ability_stealth", d="使你潜行时的移动速度惩罚降低15%，并使潜行的冷却时间缩短6秒。", dEn="Reduces your speed penalty from your Stealth ability by 15% and reduces its cooldown by 6 sec.", rq=nil}, {n="Master of Deception", c="欺诈高手", m=3, r=1, col=2, s="changed", i="spell_shadow_charm", d="当你在潜行状态下时，降低敌人侦测到你的几率，等同于你的等级提高了3级。", dEn="Reduces the chance enemies have to detect you while in Stealth mode as if you were 3 levels higher.", rq=nil}, {n="Opportunity", c="伺机而动", m=2, r=1, col=3, s="changed", i="ability_warrior_warcry", d="使你的背刺、绞喉、伏击和毁伤技能造成的伤害提高10%。", dEn="Increases the damage dealt by your Backstab, Garrote, Ambush, and Mutilate abilities by 10%.", rq=nil}, {n="Setup", c="调整", m=3, r=2, col=1, s="changed", i="spell_nature_mirrorimage", d="躲闪目标的攻击或完全抵抗目标的法术后，有100%的几率为该目标增加一个连击点。", dEn="Gives you a 100% chance to add a Combo Point to your target after Dodging one of their attacks or fully resisting one of their spells.", rq=nil}, {n="Elusiveness", c="飘忽不定", m=2, r=2, col=2, s="same", i="spell_magic_lesserinvisibilty", d="使你的消失和致盲技能的冷却时间缩短90秒。", dEn="Reduces the cooldown of your Vanish and Blind abilities by 90 sec.", rq=nil}, {n="Dirty Tricks", c="邪恶计谋", m=2, r=2, col=3, s="new", i="ability_sap", d="使你的闷棍和致盲技能消耗的能量值减少50%。", dEn="Reduces the Energy cost of your Sap and Blind abilities by 50%.", rq=nil}, {n="Improved Ambush", c="强化伏击", m=3, r=2, col=4, s="moved", i="ability_rogue_ambush", d="使你的伏击技能造成爆击的几率提高45%。", dEn="Increases the critical strike chance of your Ambush ability by 45%.", rq=nil}, {n="Initiative", c="先发制人", m=3, r=3, col=1, s="changed", i="spell_shadow_fumble", d="使你有100%的几率在使用伏击、绞喉或偷袭技能后获得1个额外的连击点数。", dEn="Gives you a 100% chance to add an additional combo point to your target when using your Ambush, Garrote, or Cheap Shot ability.", rq=nil}, {n="Ghostly Strike", c="鬼魅攻击", m=1, r=3, col=2, s="changed", i="spell_shadow_curse", d="打击敌人，造成125%（主手装备匕首时为180%）武器伤害，并使你的躲闪几率提高15%，持续7秒。奖励1个连击点。", dEn="A strike that deals 125% (180% if a Dagger is equipped in your Main Hand) weapon damage and increases your chance to dodge by 15% for 7 sec. Awards 1 combo point.", rq=nil}, {n="Improved Distract", c="强化扰乱", m=2, r=3, col=3, s="new", i="ability_rogue_distract", d="使你的扰乱技能的作用范围增加5码，并进一步降低被扰乱敌人的潜行侦测能力，使其相当于降低了2个等级。", dEn="Increases the radius of your Distract ability by 5 yds, and further reduces the Stealth detection of distracted enemies as though they were an additional 2 levels lower.", rq=nil}, {n="Heightened Senses", c="察觉", m=2, r=4, col=1, s="changed", i="ability_ambush", d="使你的潜行侦测相当于提高3级，并使你被法术和远程攻击命中的几率降低4%。", dEn="Increases your Stealth detection as if you were 3 levels higher and reduces your chance to be hit by spells and ranged attacks by 4%.", rq=nil}, {n="Premeditation", c="预谋", m=1, r=4, col=2, s="changed", i="spell_shadow_possession", d="为你的目标增加2个连击点数。你必须在20秒内增加或消耗这些连击点数，否则它们就会消失。", dEn="Adds 2 Combo Points to your target. You must add to or use those combo points within 20 sec or the combo points are lost.", rq=nil}, {n="Serrated Blades", c="锯齿利刃", m=3, r=4, col=3, s="changed", i="inv_sword_17", d="使你的攻击忽略目标9%的护甲，并使你的割裂技能造成的伤害提高30%。", dEn="Causes your attacks to ignore 9% of your target's Armor and increases the damage dealt by your Rupture ability by 30%.", rq=nil}, {n="Dirty Deeds", c="卑鄙", m=2, r=5, col=1, s="changed", i="spell_shadow_summonsuccubus", d="使你的偷袭和绞喉消耗的能量值降低20点，且绞喉不再要求你位于目标身后。", dEn="Reduces the Energy cost of your Cheap Shot and Garrote abilities by 20, and your Garrote ability no longer requires you to be behind your target.", rq=nil}, {n="Preparation", c="伺机待发", m=1, r=5, col=2, s="same", i="spell_shadow_antishadow", d="激活之后，这项技能立刻令你的其它潜行者技能的冷却时间结束。", dEn="When activated, this ability immediately finishes the cooldown on your other Rogue abilities.", rq=nil}, {n="Hemorrhage", c="出血", m=1, r=5, col=3, s="changed", i="spell_shadow_lifedrain", d="发动瞬发打击，造成100%武器伤害（装备匕首时为145%），并使目标受到来自游荡者的割裂伤害提高15%，持续15秒。奖励1个连击点数。", dEn="An instant strike that deals 100% weapon damage (145% if a Dagger is equipped) and causes the target to take 15% increased Rupture damage from the Rogue. Lasts 15 sec. Awards 1 Combo Point.", rq={4, 3}}, {n="Quietus", c="寂灭", m=5, r=6, col=1, s="new", i="ability_rogue_garrote", d="你的邪恶攻击、鬼魅攻击和出血对生命值低于35%的目标造成的伤害提高10%。", dEn="Your Sinister Strike, Ghostly Strike, and Hemorrhage abilities cause 10% more damage against targets below 35% health.", rq={5, 1}}, {n="Cutthroat", c="割喉", m=5, r=6, col=3, s="new", i="classicon_rogue", d="你的背刺有15%的几率使你在10秒内的下一个伏击不需要潜行。", dEn="Your Backstab has a 15% chance to cause your next Ambush within 10 sec to not require Stealth.", rq=nil}, {n="Thousand Cuts", c="千刀万剐", m=1, r=7, col=2, s="new", i="ability_rogue_rupture", d="当你的割裂造成周期性伤害时，使你在10秒内下一次出血或背刺消耗的能量值降低3点，最多叠加5次。", dEn="When your Rupture ability deals periodic damage, the Energy cost of your next Hemorrhage or Backstab ability within 10 sec is reduced by 3, stacking up to 5 times.", rq={5, 2}}}}},
    Priest = {{n="Discipline", c="戒律", t={{n="Power in Light", c="圣光之力", m=5, r=1, col=1, s="new", i="spell_holy_searinglight", d="你的惩击和苦修法术对受到神圣之火影响的目标造成的伤害提高10%。", dEn="Your Smite and Penance spells deal 10% increased damage to targets afflicted with your Holy Fire.", rq=nil}, {n="Wand Specialization", c="魔杖专精", m=2, r=1, col=2, s="changed", i="inv_wand_01", d="使你的魔杖造成的伤害提高25%。", dEn="Increases your damage with Wands by 25%.", rq=nil}, {n="Twin Disciplines", c="双生戒律", m=5, r=1, col=3, s="new", i="spell_holy_sealofvengeance", d="使你的瞬发法术的伤害和治疗效果提高5%。", dEn="Increases the damage and healing of your instant cast spells by 5%.", rq=nil}, {n="Silent Resolve", c="无声消退", m=3, r=2, col=1, s="changed", i="spell_nature_manaregentotem", d="使你的神圣法术产生的威胁值降低30%，并使你受到的昏迷、恐惧和沉默效果的持续时间缩短15%。", dEn="Reduces the threat generated by your Holy spells by 30% and reduces the duration of Stun, Fear, and Silence effects inflicted on you by 15%.", rq=nil}, {n="Holy Precision", c="神圣精准", m=3, r=2, col=2, s="new", i="spell_holy_divineillumination", d="使你的神圣法术命中几率提高18%。", dEn="Improves your chance to hit with Holy spells by 18%.", rq=nil}, {n="Improved Power Word: Shield", c="强化真言术：盾", m=3, r=2, col=3, s="changed", i="spell_holy_powerwordshield", d="使你的真言术：盾所吸收的伤害量提高20%。", dEn="Increases the damage absorbed by your Power Word: Shield by 20%.", rq=nil}, {n="Martyrdom", c="殉难", m=2, r=2, col=4, s="changed", i="spell_nature_tranquility", d="使你有100%的几率在受到敌人的近战或远程爆击后得到专注施法，持续6秒。专注施法效果可以让你在施法时不会因为受到伤害而延长施法时间，且令你抵抗打断效果的几率提高20%。", dEn="Gives you a 100% chance to gain Focused Casting for 6 sec after being the victim of a melee or ranged critical strike. The Focused Casting effect prevents you from losing casting time when taking damage and increases your resistance to Interrupt effects by 20%.", rq=nil}, {n="Mental Agility", c="精神敏锐", m=3, r=3, col=1, s="changed", i="ability_hibernation", d="使你的惩击、神圣之火和瞬发法术消耗的法力值降低10%。", dEn="Reduces the mana cost of your Smite, Holy Fire, and instant cast spells by 10%.", rq=nil}, {n="Inner Focus", c="心灵专注", m=1, r=3, col=2, s="changed", i="spell_frost_windwalkon", d="激活后，使你的下一个法术的法力消耗降低100%；若它是可以造成爆击效果的非周期性法术，其爆击几率还会提高25%。", dEn="When activated, reduces the Mana cost of your next spell by 100% and increases its critical effect chance by 25% if it is a non-periodic spell and capable of a critical effect.", rq=nil}, {n="Meditation", c="冥想", m=3, r=3, col=4, s="changed", i="spell_nature_sleep", d="使你在施法时仍保持50%的法力值恢复速度。", dEn="Allows 50% of your Mana regeneration to continue while casting.", rq=nil}, {n="Improved Inner Fire", c="强化心灵之火", m=3, r=4, col=1, s="changed", i="spell_holy_innerfire", d="使你的心灵之火的护甲值加成提高45%，并使其总充能次数提高12次。", dEn="Increases the Armor bonus of your Inner Fire spell by 45% and increases its total charges by 12.", rq=nil}, {n="Mental Strength", c="心灵之力", m=5, r=4, col=2, s="changed", i="spell_nature_enchantarmor", d="使你的智力总值提高15%。", dEn="Increases your total Intellect by 15%.", rq=nil}, {n="Soul Warding", c="灵魂守护", m=1, r=4, col=3, s="new", i="spell_holy_pureofheart", d="使你的真言术：盾冷却时间缩短4秒，法力消耗降低15%。", dEn="Reduces the cooldown on your Power Word: Shield spell by 4 sec and reduces its mana cost by 15%.", rq={2, 3}}, {n="Improved Mana Burn", c="强化法力燃烧", m=2, r=4, col=4, s="changed", i="spell_shadow_manaburn", d="使你的法力燃烧的施法时间缩短1秒。", dEn="Reduces the casting time of your Mana Burn spell by 1 sec.", rq=nil}, {n="Penance", c="苦修", m=1, r=5, col=2, s="new", i="spell_holy_penance", d="向目标释放圣光能量，立即对一名敌人造成81点神圣伤害，或为一名盟友恢复184点生命值，并在接下来的2秒内每1秒重复一次效果。", dEn="Launches a volley of holy light at the target, causing 81 Holy damage to an enemy, or 184 healing to an ally, instantly and every 1 sec for 2 sec.", rq=nil}, {n="Renewed Hope", c="新生希望", m=5, r=5, col=3, s="new", i="spell_holy_holyprotection", d="你对具有虚弱灵魂的目标施放的快速治疗、联结治疗、次级治疗术、治疗术、强效治疗术和苦修的爆击几率提高10%，并使目标身上虚弱灵魂的剩余持续时间缩短5秒。", dEn="Your heals from Flash Heal, Binding Heal, Lesser Heal, Heal, Greater Heal, and Penance gain 10% increased critical strike chance when cast on targets with Weakened Soul, and reduce the remaining duration of Weakened Soul on their target by 5 sec.", rq={4, 3}}, {n="Divine Aegis", c="神圣庇护", m=3, r=6, col=3, s="new", i="spell_holy_devineaegis", d="你的极效治疗会在目标身上生成一道保护性护盾，吸收相当于治疗量15%的伤害。持续12秒。", dEn="Your critical heals create a protective shield on the target, absorbing 15% of the amount healed. Lasts 12 sec.", rq=nil}, {n="Power Infusion", c="能量灌注", m=1, r=7, col=2, s="changed", i="spell_holy_powerinfusion", d="为目标注入能量，使其法术伤害和治疗量提高20%，持续15秒。", dEn="Infuses the target with power, increasing their spell damage and healing done by 20% for 15 sec.", rq={5, 2}}}}, {n="Holy", c="神圣", t={{n="Twilight Focus", c="暮光专注", m=3, r=1, col=1, s="changed", i="spell_holy_healingfocus", d="使你在施放任何法术时有70%的几率避免因受到伤害而被打断。", dEn="Gives you a 70% chance to avoid interruption caused by damage while casting any spell.", rq=nil}, {n="Improved Renew", c="强化恢复", m=3, r=1, col=2, s="same", i="spell_holy_renew", d="使你的恢复法术的治疗效果提高15%。", dEn="Increases the amount healed by your Renew spell by 15%.", rq=nil}, {n="Holy Specialization", c="神圣专精", m=5, r=1, col=3, s="same", i="spell_holy_sealofsalvation", d="使你的神圣法术造成爆击的几率提高5%。", dEn="Increases the critical effect chance of your Holy spells by 5%.", rq=nil}, {n="Spell Warding", c="法术屏障", m=5, r=2, col=2, s="same", i="spell_holy_spellwarding", d="使你受到的所有法术伤害降低10%。", dEn="Reduces all spell damage taken by 10%.", rq=nil}, {n="Divine Fury", c="神圣之怒", m=5, r=2, col=3, s="same", i="spell_holy_sealofwrath", d="使你的惩击、神圣之火、治疗术和强效治疗术的施法时间缩短0.5秒。", dEn="Reduces the casting time of your Smite, Holy Fire, Heal, and Greater Heal spells by 0.5 sec.", rq=nil}, {n="Holy Nova", c="神圣新星", m=1, r=3, col=1, s="changed", i="spell_holy_holynova", d="在施法者周围引发一场圣光爆炸，对10码内的所有敌方目标造成26到30点神圣伤害，并为10码内的所有小队成员恢复49到57点生命值。这些效果不产生威胁值。", dEn="Causes an explosion of holy light around the caster, causing 26 to 30 Holy damage to all enemy targets within 10 yards and healing all party members within 10 yards for 49 to 57. These effects cause no threat.", rq=nil}, {n="Blessed Recovery", c="神恩回复", m=3, r=3, col=2, s="changed", i="spell_holy_blessedrecovery", d="在遭受近战或远程爆击，或单次攻击受到超过最大生命值30%的伤害后，在6秒内恢复相当于所受伤害25%的生命值。刷新该效果时会保留剩余治疗量。", dEn="After being struck by a melee or ranged critical hit, or suffering more than 30% of your maximum Health from a single attack, heal 25% of the damage taken over 6 sec. Refreshing this effect carries over any remaining healing.", rq=nil}, {n="Inspiration", c="灵感", m=3, r=3, col=4, s="changed", i="spell_holy_layonhands", d="你的非周期性治疗爆击会使目标的护甲值提高25%，持续15秒。", dEn="Your non-periodic critical heals increase your target's Armor by 25% for 15 sec.", rq=nil}, {n="Holy Reach", c="神圣延伸", m=2, r=4, col=1, s="same", i="spell_holy_purify", d="使你的惩击和神圣之火的射程、治疗祷言和神圣新星的作用半径提高20%。", dEn="Increases the range of your Smite and Holy Fire spells and the radius of your Prayer of Healing and Holy Nova spells by 20%.", rq=nil}, {n="Improved Healing", c="强化治疗术", m=3, r=4, col=2, s="changed", i="spell_holy_heal02", d="使你的次级治疗术、治疗术、强效治疗术、苦修和愈合祷言的法力消耗降低15%。", dEn="Reduces the Mana cost of your Lesser Heal, Heal, Greater Heal, Penance, and Prayer of Mending spells by 15%.", rq=nil}, {n="Searing Light", c="灼热之光", m=2, r=4, col=3, s="changed", i="spell_holy_searinglightpriest", d="使你造成的神圣伤害提高5%，并且每次神圣之火造成周期性伤害时，有10%的几率使你的下一个神圣新星不消耗法力值。", dEn="Increases your Holy damage done by 5%, and gives a 10% chance each time your Holy Fire spell deals periodic damage for your next Holy Nova to cost no Mana.", rq={2, 3}}, {n="Binding Heal", c="联结治疗", m=1, r=4, col=4, s="new", i="spell_holy_blindingheal", d="为友方目标和施法者各恢复236到284点生命值。低威胁值。", dEn="Heals a friendly target and the caster for 236 to 284. Low threat.", rq=nil}, {n="Litany of Light", c="圣光连祷", m=2, r=5, col=1, s="new", i="inv_scroll_07", d="当你施放治疗法术时，若你上一次施放的是不同的治疗法术，则获得相当于本次法术基础法力消耗10%的法力值。", dEn="When you cast a healing spell, gain Mana equal to 10% of the base cost of the spell if your previous heal was a different spell.", rq=nil}, {n="Spirit of Redemption", c="救赎之魂", m=1, r=5, col=2, s="changed", i="inv_enchant_essenceeternallarge", d="在死亡时，牧师变成一个救赎之魂，持续15秒。救赎之魂无法移动、攻击，也不会受到任何法术或效果的影响。在这个形态下，牧师可以施放任何治疗法术，不需消耗任何法力值。当救赎之魂效果结束时，牧师死亡。", dEn="Upon death, the priest becomes the Spirit of Redemption for 15 sec. The Spirit of Redemption cannot move, attack, be attacked or targeted by any spells or effects. While in this form the priest can cast any healing spell free of cost. When the effect ends, the priest dies.", rq=nil}, {n="Spiritual Guidance", c="精神指引", m=5, r=5, col=3, s="changed", i="spell_holy_spiritualguidence", d="使你的法术治疗量最多提高相当于你精神总值的25%，法术伤害最多提高相当于你精神总值的8%。", dEn="Increases your spell healing by up to 25% of your total Spirit and your spell damage by up to 8% of your total Spirit.", rq=nil}, {n="Spiritual Healing", c="精神治疗", m=3, r=6, col=3, s="changed", i="spell_nature_moonglow", d="使你的法术治疗量提高10%。", dEn="Increases the amount healed by your spells by 10%.", rq=nil}, {n="Prayer of Mending", c="愈合祷言", m=1, r=7, col=2, s="new", i="spell_holy_prayerofmendingtga", d="向目标施加一个法术，在该目标下一次受到伤害或获得非周期性治疗时为其恢复172点生命值。这个治疗效果发生之后，愈合祷言会转移到20码范围内的小队或团队成员身上。最多可以转移5次，每次转移之后持续30秒。每个施法者在同一时间内只能在一名目标身上施放该法术。", dEn="Places a spell on the target that heals them for 172 the next time they take damage or receive non-periodic healing. When the heal occurs, Prayer of Mending jumps to a party or raid member within 20 yards. Jumps up to 5 times and lasts 30 sec after each jump. This spell can only be placed on one target at a time per caster.", rq={5, 2}}}}, {n="Shadow", c="Shadow", t={{n="Shadow Focus", c="暗影集中", m=5, r=1, col=1, s="changed", i="spell_shadow_burningspirit", d="使你的暗影法术命中几率提高5%。", dEn="Improves your chance to hit with Shadow spells by 5%.", rq=nil}, {n="Blackout", c="昏阙", m=5, r=1, col=2, s="same", i="spell_shadow_gathershadows", d="使你的暗影系伤害性法术有10%的几率令目标昏迷3秒。", dEn="Gives your Shadow damage spells a 10% chance to stun the target for 3 sec.", rq=nil}, {n="Spirit Tap", c="精神分流", m=5, r=1, col=3, s="changed", i="spell_shadow_requiem", d="杀死有意义的目标，或受你的吸血鬼的拥抱影响的敌人死亡时，你有100%的几率使精神提高100%，持续15秒。在此期间，施法时仍保持50%的法力回复速度。", dEn="Gives you a 100% chance to increase your Spirit by 100% for 15 sec after killing a non-trivial target or when an enemy afflicted by your Vampiric Embrace dies. For the duration, 50% of your Mana regeneration will continue while casting.", rq=nil}, {n="Shadow Affinity", c="暗影亲和", m=3, r=2, col=1, s="changed", i="spell_shadow_shadowward", d="使你的暗影法术造成的威胁值降低30%。", dEn="Reduces the threat generated by your Shadow spells by 30%.", rq=nil}, {n="Improved Shadow Word: Pain", c="强化暗言术：痛", m=2, r=2, col=3, s="same", i="spell_shadow_shadowwordpain", d="使你的暗言术：痛的持续时间延长6秒。", dEn="Increases the duration of your Shadow Word: Pain spell by 6 sec.", rq=nil}, {n="Shadow Reach", c="暗影延伸", m=2, r=2, col=4, s="changed", i="spell_shadow_chilltouch", d="使你的暗影系伤害性法术的射程提高20%。", dEn="Increases the range of your offensive Shadow spells by 20%.", rq=nil}, {n="Improved Mind Blast", c="强化心灵震爆", m=5, r=3, col=1, s="same", i="spell_shadow_unholyfrenzy", d="使你的心灵震爆的冷却时间减少2.5秒。", dEn="Reduces the cooldown of your Mind Blast spell by 2.5 sec.", rq=nil}, {n="Improved Psychic Scream", c="强化心灵尖啸", m=2, r=3, col=2, s="same", i="spell_shadow_psychicscream", d="使你的心灵尖啸的冷却时间减少4秒。", dEn="Reduces the cooldown of your Psychic Scream spell by 4 sec.", rq={1, 2}}, {n="Mind Flay", c="精神鞭笞", m=1, r=3, col=3, s="changed", i="spell_shadow_siphonmana", d="以暗影能量冲击目标的心灵，在3秒内造成63点暗影伤害，并使其移动速度降低50%。", dEn="Assault the target's mind with Shadow energy, causing 63 Shadow damage over 3 sec and slowing their movement speed by 50%.", rq=nil}, {n="Improved Mind Flay", c="强化精神鞭笞", m=2, r=3, col=4, s="new", i="spell_shadow_soulleech_2", d="你的精神鞭笞现在造成的伤害提高20%，射程提高10码，但会使目标的移动速度降低20%。", dEn="Your Mind Flay now deals 20% more damage, gains 10 yards increased range, but slows the target's movement speed by 20%.", rq={3, 3}}, {n="Improved Fade", c="强化渐隐术", m=2, r=4, col=1, s="same", i="spell_magic_lesserinvisibilty", d="使你的渐隐术的冷却时间减少6秒。", dEn="Decreases the cooldown of your Fade ability by 6 sec.", rq=nil}, {n="Vampiric Embrace", c="吸血鬼的拥抱", m=1, r=4, col=2, s="changed", i="spell_shadow_unsummonbuilding", d="暗影魔法的能量笼罩你的目标，使你对其造成的暗影伤害总量的20%转而治疗所有队友。效果持续30秒。", dEn="Afflicts your target with Shadow energy that causes all party members to be healed for 20% of any Shadow spell damage you deal for 30 sec.", rq=nil}, {n="Shadow Weaving", c="暗影之波", m=3, r=4, col=3, s="changed", i="spell_shadow_blackplague", d="你的暗影伤害法术有100%的几率使你造成的暗影伤害提高2%，持续15秒，最多叠加5次。", dEn="Your Shadow damage spells have a 100% chance to increase the Shadow damage you deal by 2% for 15 sec, stacking up to 5 times.", rq=nil}, {n="Silence", c="沉默", m=1, r=5, col=1, s="changed", i="spell_shadow_impphaseshift", d="使目标沉默，在5秒内无法施法，并打断其施法，持续3秒。", dEn="Silences the target, preventing them from casting spells for 5 sec and interrupting their spellcasts for 3 sec.", rq=nil}, {n="Devouring Contagion", c="噬灵传染", m=2, r=5, col=3, s="new", i="spell_shadow_devouringplague", d="使你的噬灵瘟疫的法力消耗降低50%。\n\n在噬灵瘟疫生效期间死亡的目标会将其传播出去，跳到10码内的一个敌人身上，持续剩余时间。", dEn="Reduces the mana cost of your Devouring Plague by 50%.\n\nTargets that die while Devouring Plague is active spreads it, jumping to a nearby enemy within 10 yds for the remaining duration.", rq=nil}, {n="Early Demise", c="提早离世", m=2, r=6, col=1, s="new", i="spell_shadow_demonicfortitude", d="对生命值等于或低于20%的目标，使暗言术：灭的爆击几率提高30%。", dEn="Increases Shadow Word: Death's critical strike chance on targets at or below 20% health by 30%.", rq=nil}, {n="Darkness", c="黑暗", m=5, r=6, col=3, s="changed", i="spell_shadow_twilight", d="你造成的暗影伤害提高10%。", dEn="Increases your Shadow damage done by 10%.", rq=nil}, {n="Shadowform", c="暗影形态", m=1, r=7, col=2, s="changed", i="spell_shadow_shadowform", d="进入暗影形态，使你的暗影伤害提高10%，所有暗影法术消耗的法力值降低50%，暗影法术的爆击伤害加成提高100%，你受到的物理伤害降低15%。但是在此形态下，你无法施放治疗法术。", dEn="Assume Shadowform, increasing your Shadow damage by 10%, reducing the Mana cost of all Shadow spells by 50%, increasing the critical strike damage bonus of your Shadow spells by 100%, and reducing Physical damage taken by you by 15%. However, you may not cast healing spells while in this form.", rq={4, 2}}}}},
    Shaman = {{n="Elemental", c="Elemental", t={{n="Convection", c="传导", m=5, r=1, col=2, s="changed", i="spell_nature_wispsplode", d="使你的震击、闪电箭、熔岩爆裂和闪电链的法力消耗降低10%。", dEn="Reduces the mana cost of your Shock, Lightning Bolt, Lava Burst, and Chain Lightning spells by 10%.", rq=nil}, {n="Concussion", c="震荡", m=5, r=1, col=3, s="changed", i="spell_nature_earthshock", d="使你的闪电箭、闪电链和大地震击造成的伤害提高5%。", dEn="Increases the damage done by your Lightning Bolt, Chain Lightning, and Earth Shock spells by 5%.", rq=nil}, {n="Elemental Warding", c="元素防护", m=3, r=2, col=1, s="changed", i="spell_nature_spiritarmor", d="受到的火焰、冰霜和自然效果伤害降低10%。", dEn="Reduces damage taken from Fire, Frost, and Nature effects by 10%.", rq=nil}, {n="Reverberation", c="回响", m=5, r=2, col=2, s="moved", i="spell_frost_frostward", d="使你的震击法术的冷却时间减少1秒。", dEn="Reduces the cooldown of your Shock spells by 1 sec.", rq=nil}, {n="Call of Flame", c="烈焰召唤", m=3, r=2, col=3, s="changed", i="spell_fire_immolation", d="使你的火焰图腾以及烈焰震击、火焰新星和熔岩爆裂造成的伤害提高15%。", dEn="Increases the damage done by your Fire Totems and by your Flame Shock, Fire Nova, and Lava Burst spells by 15%.", rq=nil}, {n="Elemental Devastation", c="元素浩劫", m=3, r=2, col=4, s="changed", i="spell_fire_elementaldevastation", d="你的进攻性法术造成爆击时，会使你的近战攻击爆击几率提高9%，持续10秒。", dEn="Your offensive spell critical strikes will increase your chance to get a critical strike with melee attacks by 9% for 10 sec.", rq=nil}, {n="Elemental Focus", c="元素集中", m=1, r=3, col=2, s="same", i="spell_shadow_manaburn", d="使你有10%的几率在施放任何火焰、冰霜或自然系的伤害性法术之后进入节能施法状态。这个状态可以使你的下一个伤害性法术所消耗的法力值减少100%。", dEn="Gives you a 10% chance to enter a Clearcasting state after casting any Fire, Frost, or Nature damage spell. The Clearcasting state reduces the mana cost of your next damage spell by 100%.", rq=nil}, {n="Elemental Alacrity", c="元素迅捷", m=3, r=3, col=3, s="changed", i="spell_lightning_lightningbolt01", d="使你的闪电箭、闪电链和熔岩爆裂的施法时间缩短0.50秒。", dEn="Reduces the cast time of your Lightning Bolt, Chain Lightning, and Lava Burst spells by 0.50 sec.", rq=nil}, {n="Improved Fire Nova", c="强化火焰新星", m=2, r=4, col=1, s="changed", i="spell_fire_sealoffire", d="使你的火焰新星造成的伤害提高20%，冷却时间缩短4秒。", dEn="Increases the damage done by your Fire Nova spell by 20% and reduces its cooldown by 4 sec.", rq=nil}, {n="Eye of the Storm", c="风暴之眼", m=3, r=4, col=2, s="changed", i="spell_nature_eyeofthestorm", d="使你在施放闪电箭、闪电链和熔岩爆裂时因受到伤害而遭受的施法推延降低70%。", dEn="Reduces the pushback suffered from damaging attacks while casting Lightning Bolt, Chain Lightning, and Lava Burst by 70%.", rq=nil}, {n="Call of Thunder", c="雷霆召唤", m=1, r=4, col=3, s="changed", i="spell_nature_callstorm", d="使你的闪电箭和闪电链的爆击几率提高3%。", dEn="Increases the critical strike chance of your Lightning Bolt and Chain Lightning spells by 3%.", rq={3, 3}}, {n="Elemental Reach", c="元素射程", m=2, r=5, col=1, s="changed", i="spell_nature_stormreach", d="使你的闪电箭、闪电链、火焰新星和熔岩爆裂的射程提高6码，烈焰震击的射程提高15码。", dEn="Increases the range of your Lightning Bolt, Chain Lightning, Fire Nova, and Lava Burst spells by 6 yards, and increases the range of your Flame Shock spell by 15 yards.", rq=nil}, {n="Lightning Overload", c="闪电超载", m=3, r=5, col=2, s="new", i="spell_nature_lightningoverload", d="你的闪电箭和闪电链有10%的几率对同一目标施放第二个类似法术，不消耗额外法力，只造成一半伤害且不产生威胁。", dEn="Gives your Lightning Bolt and Chain Lightning spells a 10% chance to cast a second, similar spell on the same target at no additional cost that causes half damage and no threat.", rq=nil}, {n="Earthbound", c="地缚", m=1, r=5, col=4, s="new", i="spell_nature_stranglevines", d="施放地缚图腾时，使附近目标无法移动5秒。", dEn="Your Earthbind Totem Immobilizes nearby targets for 5 sec when cast.", rq=nil}, {n="Elemental Fury", c="元素之怒", m=5, r=6, col=3, s="changed", i="spell_fire_volcano", d="使你的灼热图腾、熔岩图腾以及你的火焰、冰霜和自然系法术的爆击伤害加成提高100%。", dEn="Increases the critical strike damage bonus of your Searing and Magma Totems and your Fire, Frost, and Nature spells by 100%.", rq={4, 3}}, {n="Lava Burst", c="熔岩爆裂", m=1, r=7, col=2, s="new", i="spell_shaman_lavaburst", d="你向目标投掷熔岩，造成150到192点火焰伤害。如果目标身上有你的烈焰震击，熔岩爆裂的伤害提高20%。", dEn="You hurl molten lava at the target, dealing 150 to 192 Fire damage. If your Flame Shock is on the target, Lava Burst deals 20% increased damage.", rq={5, 2}}}}, {n="Enhancement", c="增强", t={{n="Earth's Grasp", c="大地之握", m=2, r=1, col=1, s="moved", i="spell_nature_stoneclawtotem", d="使你的石爪图腾的生命值提高50%，地缚图腾的影响范围增加20%。", dEn="Increases the health of your Stoneclaw Totem by 50% and the radius of your Earthbind Totem by 20%.", rq=nil}, {n="Thundering Strikes", c="雷鸣猛击", m=5, r=1, col=2, s="changed", i="ability_thunderbolt", d="使你的所有法术和攻击的爆击几率提高5%。", dEn="Improves your chance to get a critical strike with all spells and attacks by 5%.", rq=nil}, {n="Ancestral Knowledge", c="先祖知识", m=5, r=1, col=3, s="changed", i="spell_shadow_grimward", d="使你的智力值提高10%。", dEn="Increases your Intellect by 10%.", rq=nil}, {n="Guardian Totems", c="守护图腾", m=2, r=2, col=1, s="same", i="spell_nature_stoneskintotem", d="使你的石肤图腾和风墙图腾所能吸收的伤害提高20%，根基图腾的冷却时间减少2秒。", dEn="Increases the amount of damage reduced by your Stoneskin Totem and Windwall Totem by 20% and reduces the cooldown of your Grounding Totem by 2 sec.", rq=nil}, {n="Mental Dexterity", c="聪慧", m=3, r=2, col=2, s="new", i="spell_nature_mentalquickness", d="使你的攻击强度提高，数值相当于你智力的100%。", dEn="Increases your Attack Power by an amount equal to 100% of your Intellect.", rq=nil}, {n="Improved Ghost Wolf", c="强化幽魂之狼", m=2, r=2, col=3, s="changed", i="spell_nature_spiritwolf", d="使你的幽魂之狼法术的施法时间缩短3秒，且可在室内使用。", dEn="Reduces the cast time of your Ghost Wolf spell by 3 sec, and Ghost Wolf may be used indoors.", rq=nil}, {n="Improved Lightning Shield", c="强化闪电之盾", m=3, r=2, col=4, s="same", i="spell_nature_lightningshield", d="使你的闪电之盾法术所造成的伤害提高15%。", dEn="Increases the damage done by your Lightning Shield orbs by 15%.", rq=nil}, {n="Elemental Weapons", c="元素武器", m=3, r=3, col=1, s="moved", i="spell_fire_flametounge", d="使你的石化武器所提供的近战攻击强度加成提高20%，风怒武器所提供的近战攻击强度加成提高40%，火舌武器和冰封武器所造成的伤害提高15%。", dEn="Increases the melee attack power bonus of your Rockbiter Weapon by 20%, your Windfury Weapon effect by 40% and increases the damage caused by your Flametongue Weapon and Frostbrand Weapon by 15%.", rq=nil}, {n="Shamanistic Focus", c="萨满专注", m=1, r=3, col=3, s="new", i="spell_nature_elementalabsorption", d="使你的震击和闪电之盾消耗的法力值降低45%。", dEn="Reduces the mana cost of your Shock and Lightning Shield spells by 45%.", rq=nil}, {n="Anticipation", c="预知", m=3, r=3, col=4, s="changed", i="spell_nature_mirrorimage", d="使你的躲闪几率提高6%。", dEn="Increases your chance to dodge by an additional 6%.", rq=nil}, {n="Toughness", c="坚韧", m=5, r=4, col=1, s="changed", i="spell_holy_devotion", d="使你的耐力提高10%。", dEn="Increases your Stamina by 10%.", rq=nil}, {n="Flurry", c="乱舞", m=5, r=4, col=2, s="changed", i="ability_ghoulfrenzy", d="近战攻击造成爆击后，使你接下来的3次攻击的攻击速度提高25%。", dEn="Increases your attack speed by 25% for your next 3 swings after dealing a melee critical strike.", rq={2, 2}}, {n="Stormstrike", c="风暴打击", m=1, r=4, col=3, s="changed", i="ability_shaman_stormstrike", d="立即打击，造成普通武器伤害，并使你下一次用闪电箭、闪电链或大地震击对该目标造成的伤害提高20%，持续12秒。", dEn="Instantly strike for normal weapon damage and increase the damage you deal to the target with your next Lightning Bolt, Chain Lightning, or Earth Shock spell by 20% for 12 sec.", rq=nil}, {n="Spirit Weapons", c="灵魂武器", m=1, r=5, col=1, s="changed", i="ability_parry", d="有几率招架敌人的近战攻击。未激活石化武器时，你的攻击产生的威胁值降低30%；激活石化武器时，产生的所有威胁值提高30%。", dEn="Gives a chance to parry enemy melee attacks, reduces all threat generated by your attacks by 30% while Rockbiter Weapon is not active, and increases all threat generated by 30% while Rockbiter Weapon is active.", rq=nil}, {n="Mental Quickness", c="精神敏锐", m=2, r=5, col=2, s="new", i="spell_nature_sleep", d="使你的法术伤害和治疗效果最多提高相当于你智力30%的数值。", dEn="Increases your spell damage and healing by up to 30% of your Intellect.", rq=nil}, {n="Improved Stormstrike", c="强化风暴打击", m=2, r=5, col=3, s="new", i="spell_shaman_improvedstormstrike", d="使用风暴打击时，你有100%的几率获得50%的施法时法力回复，持续15秒；每当你躲闪或招架时，风暴打击的冷却时间有100%的几率重置。", dEn="When you Stormstrike, you have a 100% chance to gain 50% mana regeneration while casting spells for 15 sec, and Stormstrike's cooldown has a 100% chance to reset each time you Dodge or Parry.", rq={4, 3}}, {n="Maelstrom Weapon", c="漩涡武器", m=5, r=6, col=3, s="new", i="spell_shaman_maelstromweapon", d="近战攻击造成伤害时，你有几率使下一个闪电箭的施法时间和法力消耗降低20%。最多叠加5次。持续30秒。", dEn="When you deal damage with a melee attack, you have a chance to reduce the cast time and Mana cost of your next Lightning Bolt spell by 20%. Stacks up to 5 times. Lasts 30 sec.", rq=nil}, {n="Rage of the Farseer", c="先知之怒", m=1, r=7, col=2, s="new", i="spell_nature_bloodlust", d="使你的攻击速度提高30%，持续25秒。", dEn="Increases your attack speed by 30% for 25 sec.", rq={5, 2}}}}, {n="Restoration", c="恢复", t={{n="Improved Healing Wave", c="强化治疗波", m=5, r=1, col=2, s="same", i="spell_nature_magicimmunity", d="使你的治疗波的施法时间减少0.5秒。", dEn="Reduces the casting time of your Healing Wave spell by 0.5 sec.", rq=nil}, {n="Totemic Focus", c="图腾集中", m=5, r=1, col=3, s="changed", i="spell_nature_moonglow", d="使你的图腾以及任何召唤或移动图腾的法术所消耗的法力值降低25%。", dEn="Reduces the Mana cost of your totems and any spells that summon or move them by 25%.", rq=nil}, {n="Mindfulness", c="全神贯注", m=3, r=2, col=1, s="new", i="spell_nature_sleep", d="使你在施法时仍保持50%的法力值恢复速度。", dEn="Allows 50% of your Mana regeneration to continue while casting.", rq=nil}, {n="Natural Grace", c="自然优雅", m=3, r=2, col=2, s="changed", i="spell_nature_healingtouch", d="使你的法术造成的威胁值降低15%。", dEn="Reduces the threat generated by your spells by 15%.", rq=nil}, {n="Tidal Focus", c="潮汐集中", m=5, r=2, col=3, s="changed", i="spell_frost_manarecharge", d="使你的治疗法术法力消耗降低5%，并使你的命中几率提高5%。", dEn="Reduces the Mana cost of your healing spells by 5% and improves your chance to hit by 5%.", rq=nil}, {n="Improved Reincarnation", c="强化复生", m=2, r=2, col=4, s="changed", i="spell_nature_reincarnation", d="使你的复生法术冷却时间缩短20分钟，最大生命值提高4%，并使你复生时获得的生命值和法力值额外提高20%。", dEn="Reduces the cooldown of your Reincarnation spell by 20 min, increases your maximum health by 4%, and increases the amount of health and Mana you reincarnate with by an additional 20%.", rq=nil}, {n="Ancestral Healing", c="先祖治疗", m=3, r=3, col=1, s="moved", i="spell_nature_undyingstrength", d="在你的任何一个治疗法术对目标造成极效治疗效果后，使目标因装备而获得的护甲值提高25%，持续15秒。", dEn="Increases your target's armor value by 25% for 15 sec after getting a critical effect from one of your healing spells.", rq=nil}, {n="Healing Focus", c="治疗专注", m=3, r=3, col=2, s="changed", i="spell_nature_healingwavelesser", d="使你在施放任意治疗法术的时候有70%的几率避免因受到伤害而被打断。", dEn="Gives you a 70% chance to avoid interruption caused by damage while casting any healing spell.", rq=nil}, {n="Water Shield", c="水之护盾", m=1, r=3, col=3, s="new", i="ability_shaman_watershield", d="施法者被3个水球环绕。当法术、近战或远程攻击命中施法者，或施法者的治疗法术造成爆击时，恢复最大法力值的2%，并消耗一个水球。每隔数秒只会有一个水球被激活。持续10分钟。\n\n萨满祭司在同一时间只能激活一种元素之盾。", dEn="The caster is surrounded by 3 globes of water. When a spell, melee, or ranged attack hits the caster or when one of the caster's healing spells gets a critical result, 2% of maximum mana is restored to the caster, expending one water globe. Only one globe will activate every few seconds. Lasts 10 min.\n\nOnly one Elemental Shield can be active on the Shaman at any one time.", rq=nil}, {n="Tidal Mastery", c="潮汐掌握", m=5, r=4, col=1, s="changed", i="spell_nature_tranquility", d="使你的治疗法术产生极效治疗的几率提高5%。", dEn="Increases the critical effect chance of your healing spells by 5%.", rq=nil}, {n="Restorative Totems", c="恢复图腾", m=5, r=4, col=2, s="changed", i="spell_nature_manaregentotem", d="使你的法力之泉图腾的效果提高25%，治疗之泉图腾的效果提高50%。", dEn="Increases the effect of your Mana Spring Totem by 25% and increases the effect of your Healing Stream Totem by 50%.", rq=nil}, {n="Mana Tide Totem", c="法力之潮图腾", m=1, r=4, col=3, s="changed", i="spell_frost_summonwaterelemental", d="在施法者身边召唤一个生命值为5点的法力之潮图腾，持续12秒。它可以为半径30码范围内的小队成员每3秒回复88点法力值。", dEn="Summons a Mana Tide Totem with 5 health at the feet of the caster for 12 sec that restores 88 mana every 3 seconds to group members within 30 yards.", rq=nil}, {n="Healing Way", c="治疗之道", m=3, r=5, col=2, s="changed", i="spell_nature_healingway", d="治疗波的效果提高25%。", dEn="Increases the amount healed by your Healing Wave spell by 25%.", rq=nil}, {n="Nature's Swiftness", c="自然迅捷", m=1, r=5, col=3, s="same", i="spell_nature_ravenform", d="激活之后，你的下一个施法时间低于10秒的自然法术会成为瞬发法术。", dEn="When activated, your next Nature spell with a casting time less than 10 sec. becomes an instant cast spell.", rq=nil}, {n="Purification", c="净化", m=5, r=6, col=3, s="changed", i="spell_frost_wizardmark", d="使你的治疗法术的效果提高10%。", dEn="Increases the effectiveness of your healing spells by 10%.", rq=nil}, {n="Riptide", c="激流", m=1, r=7, col=2, s="new", i="spell_nature_riptide", d="为友方目标恢复485到533点生命值，并在15秒内额外恢复445点，同时使你直接对该目标施放的治疗链效果提高25%。", dEn="Heals a friendly target for 485 to 533, an additional 445 over 15 sec, and increases the effectiveness of your Chain Heal casts directly on that target by 25%.", rq={5, 2}}}}},
    Mage = {{n="Arcane", c="奥术", t={{n="Wand Specialization", c="魔杖专精", m=2, r=1, col=1, s="moved", i="inv_wand_01", d="使你的魔杖造成的伤害提高25%。", dEn="Increases your damage with Wands by 25%.", rq=nil}, {n="Arcane Focus", c="奥术集中", m=5, r=1, col=2, s="changed", i="spell_holy_devotion", d="使你的奥术法术命中几率提高5%。", dEn="Improves your chance to hit with Arcane spells by 5%.", rq=nil}, {n="Improved Channeling", c="强化引导", m=5, r=1, col=3, s="changed", i="spell_nature_starfall", d="使你在引导奥术飞弹时有100%的几率不会因受到伤害而被打断，在施放奥术冲击时有70%的几率不会因受到伤害而被打断。", dEn="Gives you a 100% chance to avoid interruption caused by damage while channeling Arcane Missiles and a 70% chance while casting Arcane Blast.", rq=nil}, {n="Arcane Subtlety", c="奥术精妙", m=2, r=2, col=1, s="changed", i="spell_holy_dispelmagic", d="使你的目标对你的所有法术的抗性降低15点，并使你的奥术系法术所造成的威胁值降低30%。", dEn="Reduces your target's resistance to all your spells by 15 and reduces the threat caused by your Arcane spells by 30%.", rq=nil}, {n="Magic Absorption", c="魔法吸收", m=2, r=2, col=2, s="changed", i="spell_nature_astralrecalgroup", d="使你的所有抗性提高10点，并使你完全抵抗的法术恢复最大法力值的2%。每秒最多触发一次。", dEn="Increases all your resistances by 10 and causes all spells you fully resist to restore 2% of your total mana. Cannot trigger more often than 1 time per sec.", rq=nil}, {n="Arcane Concentration", c="奥术专注", m=5, r=2, col=3, s="same", i="spell_shadow_manaburn", d="使你有10%的几率在任何伤害法术命中目标之后进入节能施法状态。节能施法状态可以使你的下一个伤害性法术所消耗的法力值减少100%。", dEn="Gives you a 10% chance of entering a Clearcasting state after any damage spell hits a target. The Clearcasting state reduces the mana cost of your next damage spell by 100%.", rq=nil}, {n="Arcane Resilience", c="奥术充沛", m=2, r=2, col=4, s="changed", i="spell_arcane_arcaneresilience", d="使你的护甲提高相当于智力50%的数值。", dEn="Increases your Armor by an amount equal to 50% of your Intellect.", rq=nil}, {n="Arcane Geometry", c="魔法协调", m=2, r=3, col=1, s="new", i="inv_ability_mage_radiantspark", d="使你的奥术法术的射程延长6码。", dEn="Increases the range of your Arcane spells by 6 yards.", rq=nil}, {n="Arcane Impact", c="奥术冲撞", m=3, r=3, col=2, s="changed", i="spell_nature_wispsplode", d="使你的奥术法术爆击几率提高6%。", dEn="Increases the critical strike chance of your Arcane spells by 6%.", rq=nil}, {n="Arcane Blast", c="奥术冲击", m=1, r=3, col=4, s="new", i="spell_arcane_blast", d="用能量冲击目标，造成57到65点奥术伤害。每次施放奥术冲击，你其他所有法术的伤害提高10%，奥术冲击的法力消耗提高175%。该效果最多叠加4次，持续8秒或直到施放任何其他伤害法术。", dEn="Blasts the target with energy, dealing 57 to 65 Arcane damage. Each time you cast Arcane Blast, the damage of all your other spells is increased by 10% and the mana cost of Arcane Blast is increased by 175%. Effect stacks up to 4 times and lasts 8 sec or until any other damage spell is cast.", rq=nil}, {n="Arcane Shielding", c="奥术护盾", m=2, r=4, col=1, s="changed", i="spell_shadow_detectlesserinvisibility", d="使你的法力护盾每吸收一点伤害所消耗的法力值减少33%，并使你的魔甲术提供的抗性提高50%。", dEn="Decreases the Mana lost per point of damage taken when your Mana Shield spell is active by 33% and increases the resistances granted by your Mage Armor spell by 50%.", rq=nil}, {n="Improved Counterspell", c="强化法术反制", m=2, r=4, col=2, s="changed", i="spell_frost_iceshock", d="你的法术反制还会使目标沉默4秒。", dEn="Your Counterspell also Silences the target for 4 sec.", rq=nil}, {n="Arcane Meditation", c="奥术冥想", m=3, r=4, col=3, s="changed", i="spell_shadow_siphonmana", d="使你在施法时仍保持50%的法力回复速度。", dEn="Allows 50% of your Mana regeneration to continue while casting.", rq={2, 3}}, {n="Missile Barrage", c="飞弹连射", m=1, r=4, col=4, s="new", i="ability_mage_missilebarrage", d="你的奥术冲击有40%的几率，火球术、寒冰箭和霜火之箭有20%的几率，使下一个奥术飞弹的引导时间缩短50%、法力消耗减少100%，且每0.5秒发射一次飞弹。", dEn="Gives your Arcane Blast spell a 40% chance, and your Fireball, Frostbolt, and Frostfire Bolt spells a 20% chance to reduce the channeled duration of your next Arcane Missiles spell by 50%, reduce the Mana cost by 100%, and missiles fire every 0.5 sec.", rq=nil}, {n="Presence of Mind", c="气定神闲", m=1, r=5, col=2, s="same", i="spell_nature_enchantarmor", d="激活之后，你的下一个施法时间低于10秒的法师法术会成为瞬发法术。", dEn="When activated, your next Mage spell with a casting time less than 10 sec becomes an instant cast spell.", rq=nil}, {n="Arcane Mind", c="奥术心智", m=5, r=5, col=3, s="changed", i="spell_shadow_charm", d="使你的智力提高10%，奥术法术的爆击伤害加成提高100%。", dEn="Increases your Intellect by 10% and increases the critical strike damage bonus of your Arcane spells by 100%.", rq=nil}, {n="Arcane Instability", c="奥术增效", m=3, r=6, col=3, s="changed", i="spell_shadow_teleport", d="使你的法术伤害提高3%，爆击几率提高3%。", dEn="Increases the damage done by your spells by 3% and your critical strike chance by 3%.", rq=nil}, {n="Arcane Power", c="奥术强化", m=1, r=7, col=2, s="changed", i="spell_nature_lightning", d="在接下来的15秒内，你的法术造成的伤害提高30%，但消耗的法力值也提高30%。", dEn="For the next 15 sec, your spells deal 30% more damage while costing 30% more mana to cast.", rq={5, 2}}}}, {n="Fire", c="火焰", t={{n="Wake of Fire", c="火焰余波", m=2, r=1, col=1, s="changed", i="spell_fire_lavaspawn", d="使你的火焰冲击冷却时间缩短2秒。击杀一个能为你提供经验值或荣誉值的目标后，你在30秒内施放的下一次火焰冲击的爆击几率提高50%。", dEn="Reduces the cooldown of your Fire Blast spell by 2 sec. Killing a non-trivial target increases the critical strike chance of your next Fire Blast cast within 30 sec by 50%.", rq=nil}, {n="Incineration", c="烧尽", m=3, r=1, col=2, s="changed", i="spell_fire_flameshock", d="使你的火焰冲击、冰枪术、奥术冲击和灼烧的爆击几率提高6%。", dEn="Increases the critical strike chance of your Fire Blast, Ice Lance, Arcane Blast, and Scorch spells by 6%.", rq=nil}, {n="Improved Fireball", c="强化火球术", m=5, r=1, col=3, s="changed", i="spell_fire_flamebolt", d="使你的火球术和霜火之箭的施法时间缩短0.5秒。", dEn="Reduces the casting time of your Fireball and Frostfire Bolt spells by 0.5 sec.", rq=nil}, {n="Ignite", c="点燃", m=5, r=2, col=1, s="same", i="spell_fire_incinerate", d="你的火焰伤害法术造成爆击后会使目标燃烧，在4秒内额外造成相当于该法术伤害40%的伤害。", dEn="Your critical strikes from Fire damage spells cause the target to burn for an additional 40% of your spell's damage over 4 sec.", rq=nil}, {n="Flame Throwing", c="烈焰投掷", m=2, r=2, col=2, s="same", i="spell_fire_flare", d="使你的火焰法术的射程增加6码。", dEn="Increases the range of your Fire spells by 6 yards.", rq=nil}, {n="Impact", c="冲击", m=3, r=2, col=3, s="changed", i="spell_fire_meteorstorm", d="使你的火焰法术有10%的几率令目标昏迷2秒。", dEn="Gives your Fire spells a 10% chance to stun the target for 2 sec.", rq=nil}, {n="Burning Soul", c="燃烧之魂", m=3, r=3, col=1, s="changed", i="spell_fire_fire", d="使你的火焰系法术有70%的几率不会因为你受到伤害而被干扰，火焰系法术所造成的威胁值降低30%。", dEn="Gives your Fire spells a 70% chance to not lose casting time when you take damage and reduces the threat caused by your Fire spells by 30%.", rq=nil}, {n="Improved Flamestrike", c="强化烈焰风暴", m=3, r=3, col=2, s="same", i="spell_fire_selfdestruct", d="使你的烈焰风暴造成爆击的几率提高15%。", dEn="Increases the critical strike chance of your Flamestrike spell by 15%.", rq=nil}, {n="Pyroblast", c="炎爆术", m=1, r=3, col=3, s="changed", i="spell_fire_fireball02", d="投掷一枚巨大的火焰巨石，造成101到131点火焰伤害，并在12秒内额外造成44点火焰伤害。", dEn="Hurls an immense fiery boulder that causes 101 to 131 Fire damage and an additional 44 Fire damage over 12 sec.", rq=nil}, {n="Improved Scorch", c="强化灼烧", m=3, r=4, col=1, s="changed", i="spell_fire_windsofwoe", d="你的灼烧法术有100%的几率使目标更易受到火焰伤害。该易伤效果会使你对该目标造成的所有火焰伤害提高3%，持续30秒，最多叠加5次。", dEn="Your Scorch spell has a 100% chance to cause your target to be vulnerable to Fire damage. This vulnerability increases all Fire damage you deal to your target by 3% and lasts 30 sec, stacking up to 5 times.", rq=nil}, {n="Improved Fire Ward", c="强化防护火焰结界", m=2, r=4, col=2, s="same", i="spell_fire_firearmor", d="你的防护火焰结界有20%的几率将火焰法术反射给施法者。", dEn="Causes your Fire Ward to have a 20% chance to reflect Fire spells while active.", rq=nil}, {n="Heating Up", c="升温", m=1, r=4, col=3, s="new", i="spell_fire_firebolt", d="火球术、霜火之箭、火焰冲击和灼烧造成非周期性爆击后，使你在20秒内施放的下一个炎爆术施法时间缩短25%，最多叠加3次。", dEn="Non-periodic critical strikes with Fireball, Frostfire Bolt, Fire Blast, and Scorch reduce the cast time of your next Pyroblast cast within 20 sec by 25%, stacking up to 3 times.", rq={3, 3}}, {n="Master of Elements", c="元素大师", m=3, r=4, col=4, s="changed", i="spell_fire_masterofelements", d="你的火焰和冰霜法术造成爆击时，会返还其基础法力消耗的30%。", dEn="Your Fire and Frost critical strikes will refund 30% of their base mana cost.", rq=nil}, {n="Critical Mass", c="火焰重击", m=3, r=5, col=2, s="same", i="spell_nature_wispheal", d="使你的火焰法术造成爆击的几率提高6%。", dEn="Increases the critical strike chance of your Fire spells by 6%.", rq=nil}, {n="Blast Wave", c="冲击波", m=1, r=5, col=3, s="changed", i="spell_holy_excorcism_02", d="一道火焰冲击波从施法者身上向外扩散，对波及范围内的所有敌人造成154到184点火焰伤害，并使其眩晕，移动速度降低50%，持续6秒。", dEn="A wave of flame radiates outward from the caster, damaging all enemies caught within the blast for 154 to 184 Fire damage, and Dazing them for 50% reduced movement speed for 6 sec.", rq=nil}, {n="Fire Power", c="火焰强化", m=5, r=6, col=3, s="same", i="spell_fire_immolation", d="使你的火焰法术造成的伤害提高10%。", dEn="Increases the damage done by your Fire spells by 10%.", rq=nil}, {n="Combustion", c="燃烧", m=1, r=7, col=2, s="changed", i="spell_fire_sealoffire", d="激活后，你的火焰伤害法术每次命中都会使你的火焰伤害法术爆击几率提高10%。该效果会持续到你用火焰法术造成3次非周期性爆击为止。", dEn="When activated, this spell causes each of your Fire damage spell hits to increase your critical strike chance with Fire damage spells by 10%. This effect lasts until you have caused 3 non-periodic critical strikes with Fire spells.", rq={5, 2}}}}, {n="Frost", c="冰霜", t={{n="Frost Warding", c="冰霜障壁", m=2, r=1, col=1, s="changed", i="spell_frost_frostward", d="使你的霜甲术和冰甲术提供的护甲和抗性提高30%。此外，你的防护冰霜结界激活时有20%的几率反射冰霜法术和效果。", dEn="Increases the Armor and resistance given by your Frost Armor and Ice Armor spells by 30%. In addition, gives your Frost Ward a 20% chance to reflect Frost spells and effects while active.", rq=nil}, {n="Improved Frostbolt", c="强化寒冰箭", m=5, r=1, col=2, s="same", i="spell_frost_frostbolt02", d="使你的寒冰箭的施法时间缩短0.5秒。", dEn="Reduces the casting time of your Frostbolt spell by 0.5 sec.", rq=nil}, {n="Elemental Precision", c="元素精准", m=5, r=1, col=3, s="changed", i="spell_ice_magicdamage", d="使你的冰霜和火焰法术命中几率提高5%。", dEn="Improves your chance to hit with Frost and Fire spells by 5%.", rq=nil}, {n="Ice Shards", c="寒冰碎片", m=5, r=2, col=1, s="same", i="spell_frost_iceshard", d="使你的冰霜法术爆击所造成的伤害提高100%。", dEn="Increases the critical strike damage bonus of your Frost spells by 100%.", rq=nil}, {n="Permafrost", c="极寒冰霜", m=3, r=2, col=2, s="changed", i="spell_frost_wisp", d="使你的冰冷效果持续时间延长33%，并使目标的速度额外降低10%。", dEn="Increases the duration of your Chill effects by 33% and reduces the target's speed by an additional 10%.", rq=nil}, {n="Improved Frost Nova", c="强化冰霜新星", m=2, r=2, col=3, s="same", i="spell_frost_freezingbreath", d="使你的冰霜新星的冷却时间减少4秒。", dEn="Reduces the cooldown of your Frost Nova spell by 4 sec.", rq=nil}, {n="Frostbite", c="霜寒刺骨", m=3, r=2, col=4, s="same", i="spell_frost_frostarmor", d="你的冰冷效果有15%的几率将目标冰冻5秒。", dEn="Gives your Chill effects a 15% chance to Freeze the target for 5 sec.", rq=nil}, {n="Piercing Ice", c="刺骨寒冰", m=3, r=3, col=1, s="same", i="spell_frost_frostbolt", d="使你的冰霜法术所造成的伤害提高6%。", dEn="Increases the damage done by your Frost spells by 6%.", rq=nil}, {n="Frost Channeling", c="冰霜导能", m=3, r=3, col=2, s="moved", i="spell_frost_stun", d="使你的所有冰霜法术所消耗的法力值减少15%，冰霜系法术所造成的威胁值降低30%。", dEn="Reduces the mana cost of your Frost spells by 15% and reduces the threat caused by your Frost spells by 30%.", rq=nil}, {n="Ice Lance", c="冰枪术", m=1, r=3, col=3, s="new", i="spell_frost_frostblast", d="对敌方目标造成28到32点冰霜伤害。对被冻结的目标伤害提高300%。", dEn="Deals 28 to 32 Frost damage to an enemy target. Deals 300% increased damage to Frozen targets.", rq=nil}, {n="Improved Blizzard", c="强化暴风雪", m=3, r=3, col=4, s="changed", i="spell_frost_icestorm", d="为你的暴风雪法术附加冰冷效果，使目标的移动速度降低40%，持续1.5秒。", dEn="Adds a Chill effect to your Blizzard spell. This effect lowers the target's movement speed by 40% for 1.5 sec.", rq=nil}, {n="Arctic Reach", c="极寒延伸", m=2, r=4, col=1, s="same", i="spell_shadow_darkritual", d="使你的冰霜新星和冰锥术的有效半径以及寒冰箭和暴风雪的射程提高20%。", dEn="Increases the range of your Frostbolt and Blizzard spells and the radius of your Frost Nova and Cone of Cold spells by 20%.", rq=nil}, {n="Ice Block", c="寒冰屏障", m=1, r=4, col=2, s="moved", i="spell_frost_frost", d="你被封在一块寒冰中，在10秒内免受所有物理攻击和法术影响，但在此期间无法攻击、移动或施法。", dEn="You become encased in a block of ice, protecting you from all physical attacks and spells for 10 sec, but during that time you cannot attack, move, or cast spells.", rq=nil}, {n="Shatter", c="碎冰", m=3, r=4, col=4, s="changed", i="spell_frost_frostshock", d="使你的所有法术对被冻结目标的爆击几率提高50%。", dEn="Increases the critical strike chance of all your spells against Frozen targets by 50%.", rq=nil}, {n="Improved Cone of Cold", c="强化冰锥术", m=3, r=5, col=1, s="changed", i="spell_frost_glacier", d="使你的冰锥术所造成的伤害提高35%。", dEn="Increases the damage dealt by your Cone of Cold spell by 35%.", rq=nil}, {n="Cold Snap", c="急速冷却", m=1, r=5, col=2, s="changed", i="spell_frost_wizardmark", d="结束你所有其他冰霜法术的剩余冷却时间。", dEn="Finishes the remaining cooldown on all your other Frost spells.", rq=nil}, {n="Fingers of Frost", c="寒冰指", m=2, r=5, col=3, s="new", i="ability_mage_wintersgrasp", d="你的冰冷效果有15%的几率使你获得寒冰指效果，使你的下2次法术将目标视为已被冻结。持续15秒。", dEn="Gives your Chill effects a 15% chance to grant you the Fingers of Frost effect, which treats your next 2 spells cast as if the target were Frozen. Lasts 15 sec.", rq={3, 3}}, {n="Winter's Chill", c="深冬之寒", m=5, r=6, col=3, s="changed", i="spell_frost_chillingblast", d="你的冰霜伤害法术有100%的几率施加深冬之寒效果，使你的冰枪术和寒冰箭对该目标的爆击几率提高2%，持续15秒。最多叠加5次。", dEn="Gives your Frost damage spells a 100% chance to apply the Winter's Chill effect, which increases the chance your Ice Lance and Frostbolt spells will critically hit the target by 2% for 15 sec. Stacks up to 5 times.", rq=nil}, {n="Ice Barrier", c="寒冰护体", m=1, r=7, col=2, s="changed", i="spell_ice_lament", d="立即为自己加上护盾，吸收447点伤害，持续1分钟。护盾存在期间，你的施法不会因受到伤害而被打断或延迟。", dEn="Instantly shields you, absorbing 447 damage. Lasts 1 min. While the shield holds, your spellcasts will not be interrupted or delayed from taking damage.", rq={5, 2}}}}},
    Warlock = {{n="Affliction", c="痛苦", t={{n="Improved Life Tap", c="强化生命分流", m=2, r=1, col=1, s="moved", i="spell_shadow_burningspirit", d="使你的生命分流法术所转化的法力值提高20%。", dEn="Increases the amount of Mana awarded by your Life Tap spell by 20%.", rq=nil}, {n="Suppression", c="镇压", m=5, r=1, col=2, s="changed", i="spell_shadow_unsummonbuilding", d="使你的命中几率提高5%，并使你产生的所有威胁降低20%。", dEn="Improves your chance to hit by 5% and reduces all threat you generate by 20%.", rq=nil}, {n="Improved Corruption", c="强化腐蚀术", m=5, r=1, col=3, s="changed", i="spell_shadow_abominationexplosion", d="使你的腐蚀术的施法时间缩短2秒，造成的伤害提高10%。", dEn="Reduces the casting time of your Corruption spell by 2 sec and increases the damage it deals by 10%.", rq=nil}, {n="Malediction", c="邪咒", m=5, r=2, col=1, s="new", i="spell_shadow_curseofachimonde", d="使你的术士法术造成的所有周期性伤害提高5%。", dEn="Increases all periodic damage done by your Warlock spells by 5%.", rq=nil}, {n="Soul Harvest", c="灵魂收割", m=2, r=2, col=2, s="new", i="inv_elemental_primal_shadow", d="杀死受你的吸取灵魂影响的有意义目标后，使你的法力回复速度提高100%，持续10秒，并在施法时保持100%的正常法力回复速度。", dEn="Killing a non-trivial target afflicted by your Drain Soul increases your Mana regeneration by 100% for 10 sec and allows 100% of normal Mana regeneration to continue while casting.", rq=nil}, {n="Improved Drains", c="强化吸取", m=3, r=2, col=3, s="new", i="spell_shadow_haunting", d="使你的吸取生命、吸取灵魂和折磨法术造成的伤害或吸取的生命提高20%。", dEn="Increases health drained or damage done by your Drain Life, Drain Soul, and Wrack spells by 20%.", rq=nil}, {n="Improved Bane of Agony", c="强化痛苦灾祸", m=2, r=3, col=1, s="changed", i="spell_shadow_curseofsargeras", d="使你的痛苦灾祸造成的伤害提高10%。", dEn="Increases the damage done by your Bane of Agony by 10%.", rq=nil}, {n="Fel Concentration", c="恶魔专注", m=3, r=3, col=2, s="changed", i="spell_shadow_fingerofdeath", d="使你在引导或施放吸取生命、吸取法力、吸取灵魂或折磨时有70%的几率避免因受到伤害而被打断。", dEn="Gives you a 70% chance to avoid interruption caused by damage while channeling or casting your Drain Life, Drain Mana, Drain Soul, or Wrack spells.", rq=nil}, {n="Amplify Curse", c="诅咒增幅", m=1, r=3, col=3, s="changed", i="spell_shadow_contagion", d="使你的下一个虚弱诅咒或痛苦灾祸的效果提高50%，或使你的下一个疲劳诅咒的效果提高20%，持续30秒。", dEn="Increases the effect of your next Curse of Weakness or Bane of Agony by 50%, or your next Curse of Exhaustion by 20%. Lasts 30 sec.", rq=nil}, {n="Pandemic", c="恶疾", m=3, r=3, col=4, s="new", i="spell_shadow_unstableaffliction_2", d="使你的腐蚀术、痛苦灾祸、末日灾祸、吸取灵魂、吸取生命、生命虹吸和折磨的爆击伤害加成提高100%。", dEn="Increases the critical strike damage bonus of your Corruption, Bane of Agony, Bane of Doom, Drain Soul, Drain Life, Siphon Life, and Wrack spells by 100%.", rq=nil}, {n="Malevolence", c="怨毒", m=5, r=4, col=1, s="new", i="spell_shadow_focusedpower", d="使你的暗影法术爆击几率提高5%。", dEn="Increases the critical effect chance of your Shadow spells by 5%.", rq=nil}, {n="Nightfall", c="夜幕", m=2, r=4, col=2, s="changed", i="spell_shadow_twilight", d="使你的腐蚀术、吸取灵魂、吸取生命和折磨在对敌人造成伤害后有4%的几率令你进入暗影冥思。暗影冥思使你的下一个暗影箭的施法时间缩短100%。", dEn="Gives your Corruption, Drain Soul, Drain Life, and Wrack spells a 4% chance to cause you to enter a Shadow Trance after damaging the opponent. The Shadow Trance reduces the casting time of your next Shadow Bolt spell by 100%.", rq=nil}, {n="Curse of Exhaustion", c="疲劳诅咒", m=1, r=4, col=3, s="changed", i="spell_shadow_grimward", d="使目标的速度降低30%，持续12秒。每个术士只能对一个目标施加一种诅咒，且同类诅咒不能叠加。", dEn="Reduces the target's movement speed by 30% for 12 sec. Only one Curse per Warlock can be active on any one target.", rq={3, 3}}, {n="Siphon Life", c="生命虹吸", m=1, r=5, col=2, s="changed", i="spell_shadow_requiem", d="每3秒将目标的11点生命值转移给施法者，持续30秒。", dEn="Transfers 11 health from the target to the caster every 3 sec. Lasts 30 sec.", rq=nil}, {n="Soul Siphon", c="灵魂虹吸", m=3, r=5, col=3, s="new", i="spell_shadow_lifedrain02", d="目标身上每有一个你的其他痛苦系效果，你的吸取生命、吸取灵魂和折磨造成的伤害或吸取的生命值提高12%，最多提高36%。", dEn="Increases the damage done or health drained by your Drain Life, Drain Soul, and Wrack spells by 12% per each of your other Affliction effects active on the target, up to a maximum increase of 36%.", rq=nil}, {n="Shadow Mastery", c="暗影掌握", m=5, r=6, col=3, s="changed", i="spell_shadow_shadetruesight", d="使你的暗影法术所造成的伤害或吸取的生命值提高5%。", dEn="Increases the damage dealt or life drained by your Shadow spells by 5%.", rq=nil}, {n="Wrack", c="折磨", m=1, r=7, col=2, s="new", i="ability_deathknight_hemorrhagicfever", d="从内部撕裂目标，每1秒造成36点暗影伤害，并使其受到你其他暗影持续伤害效果的伤害提高10%，持续6秒。", dEn="Tears the target apart from within, inflicting 36 Shadow damage every 1 sec and increasing the damage they take from your other Shadow damage over time effects by 10% for 6 sec.", rq={5, 2}}}}, {n="Demonology", c="恶魔学识", t={{n="Improved Health Funnel", c="强化生命通道", m=2, r=1, col=1, s="changed", i="spell_shadow_lifedrain", d="使你的生命通道转移的生命值提高40%，生命值消耗降低30%，并使生命通道产生的所有威胁降低100%。无论恶魔的生命值如何都可以使用生命通道。", dEn="Increases the amount of health transferred by your Health Funnel spell by 40%, reduces its health cost by 30%, and reduces all threat your Health Funnel generates by 100%. Allows Health Funnel to be used regardless of your demon's health.", rq=nil}, {n="Improved Imp", c="强化小鬼", m=3, r=1, col=2, s="changed", i="spell_shadow_summonimp", d="使你的小鬼的火焰箭造成的伤害提高30%，火焰之盾的效果提高30%。", dEn="Increases the damage of your Imp's Firebolt spell by 30% and the effect of its Fire Shield spell by 30%.", rq=nil}, {n="Demonic Embrace", c="恶魔之拥", m=5, r=1, col=3, s="changed", i="spell_shadow_metamorphosis", d="使你的耐力总值提高15%。", dEn="Increases your total Stamina by 15%.", rq=nil}, {n="Unholy Power", c="邪恶强化", m=5, r=1, col=4, s="changed", i="spell_shadow_shadowworddominate", d="使你的小鬼、虚空行者、魅魔、夜魔和地狱猎犬宠物造成的所有伤害提高10%。", dEn="Increases all damage done by your Imp, Voidwalker, Succubus, Incubus, and Felhunter pets by 10%.", rq=nil}, {n="Demonic Aegis", c="恶魔庇护", m=2, r=2, col=1, s="new", i="spell_shadow_ragingscream", d="使你的恶魔皮肤和恶魔护甲法术的效果提高30%。", dEn="Increases the effectiveness of your Demon Skin and Demon Armor spells by 30%.", rq=nil}, {n="Improved Voidwalker", c="强化虚空行者", m=3, r=2, col=2, s="same", i="spell_shadow_summonvoidwalker", d="使你的虚空行者的折磨、吞噬暗影、牺牲和受难法术效果提高30%。", dEn="Increases the effectiveness of your Voidwalker's Torment, Consume Shadows, Sacrifice, and Suffering spells by 30%.", rq=nil}, {n="Fel Vitality", c="邪能活力", m=3, r=2, col=3, s="changed", i="spell_shadow_demonictactics", d="使你的小鬼、虚空行者、魅魔、夜魔和地狱猎犬的生命值与法力值上限提高15%，并使你的法力值上限提高15%。", dEn="Increases the maximum health and Mana of your Imp, Voidwalker, Succubus, Incubus, and Felhunter by 15%, and increases your maximum Mana by 15%.", rq=nil}, {n="Demonic Energies", c="恶魔能量", m=2, r=2, col=4, s="new", i="spell_shadow_felmending", d="你造成的所有法术伤害会为宠物恢复相当于该伤害15%的生命值。通过生命分流获得法力时，召唤的恶魔会获得相当于你所得法力100%的法力。", dEn="You heal your pet for 15% of all spell damage you deal. When you gain Mana from Life Tap, your summoned demon gains 100% of the Mana you gain.", rq=nil}, {n="Improved Sayaad", c="强化萨亚德", m=3, r=3, col=1, s="same", i="ability_warlock_randomizesuccubusincubus", d="使你的魅魔和夜魔的剧痛鞭笞和安抚之吻法术的效果提高30%，并使你的魅魔和夜魔的诱惑和次级隐形术的持续时间延长30%。", dEn="Increases the effect of your Succubus' and Incubus' Lash of Pain and Soothing Kiss spells by 30%, and increases the duration of your Succubus' and Incubus' Seduction and Lesser Invisibility spells by 30%.", rq=nil}, {n="Demonic Sacrifice", c="恶魔牺牲", m=1, r=3, col=2, s="changed", i="spell_shadow_psychicscream", d="激活后，牺牲你召唤的恶魔来强化你力量的相反面向，使你获得一个持续2小时的效果。如果召唤任何恶魔，该效果会被取消。\n\n小鬼：使你的暗影伤害提高15%。\n\n虚空行者：每4秒恢复总法力值的2%。\n\n魅魔/夜魔：使你的火焰伤害提高15%。\n\n地狱猎犬：每4秒恢复总生命值的3%。", dEn="When activated, sacrifices your summoned Demon to enhance the opposing aspect of your power, granting you an effect that lasts 2 hrs. The effect is canceled if any Demon is summoned.\n\nImp: Increases your Shadow damage by 15%.\n\nVoidwalker: Restores 2% of your total Mana every 4 sec.\n\nSuccubus/Incubus: Increases your Fire damage by 15%.\n\nFelhunter: Restores 3% of your total Health every 4 sec.", rq=nil}, {n="Master Summoner", c="召唤大师", m=2, r=3, col=3, s="moved", i="spell_shadow_impphaseshift", d="使你召唤小鬼、虚空行者、魅魔、夜魔和地狱猎犬的施法时间减少4秒，法力值消耗降低40%。", dEn="Reduces the casting time of your Imp, Voidwalker, Succubus, Incubus, and Felhunter Summoning spells by 4 sec and the Mana cost by 40%.", rq=nil}, {n="Decimation", c="灭杀", m=2, r=4, col=1, s="new", i="spell_fire_fireball02", d="使你的灵魂之火冷却时间缩短90%。当你对生命值低于35%的敌人施放暗影箭或灼热之痛时，这些法术造成的伤害提高6%，并且在接下来的10秒内，你的灵魂之火施法时间缩短40%，且不消耗灵魂碎片。", dEn="Reduces the cooldown of your Soul Fire spell by 90%. When you cast Shadow Bolt or Searing Pain on an enemy below 35% health, they deal 6% increased damage, and for the next 10 sec your Soul Fire spell has its cast time reduced by 40% and costs no Soul Shards.", rq=nil}, {n="Fel Domination", c="恶魔支配", m=1, r=4, col=3, s="moved", i="spell_nature_removecurse", d="你的下一个召唤小鬼、虚空行者、魅魔、夜魔或地狱猎犬的法术施法时间减少5.5秒，法力消耗减少50%。", dEn="Your next Imp, Voidwalker, Succubus, Incubus, or Felhunter Summon spell has its casting time reduced by 5.5 sec and its Mana cost reduced by 50%.", rq={3, 3}}, {n="Demonic Brand", c="恶魔印记", m=3, r=4, col=4, s="new", i="ability_demonhunter_chaoticimprint_fire", d="你的灼热之痛产生的威胁降低50%，并标记目标10秒。你的宠物接下来对目标的6次攻击会产生高威胁，并根据宠物类型造成65至68点火焰或暗影伤害。", dEn="Your Searing Pain generates 50% less threat and brands the target for 10 sec. Your pet's next 6 attacks against the target generate high threat and deal 65 to 68 Fire or Shadow damage based on the pet.", rq=nil}, {n="Improved Felhunter", c="强化地狱猎犬", m=3, r=5, col=1, s="new", i="spell_shadow_summonfelhunter", d="使你的地狱猎犬的腐坏之血的攻击强度降低效果、吞噬魔法的治疗效果以及多疑的侦测等级提高30%，并使其法术封锁的冷却时间缩短6秒。", dEn="Increases the Attack Power reduction of your Felhunter's Tainted Blood, the healing of its Devour Magic, and the detection level of its Paranoia by 30%, and reduces the cooldown of its Spell Lock by 6 sec.", rq=nil}, {n="Soul Link", c="灵魂链接", m=1, r=5, col=2, s="changed", i="spell_shadow_gathershadows", d="激活时，施法者受到的所有伤害有30%由你的小鬼、虚空行者、魅魔、夜魔或地狱猎犬恶魔承受。此外，恶魔和主人造成的伤害都提高3%。只要恶魔处于激活状态，该效果就会持续。", dEn="When active, 30% of all damage taken by the caster is taken by your Imp, Voidwalker, Succubus, Incubus, or Felhunter Demon instead. In addition, both the Demon and the master will inflict 3% more damage. Lasts as long as the Demon is active.", rq={3, 2}}, {n="Demonic Knowledge", c="恶魔知识", m=3, r=5, col=3, s="new", i="spell_shadow_improvedvampiricembrace", d="召唤的恶魔宠物激活时，使你和恶魔宠物的法术伤害最多提高相当于你等级100%的数值。", dEn="Increases your spell damage and your Demon pet's spell damage by up to 100% of your level while you have a summoned Demon pet active.", rq=nil}, {n="Master Demonologist", c="恶魔学识大师", m=5, r=6, col=3, s="changed", i="spell_shadow_shadowpact", d="只要召唤的恶魔保持激活，使术士和该恶魔获得一个效果。\n\n小鬼 - 火焰伤害提高10%。\n\n虚空行者 - 受到的物理伤害降低10%。\n\n魅魔/夜魔 - 暗影伤害提高10%。\n\n地狱猎犬 - 受到的魔法伤害降低10%。", dEn="Grants both the Warlock and the summoned demon an effect as long as that demon is active.\n\nImp - Increases Fire damage done by 10%.\n\nVoidwalker - Reduces Physical damage taken by 10%.\n\nSuccubus/Incubus - Increases Shadow damage done by 10%.\n\nFelhunter - Reduces Magic damage taken by 10%.", rq=nil}, {n="Demonic Pact", c="恶魔契约", m=1, r=7, col=2, s="new", i="inv_ability_soulharvesterwarlock_demonicsoul", d="你的恶魔牺牲效果不再因召唤其它不同的恶魔宠物而取消。重新召唤已被牺牲的宠物仍会取消该效果。", dEn="Your Demonic Sacrifice effect is no longer cancelled by summoning a different Demon pet. Resummoning the sacrificed pet will still cancel the effect.", rq={5, 2}}}}, {n="Destruction", c="毁灭", t={{n="Destructive Reach", c="毁灭延伸", m=2, r=1, col=1, s="changed", i="spell_shadow_corpseexplode", d="使你的伤害法术射程提高20%。", dEn="Increases the range of your damaging spells by 20%.", rq=nil}, {n="Improved Shadow Bolt", c="强化暗影箭", m=5, r=1, col=2, s="changed", i="spell_shadow_shadowbolt", d="你的暗影箭爆击会使目标受到来自你攻击的暗影伤害提高20%，持续12秒。", dEn="Your Shadow Bolt critical strikes increase Shadow damage taken by the target from your attacks by 20% for 12 sec.", rq=nil}, {n="Bane", c="灾祸", m=5, r=1, col=3, s="changed", i="spell_shadow_deathpact", d="使你的暗影箭、献祭和烧尽的施法时间缩短0.5秒，灵魂之火的施法时间缩短2秒。", dEn="Reduces the casting time of your Shadow Bolt, Immolate, and Incinerate spells by 0.5 sec and your Soul Fire spell by 2 sec.", rq=nil}, {n="Molten Skin", c="熔岩之肤", m=5, r=2, col=1, s="new", i="ability_mage_moltenarmor", d="使你受到的所有伤害降低10%。", dEn="Reduces all damage taken by 10%.", rq=nil}, {n="Cataclysm", c="灾变", m=3, r=2, col=2, s="changed", i="spell_fire_windsofwoe", d="使你的毁灭系法术所消耗的法力值减少10%。", dEn="Reduces the Mana cost of your Destruction spells by 10%.", rq=nil}, {n="Aftermath", c="清算", m=5, r=2, col=3, s="changed", i="spell_fire_fire", d="使你的献祭的初始伤害提高50%，并且你的燃烧有100%的几率使目标眩晕，移动速度降低50%，持续5秒。", dEn="Increases the initial damage of your Immolate spell by 50% and your Conflagrate spell has a 100% chance to Daze the target, reducing the target's movement speed by 50% for 5 sec.", rq=nil}, {n="Ruin", c="毁灭", m=5, r=3, col=2, s="changed", i="spell_shadow_shadowwordpain", d="使你的毁灭系法术的爆击伤害加成提高100%。", dEn="Increases the critical strike damage bonus of your Destruction spells by 100%.", rq=nil}, {n="Shadowburn", c="暗影灼烧", m=1, r=3, col=3, s="changed", i="spell_shadow_scourgebuild", d="立即对目标造成65到73点暗影伤害。如果一个非琐碎的目标在被暗影灼烧命中后8秒内死亡，施法者获得一块灵魂碎片。", dEn="Instantly blasts the target for 65 to 73 Shadow damage. If a non-trivial target dies within 8 sec of being hit with Shadowburn, the caster gains a Soul Shard.", rq=nil}, {n="Intensity", c="强烈", m=3, r=4, col=1, s="changed", i="spell_fire_lavaspawn", d="使你有70%的几率在施放或引导任何毁灭系法术时不会因受到伤害而被打断。", dEn="Gives you a 70% chance to resist interruption caused by damage while casting or channeling any Destruction spell.", rq=nil}, {n="Agonizing Flames", c="苦痛之焰", m=3, r=4, col=2, s="changed", i="spell_fire_soulburn", d="使你的灼热之痛的爆击几率提高10%，并使你所有毁灭系法术造成的伤害提高10%。", dEn="Increases the critical strike chance of your Searing Pain spell by 10% and the damage done by all your Destruction spells by 10%.", rq=nil}, {n="Conflagrate", c="燃烧", m=1, r=4, col=3, s="changed", i="spell_fire_fireball", d="点燃一个已经受到你的献祭影响的目标，造成88到110点火焰伤害，并消耗你的献祭效果。", dEn="Ignites a target that is already afflicted by your Immolate spell, dealing 88 to 110 Fire damage and consuming your Immolate effect.", rq=nil}, {n="Pyroclasm", c="火焰冲撞", m=2, r=5, col=1, s="changed", i="spell_fire_volcano", d="使你的灵魂之火有26%的几率令目标昏迷3秒，并使你的火焰之雨和地狱烈焰在持续期间有26%的几率令受到伤害的目标昏迷3秒。", dEn="Gives your Soul Fire spell a 26% chance to Stun the target for 3 sec, and your Rain of Fire and Hellfire spells a 26% chance over their duration to Stun targets they damage for 3 sec.", rq={4, 1}}, {n="Bane of Havoc", c="浩劫灾祸", m=1, r=5, col=2, s="new", i="ability_warlock_baneofhavoc", d="使目标遭受浩劫灾祸，持续5分钟，术士对其他目标造成伤害时，被诅咒的目标也会受到相当于该伤害15%的伤害。浩劫灾祸最多影响1个目标，每名术士在任一目标身上只能维持一种灾祸。", dEn="Afflicts the target for 5 min, causing 15% of all damage done by the Warlock to other targets to also be dealt to the cursed target. Bane of Havoc is limited to 1 target, and only one Bane per Warlock can be active on any one target.", rq=nil}, {n="Fire and Brimstone", c="硫磺烈火", m=3, r=5, col=3, s="new", i="spell_fire_meteorstorm", d="使你的燃烧法术爆击几率提高25%。", dEn="Increases the critical strike chance of your Conflagrate spell by 25%.", rq={4, 3}}, {n="Shadow and Flame", c="影与焰", m=5, r=6, col=3, s="new", i="spell_fire_playingwithfire", d="使用燃烧击中敌人后，你造成的所有暗影伤害提高10%，持续20秒。使用暗影灼烧击中敌人后，你造成的所有火焰伤害提高10%，持续20秒。此外，燃烧有100%的几率不消耗献祭，暗影灼烧有100%的几率立刻返还一块灵魂碎片。", dEn="Hitting an enemy with Conflagrate increases all Shadow damage you deal by 10% for 20 sec, and hitting an enemy with Shadowburn increases all Fire damage you deal by 10% for 20 sec. In addition, Conflagrate has a 100% chance not to consume Immolate, and Shadowburn has a 100% chance to instantly refund a Soul Shard.", rq=nil}, {n="Incinerate", c="烧尽", m=1, r=7, col=2, s="new", i="spell_fire_burnout", d="对目标造成99到113点火焰伤害；如果目标受到献祭影响，则额外造成25%点伤害。", dEn="Deals 99 to 113 Fire damage to your target and an additional 25% damage if the target is afflicted by Immolate.", rq={5, 2}}}}},
    Druid = {{n="Balance", c="平衡", t={{n="Improved Wrath", c="强化愤怒", m=5, r=1, col=2, s="changed", i="spell_nature_abolishmagic", d="使你的愤怒法术的施法时间缩短0.5秒，法力值消耗降低50%。", dEn="Reduces the cast time of your Wrath spell by 0.5 sec and its Mana cost by 50%.", rq=nil}, {n="Genesis", c="起源", m=5, r=1, col=3, s="new", i="spell_arcane_arcane03", d="使你的法术和技能造成的周期性伤害和治疗量提高5%。", dEn="Increases the periodic damage and healing done by your spells and abilities by 5%.", rq=nil}, {n="Moonglow", c="月光", m=3, r=2, col=1, s="changed", i="spell_nature_sentinal", d="你的伤害性法术的法力消耗降低25%。", dEn="Reduces the Mana cost of your damaging spells by 25%.", rq=nil}, {n="Improved Moonfire", c="强化月火术", m=2, r=2, col=2, s="changed", i="spell_nature_starfall", d="使你的月火术的伤害和爆击几率提高10%。", dEn="Increases the damage and critical strike chance of your Moonfire spell by 10%.", rq=nil}, {n="Nature's Majesty", c="自然的威严", m=2, r=2, col=3, s="new", i="inv_staff_01", d="使你的法术和近战攻击的爆击几率提高4%。", dEn="Increases your critical strike chance with spells and melee attacks by 4%.", rq=nil}, {n="Nature's Reach", c="自然延伸", m=2, r=2, col=4, s="changed", i="spell_nature_naturetouchgrow", d="使你的进攻性平衡法术射程提高20%，命中几率提高4%。", dEn="Increases the range of your offensive Balance spells by 20% and improves your chance to hit by 4%.", rq=nil}, {n="Improved Entangling Roots", c="强化纠缠根须", m=3, r=3, col=1, s="changed", i="spell_nature_stranglevines", d="使你的纠缠根须造成的伤害提高75%，且受其影响的目标可额外承受最多75%的伤害而不会打断该效果。", dEn="Increases the damage done by your Entangling Roots spell by 75%, and its victims can take up to 75% more damage without interrupting the effect.", rq=nil}, {n="Nature's Splendor", c="自然的壮美", m=1, r=3, col=3, s="new", i="spell_nature_natureresistancetotem", d="使你的月火术和回春术的持续时间延长3秒，愈合的持续时间延长6秒，虫群的持续时间延长2秒。", dEn="Increases the duration of your Moonfire and Rejuvenation spells by 3 sec, your Regrowth spell by 6 sec, and your Insect Swarm spell by 2 sec.", rq={2, 3}}, {n="Insect Swarm", c="虫群", m=1, r=4, col=1, s="changed", i="spell_nature_insectswarm", d="敌人被飞虫围绕，攻击命中几率降低2%，在12秒内受到总计48点自然伤害。", dEn="The enemy target is swarmed by insects, decreasing their chance to hit with attacks by 2% and causing 48 Nature damage over 12 sec.", rq=nil}, {n="Vengeance", c="复仇", m=5, r=4, col=2, s="changed", i="spell_nature_purge", d="使你的奥术和自然法术的爆击伤害加成提高100%。", dEn="Increases the critical strike damage bonus of your Arcane and Nature spells by 100%.", rq={2, 2}}, {n="Improved Starfire", c="强化星火术", m=5, r=4, col=3, s="changed", i="spell_arcane_starfire", d="使你的星火术的施法时间缩短0.5秒，并有15%的几率使目标昏迷3秒。", dEn="Reduces the cast time of Starfire by 0.5 sec and Starfire has a 15% chance to stun its target for 3 sec.", rq=nil}, {n="Overgrowth", c="繁茂", m=2, r=5, col=1, s="new", i="inv_misc_herb_15", d="使你同时可被纠缠根须影响的目标数量上限提高2个。", dEn="Increases the maximum number of targets you may have affected by Entangling Roots by 2.", rq=nil}, {n="Nature's Grace", c="自然之赐", m=1, r=5, col=2, s="changed", i="spell_nature_naturesblessing", d="你的所有非周期性法术爆击都会使你获得自然的赐福，使施法速度提高并公共冷却时间缩短10%，持续3秒。", dEn="All non-periodic spell criticals grace you with a blessing of nature, increasing your spellcasting speed and reducing your global cooldown by 10% for 3 sec.", rq=nil}, {n="Eclipse", c="日月之蚀", m=3, r=5, col=3, s="new", i="ability_druid_eclipse", d="你的愤怒使接下来2次星火术的施法时间缩短0.50秒。最多储存4层。持续15秒。", dEn="Your Wrath spell reduces the cast time of your next 2 Starfire spells by 0.50 sec. Stores up to 4 charges. Lasts 15 sec.", rq=nil}, {n="Moonfury", c="月怒", m=5, r=6, col=2, s="changed", i="spell_nature_moonglow", d="使你的奥术和自然法术造成的伤害提高10%。", dEn="Increases the damage done by your Arcane and Nature spells by 10%.", rq=nil}, {n="Moonkin Form", c="枭兽形态", m=1, r=7, col=2, s="changed", i="spell_nature_forceofnature", d="变为枭兽形态，使清晰预兆的触发几率提高100%，装备提供的护甲值提高360%，45码内的所有小队成员爆击几率提高3%（与兽群领袖不叠加）。该形态还使施法者免疫变形术效果，且无法使用治疗法术。\n\n变形时会解除施法者身上的变形术和移动限制效果。", dEn="Shapeshift into Moonkin Form, increasing Omen of Clarity's chance to trigger by 100%, Armor contribution from items by 360%, and all party members within 45 yards have their Critical Strike chance increased by 3%, exclusive with Leader of the Pack. Also protects the caster from Polymorph effects and prevents the use of healing spells.\n\nThe act of shapeshifting frees the caster of Polymorph and Movement Impairing effects.", rq=nil}}}, {n="Feral Combat", c="野性战斗", t={{n="Ferocity", c="凶暴", m=5, r=1, col=2, s="changed", i="ability_hunter_pet_hyena", d="使你的槌击、原始撕咬、挥击、爪击和斜掠的消耗降低5点怒气或能量。", dEn="Reduces the cost of your Maul, Primal Bite, Swipe, Claw, and Rake abilities by 5 Rage or Energy.", rq=nil}, {n="Heart of the Wild", c="野性之心", m=5, r=1, col=3, s="changed", i="spell_holy_blessingofagility", d="使你的智力提高10%。此外，在熊形态或巨熊形态下，耐力提高20%；在猎豹形态下，力量提高10%。", dEn="Increases your Intellect by 10%. In addition, while in Bear Form or Dire Bear Form your Stamina is increased by 20% and while in Cat Form your Strength is increased by 10%.", rq=nil}, {n="Feral Swiftness", c="豹之迅捷", m=2, r=2, col=1, s="changed", i="spell_nature_spiritwolf", d="使你在猎豹形态下的移动速度提高30%，躲闪几率提高4%。", dEn="Increases your movement speed while in Cat Form by 30%, and increases your chance to Dodge by 4%.", rq=nil}, {n="Feral Instinct", c="野性本能", m=3, r=2, col=2, s="changed", i="ability_ambush", d="使你的挥击造成的伤害提高30%，并在潜行时使敌人侦测到你的几率降低，效果相当于你高出3级。", dEn="Increases damage done by your Swipe ability by 30% and reduces the chance enemies have to detect you while Prowling as if you were 3 levels higher.", rq=nil}, {n="Brutal Impact", c="野蛮冲撞", m=2, r=2, col=3, s="changed", i="ability_druid_bash", d="使你的重击和突袭的昏迷持续时间延长1秒，并使重击的冷却时间缩短30秒。", dEn="Increases the stun duration of your Bash and Pounce abilities by 1 sec and reduces the cooldown of Bash by 30 sec.", rq=nil}, {n="Thick Hide", c="厚皮", m=3, r=2, col=4, s="changed", i="inv_misc_pelt_bear_03", d="处于熊形态、猎豹形态、巨熊形态或枭兽形态时，你每级获得3点额外基础护甲；防御技能超过你等级五倍后，每一点还会提供2.00点基础护甲。该数值可进一步受到这些形态的倍率加成。", dEn="While in Bear Form, Cat Form, Dire Bear Form, or Moonkin Form, you gain 3 additional base Armor per level and another 2.00 base Armor for each point of defense skill beyond five times your level. This amount can be further increased by multipliers from those forms.", rq=nil}, {n="Shredding Attacks", c="撕碎攻击", m=3, r=3, col=1, s="changed", i="spell_shadow_vampiricaura", d="使你的撕碎消耗的能量值降低18点，割伤消耗的怒气降低3点。", dEn="Reduces the Energy cost of your Shred ability by 18 and reduces the Rage cost of your Lacerate ability by 3.", rq=nil}, {n="Savage Fury", c="野蛮暴怒", m=2, r=3, col=2, s="changed", i="ability_druid_ravage", d="使你的爪击、扫击、撕碎、槌击和横扫技能造成的伤害提高10%。", dEn="Increases the damage caused by your Claw, Rake, Shred, Maul, and Swipe abilities by 10%.", rq=nil}, {n="Feral Charge", c="野性冲锋", m=1, r=3, col=3, s="changed", i="ability_hunter_pet_bear", d="冲向一个敌人，将其定身并打断其正在施放的法术，持续4秒。\n\n跃至敌人身后。", dEn="Charge an enemy, immobilizing them and interrupting any spell they are casting for 4 sec.\n\nLeap behind an enemy.", rq=nil}, {n="Sharpened Claws", c="锋利兽爪", m=2, r=3, col=4, s="changed", i="inv_misc_monsterclaw_04", d="使你在熊形态、巨熊形态或猎豹形态下的爆击几率提高6%。", dEn="Increases your critical strike chance while in Bear Form, Dire Bear Form, or Cat Form by 6%.", rq=nil}, {n="Shifting Power", c="变换之力", m=1, r=4, col=1, s="new", i="spell_druid_displacement", d="立即将基础法力值的55%转化为40点能量。降低变形消耗的效果也会降低变换之力的消耗。", dEn="Instantly convert 55% of base Mana into 40 Energy. Shifting Power's cost is reduced by effects that reduce the cost of Shapeshifting.", rq={3, 1}}, {n="Primal Bite", c="原始撕咬", m=1, r=4, col=2, s="new", i="ability_racial_cannibalize", d="撕咬目标，造成100%的普通伤害外加26点，并产生大量威胁值。", dEn="Bite the target, dealing 100% normal damage plus 26 and generating a high amount of threat.", rq={3, 2}}, {n="Predatory Strikes", c="猛兽攻击", m=3, r=4, col=3, s="changed", i="ability_hunter_pet_cat", d="使你在猎豹形态、熊形态和巨熊形态下的近战攻击强度提高，数值相当于你等级的150%。", dEn="Increases your melee Attack Power in Cat Form, Bear Form, and Dire Bear Form by 150% of your level.", rq=nil}, {n="Blood Frenzy", c="血之狂暴", m=2, r=4, col=4, s="changed", i="ability_ghoulfrenzy", d="使你在熊形态或巨熊形态下造成爆击时，有100%的几率额外获得5点怒气。此外，你的猎豹形态下可产生连击点数的技能的非周期性爆击有100%的几率额外增加一个连击点数。", dEn="Gives you a 100% chance to gain an additional 5 Rage any time you get a critical strike while in Bear Form or Dire Bear Form. In addition, your non-periodic critical strikes from Cat Form abilities that generate Combo Points have a 100% chance to add an additional Combo Point.", rq={3, 4}}, {n="Improved Shifting Power", c="强化变换之力", m=2, r=5, col=1, s="new", i="ability_hunter_aspectmastery", d="使你的变换之力的冷却时间缩短8秒。", dEn="Reduces the cooldown of your Shifting Power spell by 8 sec.", rq={4, 1}}, {n="Leader of the Pack", c="兽群领袖", m=1, r=5, col=2, s="changed", i="spell_nature_unyeildingstamina", d="处于猎豹、熊或巨熊形态时，兽群领袖使45码内所有小队成员的爆击几率提高3%。不可与枭兽光环共存。", dEn="While in Cat Form, Bear Form, or Dire Bear Form, the Leader of the Pack increases the critical strike chance of all party members within 45 yards by 3%, exclusive with Moonkin Aura.", rq=nil}, {n="Predatory Instincts", c="掠食本能", m=2, r=5, col=4, s="new", i="ability_druid_predatoryinstincts", d="使你的近战技能的爆击伤害加成提高20%。", dEn="Increases the critical strike damage bonus of your melee abilities by 20%.", rq=nil}, {n="Natural Reaction", c="自然反射", m=5, r=6, col=1, s="new", i="ability_bullrush", d="使你的躲闪几率提高5%，并且每次躲闪有100%的几率获得5点怒气。", dEn="Increases your dodge chance by 5%, and gives you a 100% chance to gain 5 Rage each time you dodge.", rq=nil}, {n="Rend and Tear", c="狂乱撕扯", m=5, r=6, col=3, s="new", i="ability_druid_primalagression", d="使你的近战技能对流血目标造成的伤害提高10%。", dEn="Increases damage done by your melee abilities on Bleeding targets by 10%.", rq={4, 3}}, {n="Berserk", c="狂暴", m=1, r=7, col=2, s="new", i="ability_druid_berserk", d="使你的原始撕咬最多可攻击3个目标并移除其冷却时间，使你产生连击点的技能的爆击几率提高100%。持续期间清除并免疫恐惧效果。持续15秒。", dEn="Causes your Primal Bite ability to strike up to 3 targets, removes its cooldown, and increases the critical strike chance of your Combo Point-generating abilities by 100%. Clears and grants immunity to Fear effects for the duration. Lasts 15 sec.", rq={5, 2}}}}, {n="Restoration", c="恢复", t={{n="Nature's Focus", c="自然集中", m=5, r=1, col=2, s="changed", i="spell_nature_healingwavegreater", d="使你在施放奥术和自然法术时有70%的几率不会因受到伤害而被打断。", dEn="Gives you a 70% chance to avoid interruption caused by damage while casting Arcane and Nature spells.", rq=nil}, {n="Furor", c="激怒", m=5, r=1, col=3, s="changed", i="spell_holy_blessingofstamina", d="使你有100%的几率在变身为熊形态或巨熊形态时获得10点怒气。当你变身为猎豹形态时，将恢复上次处于猎豹形态时所拥有能量的100%，外加你在未处于熊形态、猎豹形态或巨熊形态的每秒10点能量，最多100点能量。", dEn="Gives you a 100% chance to gain 10 Rage when you shapeshift into Bear Form or Dire Bear Form. When you shift into Cat Form, you will regain 100% of the Energy you had when you were last in Cat Form, plus 10 Energy for each second you spent not in Bear Form, Cat Form, or Dire Bear Form, up to a maximum of 100 Energy.", rq=nil}, {n="Naturalist", c="自然主义", m=5, r=2, col=1, s="changed", i="spell_nature_healingtouch", d="使你的治疗之触的施法时间缩短0.5秒，并使你造成的所有伤害提高5%。", dEn="Reduces the cast time of your Healing Touch spell by 0.5 sec and increases all damage you deal by 5%.", rq=nil}, {n="Subtlety", c="微妙", m=3, r=2, col=2, s="changed", i="ability_eyeoftheowl", d="使你的自然和奥术法术产生的威胁降低30%。", dEn="Reduces the threat generated by your Nature and Arcane spells by 30%.", rq=nil}, {n="Natural Shapeshifter", c="自然变形", m=3, r=2, col=3, s="moved", i="spell_nature_wispsplode", d="使你的所有变形法术所消耗的法力值降低30%。", dEn="Reduces the mana cost of all shapeshifting by 30%.", rq=nil}, {n="Reflection", c="反射", m=3, r=3, col=2, s="changed", i="spell_frost_windwalkon", d="使你在施法时仍保持50%的法力回复速度。", dEn="Allows 50% of your Mana regeneration to continue while casting.", rq=nil}, {n="Gift of Nature", c="自然赐福", m=5, r=3, col=3, s="changed", i="spell_nature_protectionformnature", d="使你的所有治疗法术效果提高10%。", dEn="Increases the effect of all your healing spells by 10%.", rq=nil}, {n="Gift of the Earthmother", c="大地母亲的恩赐", m=1, r=3, col=4, s="new", i="spell_nature_spiritarmor", d="使你的回春术、迅捷治愈和野性成长的公共冷却时间缩短0.5秒。", dEn="Reduces the global cooldown by 0.5 seconds on your Rejuvenation, Swiftmend, and Wild Growth spells.", rq=nil}, {n="Tranquil Spirit", c="宁静之魂", m=5, r=4, col=2, s="same", i="spell_holy_elunesgrace", d="使你的治疗之触和宁静所消耗的法力值减少10%。", dEn="Reduces the mana cost of your Healing Touch and Tranquility spells by 10%.", rq=nil}, {n="Improved Rejuvenation", c="强化回春术", m=3, r=4, col=3, s="same", i="spell_nature_rejuvenation", d="使你的回春术的效果提高15%。", dEn="Increases the effect of your Rejuvenation spell by 15%.", rq=nil}, {n="Swiftmend", c="迅捷治愈", m=1, r=4, col=4, s="changed", i="inv_relics_idolofrejuvenation", d="立即为一个带有回春术或愈合效果的目标恢复生命值，数值等于其中一个法术完整持续时间的周期性治疗效果。", dEn="Instantly heals a target with an active Rejuvenation or Regrowth effect for an amount equal to the full duration of the periodic effect of one of those spells.", rq=nil}, {n="Nature's Swiftness", c="自然迅捷", m=1, r=5, col=1, s="same", i="spell_nature_ravenform", d="激活之后，你的下一个自然法术会成为瞬发法术。", dEn="When activated, your next Nature spell becomes an instant cast spell.", rq={2, 1}}, {n="Living Spirit", c="生命之魂", m=3, r=5, col=2, s="new", i="spell_nature_giftofthewaterspirit", d="使你的精神提高15%。", dEn="Increases your Spirit by 15%.", rq=nil}, {n="Improved Tranquility", c="强化宁静", m=2, r=5, col=4, s="changed", i="spell_nature_tranquility", d="使你的宁静产生的威胁值降低100%，冷却时间缩短60%。", dEn="Reduces threat caused by Tranquility by 100% and its cooldown by 60%.", rq=nil}, {n="Improved Regrowth", c="强化愈合", m=5, r=6, col=3, s="same", i="spell_nature_resistnature", d="使你的愈合法术产生极效治疗效果的几率提高50%。", dEn="Increases the critical effect chance of your Regrowth spell by 50%.", rq={4, 3}}, {n="Wild Growth", c="野性成长", m=1, r=7, col=2, s="new", i="ability_druid_flourish", d="在7秒内为目标及其43码内的小队成员恢复336点生命值。治疗效果起初较快，随着野性成长接近结束而变慢。", dEn="Heals the target and their party for 336 over 7 sec. Party members must be within 43 yards of target. The amount healed is applied quickly at first, and slows down as Wild Growth reaches its full duration.", rq={5, 2}}}}},
  },
