    ["judgement"] = {k="spell", cn="改动。不再消耗你的圣印。10码射程，10秒冷却。审判怒火圣印会嘲讽目标4秒，圣骑士现在可以拉怪坦了。", en="Changed.It no longer eats your seal.10 yd range, 10 sec cooldown.Judging Seal of Fury taunts for 4 sec, so Paladins can tank pulls now."},
    ["审判"] = {k="spell", cn="改动。不再消耗你的圣印。10码射程，10秒冷却。审判怒火圣印会嘲讽目标4秒，圣骑士现在可以拉怪坦了。", en="Changed.It no longer eats your seal.10 yd range, 10 sec cooldown.Judging Seal of Fury taunts for 4 sec, so Paladins can tank pulls now."},
    ["seal of fury"] = {k="spell", cn="坦克圣印。每次命中附加神圣伤害，举盾时还能获得相当于该伤害一半的吸收盾。38级时到4级。", en="The tank seal.Every hit adds Holy damage, and with a shield up you get an absorb worth half of it.Rank 4 by level 38."},
    ["怒火圣印"] = {k="spell", cn="坦克圣印。每次命中附加神圣伤害，举盾时还能获得相当于该伤害一半的吸收盾。38级时到4级。", en="The tank seal.Every hit adds Holy damage, and with a shield up you get an absorb worth half of it.Rank 4 by level 38."},
    ["holy strike"] = {k="spell", cn="惩戒的基线打击，10秒冷却：武器伤害加神圣伤害。38级时到5级。多个天赋围绕它展开。", en="Baseline Ret strike on a 10 sec cooldown: weapon damage plus Holy.Rank 5 by 38.Several talents build on it."},
    ["神圣打击"] = {k="spell", cn="惩戒的基线打击，10秒冷却：武器伤害加神圣伤害。38级时到5级。多个天赋围绕它展开。", en="Baseline Ret strike on a 10 sec cooldown: weapon damage plus Holy.Rank 5 by 38.Several talents build on it."},
    ["blessing of kings and consecration"] = {k="spell", cn="两者现在都是训练师习得，不再是天赋。奉献20级学。", en="Both trainable now, not talents.Consecration comes at level 20."},
    ["王者祝福与奉献"] = {k="spell", cn="两者现在都是训练师习得，不再是天赋。奉献20级学。", en="Both trainable now, not talents.Consecration comes at level 20."},
    ["shadow word: death"] = {k="spell", cn="斩杀式暗影法术。由天赋「早夭」点名。", en="Execute-style Shadow spell.Named by the Early Demise talent."},
    ["暗言术：灭"] = {k="spell", cn="斩杀式暗影法术。由天赋「早夭」点名。", en="Execute-style Shadow spell.Named by the Early Demise talent."},
    ["devouring plague"] = {k="spell", cn="现在是普通暗影法术，不再是亡灵种族技能。38级时到3级，1分钟冷却。", en="A normal Shadow spell now, not an Undead racial.Rank 3 by 38, 1 min cooldown."},
    ["噬灵瘟疫"] = {k="spell", cn="现在是普通暗影法术，不再是亡灵种族技能。38级时到3级，1分钟冷却。", en="A normal Shadow spell now, not an Undead racial.Rank 3 by 38, 1 min cooldown."},
    ["fear ward"] = {k="spell", cn="所有牧师都有。3分钟冷却。", en="Every Priest gets it.3 min cooldown."},
    ["恐惧守卫"] = {k="spell", cn="所有牧师都有。3分钟冷却。", en="Every Priest gets it.3 min cooldown."},
    ["aimed shot"] = {k="spell", cn="现在是训练师习得而不是射击天赋，而且更快：2秒施法，6秒冷却，与多重射击共享冷却（Classic 是3秒施法）。38级时到3级。施法时间是一位读者在 Xaryu 直播里抓到的。", en="Rank 3 by 38.A reader caught the cast time on Xaryu's stream."},
    ["瞄准射击"] = {k="spell", cn="现在是训练师习得而不是射击天赋，而且更快：2秒施法，6秒冷却，与多重射击共享冷却（Classic 是3秒施法）。38级时到3级。施法时间是一位读者在 Xaryu 直播里抓到的。", en="Rank 3 by 38.A reader caught the cast time on Xaryu's stream."},
    ["call owl"] = {k="spell", cn="召唤宠物以你的宠物命名。试玩的猎人显示为「召唤猫头鹰」。", en="Call Pet is named after your pet.The demo Hunter's read Call Owl."},
    ["召唤猫头鹰"] = {k="spell", cn="召唤宠物以你的宠物命名。试玩的猎人显示为「召唤猫头鹰」。", en="Call Pet is named after your pet.The demo Hunter's read Call Owl."},
    ["aspect of the beast"] = {k="spell", cn="改动。1级使你无法被追踪并增加50点近战攻击强度。Classic 只有无法被追踪。由一位读者在 Xaryu 直播里发现。", en="Changed.Rank 1 makes you untrackable and adds 50 melee attack power.Spotted by a reader on Xaryu's stream."},
    ["野兽守护"] = {k="spell", cn="改动。1级使你无法被追踪并增加50点近战攻击强度。Classic 只有无法被追踪。由一位读者在 Xaryu 直播里发现。", en="Changed.Rank 1 makes you untrackable and adds 50 melee attack power.Spotted by a reader on Xaryu's stream."},
    ["comprehend scroll"] = {k="spell", cn="新的小技能：解读一张未翻译的卷轴。在一名天裔法师身上看到。", en="New little ability: decipher an untranslated scroll.Seen on a Skyborne Mage."},
    ["解读卷轴"] = {k="spell", cn="新的小技能：解读一张未翻译的卷轴。在一名天裔法师身上看到。", en="New little ability: decipher an untranslated scroll.Seen on a Skyborne Mage."},
    ["frostfire bolt"] = {k="spell", cn="一发同时属于火焰和冰霜的飞弹。四个天赋提到了它。", en="A bolt that is both Fire and Frost.Four talents mention it."},
    ["霜火之箭"] = {k="spell", cn="一发同时属于火焰和冰霜的飞弹。四个天赋提到了它。", en="A bolt that is both Fire and Frost.Four talents mention it."},
    ["subjugate demon"] = {k="spell", cn="奴役恶魔改名。38级时到1级。", en="Enslave Demon, renamed.Rank 1 by 38."},
    ["征服恶魔"] = {k="spell", cn="奴役恶魔改名。38级时到1级。", en="Enslave Demon, renamed.Rank 1 by 38."},
    ["bane of agony"] = {k="spell", cn="痛苦诅咒改名，厄运灾祸同理。灾祸和诅咒现在是两类，可以各挂一个。", en="Curse of Agony, renamed.Bane of Doom the same.Banes and Curses are now separate, so you can run one of each."},
    ["痛苦灾祸"] = {k="spell", cn="痛苦诅咒改名，厄运灾祸同理。灾祸和诅咒现在是两类，可以各挂一个。", en="Curse of Agony, renamed.Bane of Doom the same.Banes and Curses are now separate, so you can run one of each."},
    ["incubus"] = {k="spell", cn="魅魔的男性版本，独立召唤。四个恶魔学识天赋提到了它。", en="Male counterpart to the Succubus, its own summon.Named by four Demonology talents."},
    ["梦魇魔"] = {k="spell", cn="魅魔的男性版本，独立召唤。四个恶魔学识天赋提到了它。", en="Male counterpart to the Succubus, its own summon.Named by four Demonology talents."},
    ["rage"] = {k="spell", cn="怒气来自受到伤害和你的近战挥击。武器越慢，每次挥击获得的怒气越多，所以怒气会稳定地增长，而不是随你打得多重而变化。脱离战斗后每秒损失1.25点怒气（每分钟75点）。来自 Beta 的怒气说明，以及暴雪的职业亮点视频（0:23）。", en="Rage comes from taking damage and from your melee swings.Slower weapons give more Rage per swing, so it comes in at a steady rate instead of scaling with how hard you hit.Out of combat you lose 1.25 Rage a second (75 a minute).From the beta's Rage tooltip, and Blizzard's Class Highlights video (0:23)."},
    ["怒气"] = {k="spell", cn="怒气来自受到伤害和你的近战挥击。武器越慢，每次挥击获得的怒气越多，所以怒气会稳定地增长，而不是随你打得多重而变化。脱离战斗后每秒损失1.25点怒气（每分钟75点）。来自 Beta 的怒气说明，以及暴雪的职业亮点视频（0:23）。", en="Rage comes from taking damage and from your melee swings.Slower weapons give more Rage per swing, so it comes in at a steady rate instead of scaling with how hard you hit.Out of combat you lose 1.25 Rage a second (75 a minute).From the beta's Rage tooltip, and Blizzard's Class Highlights video (0:23)."},
    ["victory rush"] = {k="spell", cn="基线技能，在武器页。瞬发，30秒冷却：一次近战攻击，为你恢复最大生命值的10%，在击杀非琐碎目标后20秒内可用。由读者从 Soda 直播读出。", en="Baseline, in the Arms tab.Instant, 30 sec cooldown: a melee hit that heals you for 10% of your maximum health, usable within 20 sec of killing something non-trivial.Read off Soda's stream via a reader."},
    ["乘胜追击"] = {k="spell", cn="基线技能，在武器页。瞬发，30秒冷却：一次近战攻击，为你恢复最大生命值的10%，在击杀非琐碎目标后20秒内可用。由读者从 Soda 直播读出。", en="Baseline, in the Arms tab.Instant, 30 sec cooldown: a melee hit that heals you for 10% of your maximum health, usable within 20 sec of killing something non-trivial.Read off Soda's stream via a reader."},
    ["tactical mastery"] = {k="spell", cn="现在是武器页里的被动，不再是天赋。你自行切换姿态时可保留至多10点怒气，武器天赋「强化战术大师」再加至多15点。由读者从 Soda 的战士视频读出。", en="A passive in the Arms tab now, not a talent.You keep up to 10 Rage when you change stances on your own, and the Arms talent Improved Tactical Mastery adds up to 15 more.Read off Soda's Warrior video via a reader."},
    ["战术大师"] = {k="spell", cn="现在是武器页里的被动，不再是天赋。你自行切换姿态时可保留至多10点怒气，武器天赋「强化战术大师」再加至多15点。由读者从 Soda 的战士视频读出。", en="A passive in the Arms tab now, not a talent.You keep up to 10 Rage when you change stances on your own, and the Arms talent Improved Tactical Mastery adds up to 15 more.Read off Soda's Warrior video via a reader."},
    ["intercept"] = {k="spell", cn="还在游戏里：狂怒树有「强化拦截」。只是不在38级的法术书里，所以现在大概比30级学得晚。", en="Still in the game: the Fury tree has Improved Intercept.It just isn't in the level 38 spellbook, so it's probably learned later than 30 now."},
    ["拦截"] = {k="spell", cn="还在游戏里：狂怒树有「强化拦截」。只是不在38级的法术书里，所以现在大概比30级学得晚。", en="Still in the game: the Fury tree has Improved Intercept.It just isn't in the level 38 spellbook, so it's probably learned later than 30 now."},
    ["thunder clap"] = {k="spell", cn="已改动。战斗姿态或防御姿态均可使用。4级使攻击速度降低20%，持续22秒，最多命中4个目标；数据读自 Xaryu 的直播（感谢一位读者）；", en="Changed.Works in Battle or Defensive Stance.Read off Xaryu's stream, thanks to a reader;"},
    ["雷霆一击"] = {k="spell", cn="已改动。战斗姿态或防御姿态均可使用。4级使攻击速度降低20%，持续22秒，最多命中4个目标；数据读自 Xaryu 的直播（感谢一位读者）；", en="Changed.Works in Battle or Defensive Stance.Read off Xaryu's stream, thanks to a reader;"},
    ["bloodrage"] = {k="spell", cn="还在，在防护页。消耗116点生命值换10点怒气，并在10秒内再获得10点。", en="Still there, in the Protection tab.116 health for 10 rage plus 10 more over 10 sec."},
    ["血性狂暴"] = {k="spell", cn="还在，在防护页。消耗116点生命值换10点怒气，并在10秒内再获得10点。", en="Still there, in the Protection tab.116 health for 10 rage plus 10 more over 10 sec."},
    ["shield wall"] = {k="spell", cn="它不再与反击风暴和鲁莽共享冷却时间：Beta 文件里三者各有独立计时，暴雪在职业亮点视频（1:14）里也是这么说的。最早由两位读者指出。", en="It no longer shares a cooldown with Retaliation and Recklessness: each has its own timer in the beta files, and Blizzard says so in its Class Highlights video (1:14).Two readers flagged it first."},
    ["盾墙"] = {k="spell", cn="它不再与反击风暴和鲁莽共享冷却时间：Beta 文件里三者各有独立计时，暴雪在职业亮点视频（1:14）里也是这么说的。最早由两位读者指出。", en="It no longer shares a cooldown with Retaliation and Recklessness: each has its own timer in the beta files, and Blizzard says so in its Class Highlights video (1:14).Two readers flagged it first."},
    ["shield block"] = {k="spell", cn="改动：基线2层、7秒（Classic 是1次格挡、5秒）。仍是10点怒气、5秒冷却、防御姿态。由读者寄来的 Tyler1 法术书截图读出。", en="Still 10 Rage, 5 sec cooldown, Defensive Stance.Read from a Tyler1 spellbook screenshot a reader sent in."},
    ["盾牌格挡"] = {k="spell", cn="改动：基线2层、7秒（Classic 是1次格挡、5秒）。仍是10点怒气、5秒冷却、防御姿态。由读者寄来的 Tyler1 法术书截图读出。", en="Still 10 Rage, 5 sec cooldown, Defensive Stance.Read from a Tyler1 spellbook screenshot a reader sent in."},
    ["energy"] = {k="spell", cn="能量每0.1秒恢复1点，即每秒10点。来自 Beta 的能量说明，以及暴雪的职业亮点视频（3:41）。", en="Energy comes back 1 point every 0.1 sec, 10 a second.From the beta's Energy tooltip, and Blizzard's Class Highlights video (3:41)."},
    ["能量"] = {k="spell", cn="能量每0.1秒恢复1点，即每秒10点。来自 Beta 的能量说明，以及暴雪的职业亮点视频（3:41）。", en="Energy comes back 1 point every 0.1 sec, 10 a second.From the beta's Energy tooltip, and Blizzard's Class Highlights video (3:41)."},
    ["毒液"] = {k="spell", cn="刺杀树底部的新终结技。你的毒药伤害提高30%，触发几率提高10%，连击点越多持续越久。", en="New finisher at the bottom of Assassination.Your poisons do 30% more and apply 10% more often, longer per combo point."},
    ["axes"] = {k="spell", cn="潜行者现在可以用单手斧了。「劈砍」天赋把斧/剑列为一组武器。", en="Rogues can use one-handed axes now.The Hack and Slash talent lists Axe/Sword as a weapon group."},
    ["斧类武器"] = {k="spell", cn="潜行者现在可以用单手斧了。「劈砍」天赋把斧/剑列为一组武器。", en="Rogues can use one-handed axes now.The Hack and Slash talent lists Axe/Sword as a weapon group."},
    ["omen of clarity and nature's grasp"] = {k="spell", cn="两者现在都是训练师习得，不再是天赋。38级时在平衡页里。", en="Both trainable now, not talents.They're in the Balance tab at 38."},
    ["清晰预兆与自然之握"] = {k="spell", cn="两者现在都是训练师习得，不再是天赋。38级时在平衡页里。", en="Both trainable now, not talents.They're in the Balance tab at 38."},
    ["revive"] = {k="spell", cn="新的脱战复活，10秒施法。复生保留30分钟冷却。", en="New out-of-combat resurrection, 10 sec cast.Rebirth keeps its 30 min cooldown."},
    ["复活"] = {k="spell", cn="新的脱战复活，10秒施法。复生保留30分钟冷却。", en="New out-of-combat resurrection, 10 sec cast.Rebirth keeps its 30 min cooldown."},
    ["lacerate"] = {k="spell", cn="后续资料片的熊形态流血技能，在《无限》里作为基线技能：「撕碎攻击」天赋降低它的怒气消耗。不在38级的法术书里，所以学得更晚。感谢一位读者。", en="Bear bleed from later expansions, in Forever as a baseline ability: the Shredding Attacks talent cuts its Rage cost.Not in the level 38 spellbook, so it comes later.Thanks to a reader."},
    ["割伤"] = {k="spell", cn="后续资料片的熊形态流血技能，在《无限》里作为基线技能：「撕碎攻击」天赋降低它的怒气消耗。不在38级的法术书里，所以学得更晚。感谢一位读者。", en="Bear bleed from later expansions, in Forever as a baseline ability: the Shredding Attacks talent cuts its Rage cost.Not in the level 38 spellbook, so it comes later.Thanks to a reader."},
    ["cure poison"] = {k="spell", cn="没了。驱毒术是唯一的解毒手段。", en="Gone.Abolish Poison is the only poison cure."},
    ["消除中毒"] = {k="spell", cn="没了。驱毒术是唯一的解毒手段。", en="Gone.Abolish Poison is the only poison cure."},
    ["lightning bolt"] = {k="spell", cn="比 Classic 快半秒。7级是2.5秒施法。", en="Rank 7 is a 2.5 sec cast."},
    ["闪电箭"] = {k="spell", cn="比 Classic 快半秒。7级是2.5秒施法。", en="Rank 7 is a 2.5 sec cast."},
    ["chain lightning"] = {k="spell", cn="同样快半秒：1级是2秒施法，6秒冷却，3个目标，每次跳跃伤害减弱30%。元素迅捷点满后闪电箭同样是2秒。", en="Also half a second faster: rank 1 is a 2 sec cast, 6 sec cooldown, 3 targets, each jump 30% weaker.Max Elemental Alacrity brings Lightning Bolt to the same 2 sec."},
    ["闪电链"] = {k="spell", cn="同样快半秒：1级是2秒施法，6秒冷却，3个目标，每次跳跃伤害减弱30%。元素迅捷点满后闪电箭同样是2秒。", en="Also half a second faster: rank 1 is a 2 sec cast, 6 sec cooldown, 3 targets, each jump 30% weaker.Max Elemental Alacrity brings Lightning Bolt to the same 2 sec."},
    ["totemic projection"] = {k="spell", cn="新技能。选一个至多30码远的地点，你的图腾会移过去，不再只能放在脚下。在 Guzu 直播里看到：地上一个绿圈，然后图腾出现在怪旁边。图腾召回也在。", en="New.Pick a spot up to 30 yd away and your totems move there, not just to your feet.Seen on Guzu's stream: a green circle on the ground, then the totems appear by the mob.Totemic Recall is in too."},
    ["图腾投射"] = {k="spell", cn="新技能。选一个至多30码远的地点，你的图腾会移过去，不再只能放在脚下。在 Guzu 直播里看到：地上一个绿圈，然后图腾出现在怪旁边。图腾召回也在。", en="New.Pick a spot up to 30 yd away and your totems move there, not just to your feet.Seen on Guzu's stream: a green circle on the ground, then the totems appear by the mob.Totemic Recall is in too."},
    ["totems last 5 min"] = {k="spell", cn="持续型图腾现在持续5分钟。Beta 里祛病图腾仍然持续2分钟。灼热（30秒）、熔岩（20）、石爪（15）、地缚和根基（45）以及法力之潮（12）保持原来的短持续时间。来自 Beta 文件；暴雪的职业亮点视频（3:00）说的是五分钟。", en="Lasting totems last 5 min now.Disease Cleansing Totem still lasts 2 min in the beta.Searing (30 sec), Magma (20), Stoneclaw (15), Earthbind and Grounding (45) and Mana Tide (12) keep their short timers.From the beta files;Blizzard's Class Highlights video (3:00) says five minutes."},
    ["图腾持续5分钟"] = {k="spell", cn="持续型图腾现在持续5分钟。Beta 里祛病图腾仍然持续2分钟。灼热（30秒）、熔岩（20）、石爪（15）、地缚和根基（45）以及法力之潮（12）保持原来的短持续时间。来自 Beta 文件；暴雪的职业亮点视频（3:00）说的是五分钟。", en="Lasting totems last 5 min now.Disease Cleansing Totem still lasts 2 min in the beta.Searing (30 sec), Magma (20), Stoneclaw (15), Earthbind and Grounding (45) and Mana Tide (12) keep their short timers.From the beta files;Blizzard's Class Highlights video (3:00) says five minutes."},
    ["call of the elements, ancestors and spirits"] = {k="spell", cn="新增：每个技能都能用一次3秒的施法，从各自的图腾栏配置里一次放下最多四个图腾。元素的召唤20级、先祖的召唤30级、灵魂的召唤40级，所以到40级共有三套保存的配置。", en="New: each drops up to four totems from its own Totem Bar set in one 3 sec cast.Call of the Elements at 20, Call of the Ancestors at 30, Call of the Spirits at 40, so three saved sets by 40."},
    ["元素的召唤、先祖的召唤与灵魂的召唤"] = {k="spell", cn="新增：每个技能都能用一次3秒的施法，从各自的图腾栏配置里一次放下最多四个图腾。元素的召唤20级、先祖的召唤30级、灵魂的召唤40级，所以到40级共有三套保存的配置。", en="New: each drops up to four totems from its own Totem Bar set in one 3 sec cast.Call of the Elements at 20, Call of the Ancestors at 30, Call of the Spirits at 40, so three saved sets by 40."},
    ["ghost wolf"] = {k="spell", cn="仍然是3秒施法，但强化幽魂之狼现在1级减少1秒、2级减少全部3秒，并且可以在室内使用，所以2/2时为瞬发，与 Guzu 的鼠标提示一致。", en="Still a 3 sec cast, but Improved Ghost Wolf now takes 1 sec off at rank 1 and the whole 3 sec at rank 2, and lets it work indoors, so at 2/2 it is instant, as Guzu's tooltip showed."},
    ["幽魂之狼"] = {k="spell", cn="仍然是3秒施法，但强化幽魂之狼现在1级减少1秒、2级减少全部3秒，并且可以在室内使用，所以2/2时为瞬发，与 Guzu 的鼠标提示一致。", en="Still a 3 sec cast, but Improved Ghost Wolf now takes 1 sec off at rank 1 and the whole 3 sec at rank 2, and lets it work indoors, so at 2/2 it is instant, as Guzu's tooltip showed."},
    ["fire nova"] = {k="spell", cn="现在是法术，不再是图腾：30码射程，瞬发，10秒冷却时间，对你当前火焰图腾10码内的所有目标造成伤害（3级造成195到219点伤害，32级学会；5级造成413到459点，52级学会）。强化火焰新星使冷却时间缩短2或4秒。来自 Beta 客户端。", en="A spell now, not a totem: 30 yd range, instant, 10 sec cooldown, and it blasts everything within 10 yd of your active Fire totem (rank 3 does 195 to 219 and comes at 32, rank 5 413 to 459 at 52).Improved Fire Nova trims 2 or 4 sec off the cooldown.From the beta client."},
    ["火焰新星"] = {k="spell", cn="现在是法术，不再是图腾：30码射程，瞬发，10秒冷却时间，对你当前火焰图腾10码内的所有目标造成伤害（3级造成195到219点伤害，32级学会；5级造成413到459点，52级学会）。强化火焰新星使冷却时间缩短2或4秒。来自 Beta 客户端。", en="A spell now, not a totem: 30 yd range, instant, 10 sec cooldown, and it blasts everything within 10 yd of your active Fire totem (rank 3 does 195 to 219 and comes at 32, rank 5 413 to 459 at 52).Improved Fire Nova trims 2 or 4 sec off the cooldown.From the beta client."},
    ["blood fury"] = {k="racial", cn="《无限》种族天赋：瞬发，2 分钟冷却。使攻击强度和法术强度提高 10%，持续 15 秒。", en="Forever racial: Instant, 2 min cooldown.Increases Attack Power and Spell Power by 10% for 15 sec."},
    ["hardiness"] = {k="racial", cn="《无限》种族天赋：受到的昏迷效果持续时间缩短 20%。", en="Forever racial: Duration of Stun effects on you reduced by 20%."},
    ["axe specialization"] = {k="racial", cn="《无限》种族天赋：装备斧或双手斧时，你所有法术和技能的爆击几率提高 1%。", en="Forever racial: Increases your critical strike chance with all spells and abilities by 1% while you have an axe or a two-handed axe equipped."},
    ["斧专精"] = {k="racial", cn="《无限》种族天赋：装备斧或双手斧时，你所有法术和技能的爆击几率提高 1%。", en="Forever racial: Increases your critical strike chance with all spells and abilities by 1% while you have an axe or a two-handed axe equipped."},
    ["shatter curse"] = {k="racial", cn="《无限》种族天赋：瞬发，3 分钟冷却。立即解除所有诅咒和灾祸并获得免疫，同时受到的所有魔法伤害降低 15%，持续 8 秒。", en="Forever racial: Instant, 3 min cooldown.Instantly removes and grants immunity to all Curses and Banes, and reduces all Magical damage taken by 15% for 8 sec."},
    ["破咒"] = {k="racial", cn="《无限》种族天赋：瞬发，3 分钟冷却。立即解除所有诅咒和灾祸并获得免疫，同时受到的所有魔法伤害降低 15%，持续 8 秒。", en="Forever racial: Instant, 3 min cooldown.Instantly removes and grants immunity to all Curses and Banes, and reduces all Magical damage taken by 15% for 8 sec."},
    ["underwater breathing"] = {k="racial", cn="《无限》种族天赋：水下闭气时间延长 300%。", en="Forever racial: Underwater breath lasts 300% longer than normal."},
    ["水下呼吸"] = {k="racial", cn="《无限》种族天赋：水下闭气时间延长 300%。", en="Forever racial: Underwater breath lasts 300% longer than normal."},
    ["will of the forsaken"] = {k="racial", cn="《无限》种族天赋：瞬发，2 分钟冷却。立即解除所有魅惑、恐惧和睡眠效果。", en="Forever racial: Instant, 2 min cooldown.Instantly removes all Charm, Fear and Sleep effects."},
    ["被遗忘者的意志"] = {k="racial", cn="《无限》种族天赋：瞬发，2 分钟冷却。立即解除所有魅惑、恐惧和睡眠效果。", en="Forever racial: Instant, 2 min cooldown.Instantly removes all Charm, Fear and Sleep effects."},
    ["cannibalize"] = {k="racial", cn="《无限》种族天赋：5 码，瞬发，2 分钟冷却。激活后每 2 秒恢复 7% 总生命值和 7% 总法力值，持续 10 秒。只对 5 码内的人型生物或亡灵尸体有效。移动、动作或受到伤害都会打断。", en="Forever racial: 5 yd range, Instant, 2 min cooldown.When activated, regenerates 7% of total Health and 7% of total Mana every 2 sec for 10 sec.Only works on Humanoid or Undead corpses within 5 yds.Any movement, action, or damage taken while Cannibalizing will cancel the effect."},
    ["食尸"] = {k="racial", cn="《无限》种族天赋：5 码，瞬发，2 分钟冷却。激活后每 2 秒恢复 7% 总生命值和 7% 总法力值，持续 10 秒。只对 5 码内的人型生物或亡灵尸体有效。移动、动作或受到伤害都会打断。", en="Forever racial: 5 yd range, Instant, 2 min cooldown.When activated, regenerates 7% of total Health and 7% of total Mana every 2 sec for 10 sec.Only works on Humanoid or Undead corpses within 5 yds.Any movement, action, or damage taken while Cannibalizing will cancel the effect."},
    ["touch of the grave"] = {k="racial", cn="《无限》种族天赋：你的法术和攻击有一定几率（施法者 5%，近战 10%）从目标吸取生命，最多为你最大生命值的 5%。内置冷却 1 秒。", en="Forever racial: Your spells and attacks have a chance (5% for casters, 10% for melee) to drain Health from the target, up to 5% of your maximum Health.1 sec internal cooldown."},
    ["坟墓之触"] = {k="racial", cn="《无限》种族天赋：你的法术和攻击有一定几率（施法者 5%，近战 10%）从目标吸取生命，最多为你最大生命值的 5%。内置冷却 1 秒。", en="Forever racial: Your spells and attacks have a chance (5% for casters, 10% for melee) to drain Health from the target, up to 5% of your maximum Health.1 sec internal cooldown."},
    ["war stomp"] = {k="racial", cn="《无限》种族天赋：0.5 秒施法，2 分钟冷却。使 8 码内至多 5 个敌人昏迷 2 秒。", en="Forever racial: 0.5 sec cast, 2 min cooldown.Stuns up to 5 enemies within 8 yds for 2 sec."},
    ["战争践踏"] = {k="racial", cn="《无限》种族天赋：0.5 秒施法，2 分钟冷却。使 8 码内至多 5 个敌人昏迷 2 秒。", en="Forever racial: 0.5 sec cast, 2 min cooldown.Stuns up to 5 enemies within 8 yds for 2 sec."},
    ["耐力"] = {k="racial", cn="《无限》种族天赋：总生命值提高 5%，命中几率提高 1%。", en="Forever racial: Total Health increased by 5% and chance to hit increased by 1%."},
    ["cultivation"] = {k="racial", cn="《无限》种族天赋：瞬发。培育附近一株草药，长出一株副本，无需草药学技能即可采集。每株草药只能培育一次。", en="Forever racial: Instant.Cultivate a nearby herb, growing a duplicate you can harvest without requiring Herbalism skill.Each herb may only be cultivated once."},
    ["耕耘"] = {k="racial", cn="《无限》种族天赋：瞬发。培育附近一株草药，长出一株副本，无需草药学技能即可采集。每株草药只能培育一次。", en="Forever racial: Instant.Cultivate a nearby herb, growing a duplicate you can harvest without requiring Herbalism skill.Each herb may only be cultivated once."},
    ["plainsrunning"] = {k="racial", cn="《无限》种族天赋：每持续移动 5 秒，移动速度提高 1%，最高提高 30%。受到伤害或停下会削弱该效果。", en="Forever racial: Gain 1% increased movement speed every 5 sec spent moving, up to a maximum of 30% increase.Taking damage or standing still will reduce this effect."},
    ["平原奔跑"] = {k="racial", cn="《无限》种族天赋：每持续移动 5 秒，移动速度提高 1%，最高提高 30%。受到伤害或停下会削弱该效果。", en="Forever racial: Gain 1% increased movement speed every 5 sec spent moving, up to a maximum of 30% increase.Taking damage or standing still will reduce this effect."},
    ["berserking"] = {k="racial", cn="《无限》种族天赋：瞬发，3 分钟冷却。使你的施法速度和攻击速度提高 10%，持续 10 秒。", en="Forever racial: Instant, 3 min cooldown.Increases your spellcasting and attack speed by 10% for 10 sec."},
    ["regeneration"] = {k="racial", cn="《无限》种族天赋：生命回复速度提高 10%。此外，战斗中仍能保持 10% 的总生命回复。", en="Forever racial: Health regeneration rate increased by 10%.In addition, 10% of total Health regeneration will continue during combat."},
    ["再生"] = {k="racial", cn="《无限》种族天赋：生命回复速度提高 10%。此外，战斗中仍能保持 10% 的总生命回复。", en="Forever racial: Health regeneration rate increased by 10%.In addition, 10% of total Health regeneration will continue during combat."},
    ["beast slaying"] = {k="racial", cn="《无限》种族天赋：对野兽造成的伤害提高 5%。", en="Forever racial: Damage dealt versus Beasts increased by 5%."},
    ["野兽杀手"] = {k="racial", cn="《无限》种族天赋：对野兽造成的伤害提高 5%。", en="Forever racial: Damage dealt versus Beasts increased by 5%."},
    ["rapid regeneration"] = {k="racial", cn="《无限》种族天赋：引导，3 分钟冷却。在 6 秒内恢复你最大生命值的 50%。移动、动作或受到伤害都会打断。", en="Forever racial: Channeled, 3 min cooldown.Regenerate 50% of your maximum Health over 6 sec.Any movement, action, or damage taken will cancel the effect."},
    ["急速再生"] = {k="racial", cn="《无限》种族天赋：引导，3 分钟冷却。在 6 秒内恢复你最大生命值的 50%。移动、动作或受到伤害都会打断。", en="Forever racial: Channeled, 3 min cooldown.Regenerate 50% of your maximum Health over 6 sec.Any movement, action, or damage taken will cancel the effect."},
    ["walk on air"] = {k="racial", cn="《无限》种族天赋：瞬发，2 分钟冷却。在空中向下滑翔 10 秒，可控制方向。", en="Forever racial: Instant, 2 min cooldown.Glide downward through the air for 10 sec while controlling your direction of travel."},
    ["御风而行"] = {k="racial", cn="《无限》种族天赋：瞬发，2 分钟冷却。在空中向下滑翔 10 秒，可控制方向。", en="Forever racial: Instant, 2 min cooldown.Glide downward through the air for 10 sec while controlling your direction of travel."},
    ["skysight"] = {k="racial", cn="《无限》种族天赋：0.5 秒施法，2 分钟冷却。尝试从附近的元素汇聚点汲取力量并获得祝福，使移动速度和骑乘速度提高 10%。附近没有元素汇聚点时持续 30 秒，找到时持续 15 分钟。", en="Forever racial: 0.5 sec cast, 2 min cooldown.Attempt to draw power from a convergence of elements and receive its blessing, increasing your movement and mounted movement speeds by 10%.Lasts 30 sec if no elemental convergence is nearby, and 15 min if one is found."},
    ["天视"] = {k="racial", cn="《无限》种族天赋：0.5 秒施法，2 分钟冷却。尝试从附近的元素汇聚点汲取力量并获得祝福，使移动速度和骑乘速度提高 10%。附近没有元素汇聚点时持续 30 秒，找到时持续 15 分钟。", en="Forever racial: 0.5 sec cast, 2 min cooldown.Attempt to draw power from a convergence of elements and receive its blessing, increasing your movement and mounted movement speeds by 10%.Lasts 30 sec if no elemental convergence is nearby, and 15 min if one is found."},
    ["elemental insight"] = {k="racial", cn="《无限》种族天赋：对元素生物造成的伤害提高 5%。", en="Forever racial: Damage dealt versus Elementals increased by 5%."},
    ["元素洞察"] = {k="racial", cn="《无限》种族天赋：对元素生物造成的伤害提高 5%。", en="Forever racial: Damage dealt versus Elementals increased by 5%."},
    ["wind blessed"] = {k="racial", cn="《无限》种族天赋：使你的施法、近战和远程急速提高 1%。", en="Forever racial: Increases your spellcasting, melee, and ranged Haste by 1%."},
    ["风之祝福"] = {k="racial", cn="《无限》种族天赋：使你的施法、近战和远程急速提高 1%。", en="Forever racial: Increases your spellcasting, melee, and ranged Haste by 1%."},
    ["sword specialization"] = {k="racial", cn="《无限》种族天赋：装备剑或双手剑时，你所有法术和攻击的爆击几率提高 2%。", en="Forever racial: Increases your critical strike chance with all spells and attacks by 2% while you have a sword or two-handed sword equipped."},
    ["剑专精"] = {k="racial", cn="《无限》种族天赋：装备剑或双手剑时，你所有法术和攻击的爆击几率提高 2%。", en="Forever racial: Increases your critical strike chance with all spells and attacks by 2% while you have a sword or two-handed sword equipped."},
    ["the human spirit"] = {k="racial", cn="《无限》种族天赋：精神提高 5%。", en="Forever racial: Spirit increased by 5%."},
    ["人类精神"] = {k="racial", cn="《无限》种族天赋：精神提高 5%。", en="Forever racial: Spirit increased by 5%."},
    ["perception"] = {k="racial", cn="《无限》种族天赋：瞬发，3 分钟冷却。大幅提高潜行察觉能力，持续 20 秒。", en="Forever racial: Instant, 3 min cooldown.Dramatically increases stealth detection for 20 sec."},
    ["感知"] = {k="racial", cn="《无限》种族天赋：瞬发，3 分钟冷却。大幅提高潜行察觉能力，持续 20 秒。", en="Forever racial: Instant, 3 min cooldown.Dramatically increases stealth detection for 20 sec."},
    ["will to survive"] = {k="racial", cn="《无限》种族天赋：瞬发，3 分钟冷却。立即解除所有昏迷效果。", en="Forever racial: Instant, 3 min cooldown.Instantly removes all Stun effects."},
    ["求生意志"] = {k="racial", cn="《无限》种族天赋：瞬发，3 分钟冷却。立即解除所有昏迷效果。", en="Forever racial: Instant, 3 min cooldown.Instantly removes all Stun effects."},
    ["find treasure"] = {k="racial", cn="《无限》种族天赋：瞬发。让矮人感知附近的宝藏，并显示在小地图上。持续到取消为止。", en="Forever racial: Instant.Allows the dwarf to sense nearby treasure, making it appear on the minimap.Lasts until canceled."},
    ["寻找宝藏"] = {k="racial", cn="《无限》种族天赋：瞬发。让矮人感知附近的宝藏，并显示在小地图上。持续到取消为止。", en="Forever racial: Instant.Allows the dwarf to sense nearby treasure, making it appear on the minimap.Lasts until canceled."},
    ["stoneform"] = {k="racial", cn="《无限》种族天赋：瞬发，3 分钟冷却。立即解除所有流血、中毒和疾病效果并获得免疫，同时受到的所有物理伤害降低 10%，持续 8 秒。", en="Forever racial: Instant, 3 min cooldown.Instantly removes and grants immunity to all Bleed, Poison, and Disease effects, and reduces all Physical damage taken by 10% for 8 sec."},
    ["石像形态"] = {k="racial", cn="《无限》种族天赋：瞬发，3 分钟冷却。立即解除所有流血、中毒和疾病效果并获得免疫，同时受到的所有物理伤害降低 10%，持续 8 秒。", en="Forever racial: Instant, 3 min cooldown.Instantly removes and grants immunity to all Bleed, Poison, and Disease effects, and reduces all Physical damage taken by 10% for 8 sec."},
    ["mace specialization"] = {k="racial", cn="《无限》种族天赋：装备锤或双手锤时，你所有法术和攻击的爆击几率提高 1%。", en="Forever racial: Increases your critical strike chance with all spells and attacks by 1% while you have a mace or two-handed mace equipped."},
    ["锤专精"] = {k="racial", cn="《无限》种族天赋：装备锤或双手锤时，你所有法术和攻击的爆击几率提高 1%。", en="Forever racial: Increases your critical strike chance with all spells and attacks by 1% while you have a mace or two-handed mace equipped."},
    ["big game hunter"] = {k="racial", cn="《无限》种族天赋：对野兽造成的伤害提高 5%。", en="Forever racial: Damage dealt versus Beasts increased by 5%."},
    ["猎兽者"] = {k="racial", cn="《无限》种族天赋：对野兽造成的伤害提高 5%。", en="Forever racial: Damage dealt versus Beasts increased by 5%."},
    ["shadowmeld"] = {k="racial", cn="《无限》种族天赋：瞬发，10 秒冷却。激活后隐入阴影，降低敌人发现你的几率。持续到取消或移动为止。战斗中使用会让敌人不愿攻击你，但冷却时间变为 2 分钟。", en="Forever racial: Instant, 10 sec cooldown.Activate to slip into the shadows, reducing the chance for enemies to detect your presence.Lasts until cancelled or upon moving.Using this ability in combat discourages enemies from attacking you, but increases the cooldown to 2 min."},
    ["影遁"] = {k="racial", cn="《无限》种族天赋：瞬发，10 秒冷却。激活后隐入阴影，降低敌人发现你的几率。持续到取消或移动为止。战斗中使用会让敌人不愿攻击你，但冷却时间变为 2 分钟。", en="Forever racial: Instant, 10 sec cooldown.Activate to slip into the shadows, reducing the chance for enemies to detect your presence.Lasts until cancelled or upon moving.Using this ability in combat discourages enemies from attacking you, but increases the cooldown to 2 min."},
    ["quickness"] = {k="racial", cn="《无限》种族天赋：躲闪几率提高 1%，移动速度提高 2%。暗夜精灵盗贼和德鲁伊在潜行时更难被发现，相当于等级高 1 级。", en="Forever racial: Dodge chance increased by 1% and movement speed increased by 2%.Night Elf Rogues and Druids are harder to detect in Stealth as if they were 1 level higher."},
    ["敏捷"] = {k="racial", cn="《无限》种族天赋：躲闪几率提高 1%，移动速度提高 2%。暗夜精灵盗贼和德鲁伊在潜行时更难被发现，相当于等级高 1 级。", en="Forever racial: Dodge chance increased by 1% and movement speed increased by 2%.Night Elf Rogues and Druids are harder to detect in Stealth as if they were 1 level higher."},
    ["wisp spirit"] = {k="racial", cn="《无限》种族天赋：死亡后变为小精灵，移动速度提高 75%。", en="Forever racial: Transform into a wisp upon death, increasing movement speed by 75%."},
    ["小精灵形态"] = {k="racial", cn="《无限》种族天赋：死亡后变为小精灵，移动速度提高 75%。", en="Forever racial: Transform into a wisp upon death, increasing movement speed by 75%."},
    ["elune's light"] = {k="racial", cn="《无限》种族天赋：瞬发，3 分钟冷却。使你所有法术和攻击的爆击几率提高 10%，持续 15 秒。", en="Forever racial: Instant, 3 min cooldown.Increases your critical strike chance with all spells and attacks by 10% for 15 sec."},
    ["艾露恩之光"] = {k="racial", cn="《无限》种族天赋：瞬发，3 分钟冷却。使你所有法术和攻击的爆击几率提高 10%，持续 15 秒。", en="Forever racial: Instant, 3 min cooldown.Increases your critical strike chance with all spells and attacks by 10% for 15 sec."},
    ["escape artist"] = {k="racial", cn="《无限》种族天赋：瞬发，2 分钟冷却。立即摆脱任何移动减速效果，并在 3 秒内免疫这类效果。", en="Forever racial: Instant, 2 min cooldown.Instantly escape the effects of any movement impairing effect and gain immunity to those effects for 3 sec."},
    ["逃命专家"] = {k="racial", cn="《无限》种族天赋：瞬发，2 分钟冷却。立即摆脱任何移动减速效果，并在 3 秒内免疫这类效果。", en="Forever racial: Instant, 2 min cooldown.Instantly escape the effects of any movement impairing effect and gain immunity to those effects for 3 sec."},
    ["expansive mind"] = {k="racial", cn="《无限》种族天赋：最大法力值、怒气或能量提高 5%，取决于你的职业。", en="Forever racial: Maximum Mana, Rage or Energy increased by 5%, whichever your class uses."},
    ["广博心智"] = {k="racial", cn="《无限》种族天赋：最大法力值、怒气或能量提高 5%，取决于你的职业。", en="Forever racial: Maximum Mana, Rage or Energy increased by 5%, whichever your class uses."},
    ["engineering specialization"] = {k="racial", cn="《无限》种族天赋：你的侏儒巧思使你使用工程装置时失灵或反噬的几率降低 20%。", en="Forever racial: Your gnomish ingenuity reduces the rate of engineering devices failing or backfiring when you use them by 20%."},
    ["工程学专精"] = {k="racial", cn="《无限》种族天赋：你的侏儒巧思使你使用工程装置时失灵或反噬的几率降低 20%。", en="Forever racial: Your gnomish ingenuity reduces the rate of engineering devices failing or backfiring when you use them by 20%."},
    ["eureka!"] = {k="racial", cn="《无限》种族天赋：瞬发，2 分钟冷却。你接下来 3 个伤害性技能消耗降低（法力 -50%、怒气 -40%、能量 -20%；治疗者法力 -15% 且治疗量 +10%），并且伤害提高 10%。", en="Forever racial: Instant, 2 min cooldown.Your next 3 damaging abilities cost less (50% less Mana, 40% less Rage, 20% less Energy;15% less Mana for healers, who also heal 10% more) and deal 10% more damage."},
    ["灵光一现！"] = {k="racial", cn="《无限》种族天赋：瞬发，2 分钟冷却。你接下来 3 个伤害性技能消耗降低（法力 -50%、怒气 -40%、能量 -20%；治疗者法力 -15% 且治疗量 +10%），并且伤害提高 10%。", en="Forever racial: Instant, 2 min cooldown.Your next 3 damaging abilities cost less (50% less Mana, 40% less Rage, 20% less Energy;15% less Mana for healers, who also heal 10% more) and deal 10% more damage."},
    ["read ley line"] = {k="racial", cn="《无限》种族天赋：2 秒施法，2 分钟冷却。尝试接入附近的魔网能量，使生命和法力回复提高 100%。附近没有魔网时持续 15 秒，找到时持续 15 分钟。", en="Forever racial: 2 sec cast, 2 min cooldown.Attempt to tap into the power of a nearby ley line, increasing your Health and Mana regeneration by 100%.Lasts 15 sec if no ley line is nearby, and 15 min if one is found."},
    ["读取魔网"] = {k="racial", cn="《无限》种族天赋：2 秒施法，2 分钟冷却。尝试接入附近的魔网能量，使生命和法力回复提高 100%。附近没有魔网时持续 15 秒，找到时持续 15 分钟。", en="Forever racial: 2 sec cast, 2 min cooldown.Attempt to tap into the power of a nearby ley line, increasing your Health and Mana regeneration by 100%.Lasts 15 sec if no ley line is nearby, and 15 min if one is found."},
  },
  leveling = {milestones={{lv=1, t="选阵营 / 种族 / 职业", tEn="Pick faction, race and class", d="天裔建角色时自选阵营；主名 + 副名两栏都要填。练小号有传承系统：每个角色首发最多 16 点，开局最多攒 65 点。", dEn="Skyborne choose their faction at character creation; both a first and a second name are required. Alts get the Legacy system: up to 16 points per character at launch, 65 earnable in total.", fv=true}, {lv=5, t="学专业", tEn="Learn professions", d="两个主专业 + 烹饪 / 急救 / 钓鱼。60 级封顶、不出新资料片，专业一直值钱。", dEn="Two primary professions plus Cooking, First Aid and Fishing. With a permanent level 60 cap and no new expansions, professions keep their value.", fv=false}, {lv=10, t="天赋点开始", tEn="Talent points begin", d="每级 1 点，60 级共 51 点；第 1 行 0 点可点，每 5 点解锁下一行。猎人 10 级驯服宠物。", dEn="One point per level, 51 by level 60. Row 1 is available at 0 points; every 5 points unlocks the next row. Hunters tame their first pet at 10.", fv=false}, {lv=20, t="第一个 20 级地下城段", tEn="First level-20 dungeon bracket", d="哀嚎洞穴 / 死亡矿井 / 影牙城堡 / 塔恩之厅 / 洛丹伦废墟。", dEn="Wailing Caverns / The Deadmines / Shadowfang Keep / Halls of Thane / Ruins of Lordaeron.", fv=false}, {lv=30, t="德鲁伊旅行形态", tEn="Druid Travel Form", d="野外赶路第一个提速点。", dEn="The first real movement-speed upgrade for open-world travel.", fv=false}, {lv=40, t="骑术 + 坐骑", tEn="Riding and a mount", d="地面坐骑（无限没有飞行坐骑，是设计原则）。圣骑士 / 术士走职业坐骑任务。", dEn="Ground mounts only — no flying in Forever, by design. Paladins and Warlocks get theirs through class mount quests.", fv=false}, {lv=50, t="50 级后半段", tEn="Second half of the 50s", d="沉没的神庙 → 黑石深渊 → 厄运之槌，装备开始换紫。", dEn="Sunken Temple → Blackrock Depths → Dire Maul; epics start replacing blues.", fv=false}, {lv=58, t="60 级前的五本", tEn="The five pre-60 dungeons", d="黑石塔上下层 / 通灵学院 / 斯坦索姆 / 塑造者平台，预 BiS 都在这。", dEn="Lower and Upper Blackrock Spire / Scholomance / Stratholme / the Shaper's Terrace — pre-raid best-in-slot lives here.", fv=false}, {lv=60, t="封顶", tEn="Level cap", d="史诗坐骑；海加尔峰（20 人）/ 巴罗深渊（10 人）12 月 9 日开放，海加尔峰带传奇任务和 T1 套装。", dEn="Epic mount. Mount Hyjal (20-player) and the Barrow Deeps (10-player) open on December 9; Hyjal carries the legendary questline and Tier 1 sets.", fv=true}}, zones={{lv="1–10", a={"艾尔文森林", "丹莫罗", "泰达希尔"}, h={"杜隆塔尔", "莫高雷", "提瑞斯法林地"}, c={}, aEn={"Elwynn Forest", "Dun Morogh", "Teldrassil"}, hEn={"Durotar", "Mulgore", "Tirisfal Glades"}, cEn={}, fv={{n="泽风岛", nEn="Zephyr Isle", lv="1–12", d="天裔起始区（天空之墙）", dEn="Skyborne starting zone (Skywall)"}}}, {lv="10–20", a={"西部荒野", "洛克莫丹", "黑海岸"}, h={"贫瘠之地", "银松森林"}, c={}, aEn={"Westfall", "Loch Modan", "Darkshore"}, hEn={"The Barrens", "Silverpine Forest"}, cEn={}, fv={}}, {lv="20–30", a={"赤脊山", "暮色森林", "湿地"}, h={"石爪山脉", "希尔斯布莱德丘陵"}, c={"灰谷"}, aEn={"Redridge Mountains", "Duskwood", "Wetlands"}, hEn={"Stonetalon Mountains", "Hillsbrad Foothills"}, cEn={"Ashenvale"}, fv={}}, {lv="30–40", a={}, h={}, c={"荆棘谷", "千针石林", "凄凉之地", "阿拉希高地", "尘泥沼泽"}, aEn={}, hEn={}, cEn={"Stranglethorn Vale", "Thousand Needles", "Desolace", "Arathi Highlands", "Dustwallow Marsh"}, fv={{n="河谷地", nEn="Rivervale", lv="35–45", d="150+ 新任务、中立地精城、克罗多克要塞", dEn="150+ new quests, a neutral goblin town, Crodok Hold"}}}, {lv="40–50", a={}, h={}, c={"塔纳利斯", "菲拉斯", "辛特兰", "悲伤沼泽", "荒芜之地", "费伍德森林"}, aEn={}, hEn={}, cEn={"Tanaris", "Feralas", "The Hinterlands", "Swamp of Sorrows", "Badlands", "Felwood"}, fv={}}, {lv="50–60", a={}, h={}, c={"安戈洛环形山", "燃烧平原", "西瘟疫之地", "东瘟疫之地", "冬泉谷", "希利苏斯"}, aEn={}, hEn={}, cEn={"Un'Goro Crater", "Burning Steppes", "Western Plaguelands", "Eastern Plaguelands", "Winterspring", "Silithus"}, fv={{n="海加尔山", nEn="Mount Hyjal", lv="60", d="单人 + 组队内容，团本入口", dEn="solo and group content; raid entrance"}}}}, dungeons={{n="怒焰裂谷", nEn="Ragefire Chasm", lv="13–18", where="奥格瑞玛", whereEn="Orgrimmar", side="部落"}, {n="塔恩之厅", nEn="Halls of Thane", lv="13", where="丹莫罗", whereEn="Dun Morogh", side=""}, {n="洛丹伦废墟", nEn="Ruins of Lordaeron", lv="15+", where="提瑞斯法", whereEn="Tirisfal", side=""}, {n="哀嚎洞穴", nEn="Wailing Caverns", lv="17–24", where="贫瘠之地", whereEn="The Barrens", side=""}, {n="死亡矿井", 