ic", p=19.0}, {id=12969, n="横扫重锤", nEn="Seeping Willow", q="q3", slot="双手", i="inv_hammer_17", type="锤", ilvl=63, req=58, st={"155 - 233 伤害", "速度 3.60", "每秒伤害 53.9", "命中率： 使施法者身边半径8码范围内的敌人的所有属性降低20点，每3秒对它们造成20点自然伤害，持续30秒。"}, stEn={"155 - 233 Damage", "Speed 3.60", "53.9 damage per second", "Chance on hit: Lowers all stats by 20 and deals 20 Nature damage every 3 sec to all enemies within an 8 yard radius of the caster for 30 sec."}, seen=false, stSrc="classic", p=19.0}, {id=24101, n="书卷：凶猛撕咬 V", nEn="Book of Ferocious Bite V", q="q3", slot="配方", i="inv_misc_book_02", type="书", ilvl=60, req=60, st={"职业：德鲁伊", "使用：终结技，每个连击点造成伤害，并把多余的每点能量转化为2.7点额外伤害，伤害受攻击强度加成。1点：199-259点伤害；2点：346-406点伤害；3点：493-553点伤害；4点：640-700点伤害；5点：787-847点伤害", "“教你学会凶猛撕咬（等级 5）。”"}, stEn={"Classes: Druid", "Use: Finishing move that causes damage per combo point and converts each extra point of energy into 2.7 additional damage. Damage is increased by your Attack Power. 1 point : 199-259 damage 2 points: 346-406 damage 3 points: 493-553 damage 4 points: 640-700 damage 5 points: 787-847 damage", "\"Teaches Ferocious Bite (Rank 5).\""}, seen=false, p=13.0}, {id=19227, n="野兽之一", nEn="Ace of Beasts", q="q3", slot="任务", i="inv_misc_ticket_tarot_beasts_01", type="任务物品", ilvl=1, req=0, st={"使用：将八张野兽卡片收集起来以完成这副套牌。"}, stEn={"Use: Combine the Ace through Eight of Beasts to complete the set."}, seen=false, p=5.0}}}, {n="达基萨斯将军", nEn="General Drakkisath", ej="general drakkisath", items={{id=12592, n="沙赫拉姆黑剑", nEn="Blackblade of Shahram", q="q4", slot="双手", i="inv_sword_29", type="剑", ilvl=63, req=58, st={"166 - 250 伤害", "速度 3.50", "每秒伤害 59.4", "命中率： 召唤沙赫拉姆的灵魂。"}, stEn={"166 - 250 Damage", "Speed 3.50", "59.4 damage per second", "Chance on hit: Summons the infernal spirit of Shahram."}, seen=false, stSrc="classic", p=1.0}, {id=22267, n="织法者头巾", nEn="Spellweaver's Turban", q="q3", slot="头部", i="inv_helmet_62", type="布甲", ilvl=63, req=60, st={"73 护甲", "+9 智力", "装备：提高所有法术和魔法效果所造成的伤害和治疗效果，最多36点。", "装备：使你的法术击中敌人的几率提高1%。