    Priest = {{lv=1, id=585, n="惩击", i="spell_holy_holysmite", auto=true, d="对单体目标造成13到17点神圣伤害。"}, {lv=1, id=401977, n="暗影魔", i="spell_shadow_shadowfiend", auto=false, d="召唤一个暗影魔攻击目标。当暗影魔攻击时为施法者恢复5%的法力值。持续15 秒。"}, {lv=1, id=2050, n="次级治疗术", i="spell_holy_lesserheal", auto=true, d="治疗目标，恢复46到56点生命值。"}, {lv=1, id=1243, n="真言术：韧", i="spell_holy_wordfortitude", auto=false, d="圣洁的能量充满目标全身，令其耐力提高4点，持续1 小时。"}, {lv=4, id=589, n="暗言术：痛", i="spell_shadow_shadowwordpain", auto=false, d="黑暗的咒语，在18 秒内造成总计30点暗影伤害。"}, {lv=4, id=2052, n="次级治疗术", i="spell_holy_lesserheal", auto=false, d="治疗目标，恢复71到85点生命值。"}, {lv=6, id=591, n="惩击", i="spell_holy_holysmite", auto=false, d="对单体目标造成25到31点神圣伤害。"}, {lv=6, id=17, n="真言术：盾", i="spell_holy_powerwordshield", auto=false, d="汲取一名队伍成员的灵魂力量，为其施加护盾，吸收点伤害。持续30 秒。护盾存在期间，其施法不会因受到伤害而被打断。受到护盾保护后，该目标在15 秒内无法再次受到护盾保护。"}, {lv=8, id=139, n="恢复", i="spell_holy_renew", auto=false, d="治疗目标，在15 秒内恢复总计45点生命值。"}, {lv=8, id=586, n="渐隐术", i="spell_magic_lesserinvisibilty", auto=false, d="渐渐消失，使敌人不再攻击你，持续10 秒。"}, {lv=10, id=2006, n="复活术", i="spell_holy_resurrection", auto=false, d="复活一个死去的玩家，复活后该玩家拥有70点生命值和若干点法力值。无法在战斗中施放。"}, {lv=10, id=8092, n="心灵震爆", i="spell_shadow_unholyfrenzy", auto=false, d="用暗影魔法冲击敌人，对其造成37到41点暗影伤害，同时产生很高的威胁值。"}, {lv=10, id=10797, n="星辰碎片", i="spell_arcane_starfire", auto=false, d="召唤群星的碎片攻击敌人，在6 秒内对其造成162点奥术伤害。"}, {lv=10, id=594, n="暗言术：痛", i="spell_shadow_shadowwordpain", auto=false, d="黑暗的咒语，在18 秒内造成总计60点暗影伤害。"}, {lv=10, id=2053, n="次级治疗术", i="spell_holy_lesserheal", auto=false, d="治疗目标，恢复130到152点生命值。"}, {lv=10, id=1277370, n="神圣恩典", i="ability_priest_savinggrace", auto=false, d="立即为一名生命值低于50%的友方目标恢复131到167点生命值，并移除该目标身上的虚弱灵魂效果。不能对自己施放。"}, {lv=10, id=13908, n="绝望祷言", i="spell_holy_restoration", auto=false, d="立即为施法者回复131到167点生命值。"}, {lv=10, id=2652, n="虚弱之触", i="spell_shadow_deadofnight", auto=false, d="对施法者进行的下一次近战攻击会使攻击者受到8点暗影伤害，并使其近战攻击强度降低43点，持续2 分钟。"}, {lv=10, id=9035, n="虚弱妖术", i="spell_shadow_fingerofdeath", auto=false, d="削弱目标敌人，使其近战攻击强度降低43点，并使其受到的任何治疗效果降低20%。持续2 分钟。"}, {lv=10, id=1277455, n="迷惑闪光", i="ability_paladin_blindinglight2", auto=false, d="迷惑0码内的最多若干个敌人，持续3 秒。任何伤害都会打断此效果。"}, {lv=12, id=588, n="心灵之火", i="spell_holy_innerfire", auto=false, d="圣洁的能量充满施法者的体内，使的防御值提高315点。每次近战或远程伤害都会使牧师消耗一次防护能量。效果可持续10 分钟，或在若干次防护之后消失。"}, {lv=12, id=592, n="真言术：盾", i="spell_holy_powerwordshield", auto=false, d="立即为队友加上魔法护盾，可吸收86点伤害，持续30 秒。只要护盾存在，受保护者的施法就不会被物理攻击打断。目标在被加上护盾之后的15 秒内无法再被加上护盾。"}, {lv=12, id=1244, n="真言术：韧", i="spell_holy_wordfortitude", auto=false, d="圣洁的能量充满目标全身，令其耐力提高10点，持续1 小时。"}, {lv=14, id=8122, n="心灵尖啸", i="spell_shadow_psychicscream", auto=false, d="施法者发出心灵尖啸，使附近半径0码范围内的若干个敌人逃跑，持续8 秒。逃跑中的目标受到伤害则可能中断此效果。"}, {lv=14, id=6074, n="恢复", i="spell_holy_renew", auto=false, d="治疗目标，在15 秒内恢复总计75点生命值。"}, {lv=14, id=598, n="惩击", i="spell_holy_holysmite", auto=false, d="对单体目标造成43到49点神圣伤害。"}, {lv=14, id=528, n="祛病术", i="spell_holy_nullifydisease", auto=false, d="从友方目标身上移除1个疾病效果。"}, {lv=16, id=8102, n="心灵震爆", i="spell_shadow_unholyfrenzy", auto=false, d="用暗影魔法冲击敌人，对其造成65到71点暗影伤害，同时产生很高的威胁值。"}, {lv=16, id=2054, n="治疗术", i="spell_holy_heal", auto=false, d="治疗目标，恢复270到312点生命值。"}, {lv=18, id=19296, n="星辰碎片", i="spell_arcane_starfire", auto=false, d="召唤群星的碎片攻击敌人，在6 秒内对其造成300点奥术伤害。"}, {lv=18, id=970, n="暗言术：痛", i="spell_shadow_shadowwordpain", auto=false, d="黑暗的咒语，在18 秒内造成总计108点暗影伤害。"}, {lv=18, id=600, n="真言术：盾", i="spell_holy_powerwordshield", auto=false, d="立即为队友加上魔法护盾，可吸收154点伤害，持续30 秒。只要护盾存在，受保护者的施法就不会被物理攻击打断。目标在被加上护盾之后的15 秒内无法再被加上护盾。"}, {lv=18, id=1277371, n="神圣恩典", i="ability_priest_savinggrace", auto=false, d="立即为一名生命值低于50%的友方目标恢复247到305点生命值，并移除该目标身上的虚弱灵魂效果。不能对自己施放。"}, {lv=18, id=19236, n="绝望祷言", i="spell_holy_restoration", auto=false, d="立即为施法者回复247到305点生命值。"}, {lv=18, id=527, n="驱散魔法", i="spell_holy_dispelmagic", auto=false, d="驱散目标身上的魔法效果，从友方身上移除1个有害法术，或是从敌人身上移除1个有益法术。"}, {lv=20, id=2944, n="噬灵瘟疫", i="spell_shadow_devouringplague", auto=false, d="使目标患上疾病，在24 秒内造成总计128点暗影伤害，并为施法者恢复等量的生命值。"}, {lv=20, id=13896, n="回馈", i="spell_shadow_ritualofsacrifice", auto=false, d="牧师被一股反魔法能量笼罩。任何对牧师成功施放的敌对法术都会令施法者损失18点法力值，并对其造成等量的暗影伤害。效果持续15 秒。"}, {lv=20, id=453, n="安抚心灵", i="spell_holy_mindsooth", auto=false, d="安抚目标，使它的警戒范围减少10码。只对若干级及以下等级的人型目标有效。持续15 秒。"}, {lv=20, id=1277462, n="应急方案", i="ability_priest_soulwarding", auto=false, d="为一名盟友施加神圣结界，持续30 秒。下一次该盟友受到使其生命值降至35%以下的伤害时，将获得一个可吸收若干点伤害的护盾，并在15 秒内恢复若干点生命值。同一目标只能受到一个应急方案的影响。"}, {lv=20, id=7128, n="心灵之火", i="spell_holy_innerfire", auto=false, d="圣洁的能量充满施法者的体内，使的防御值提高495点。每次近战或远程伤害都会使牧师消耗一次防护能量。效果可持续10 分钟，或在若干次防护之后消失。"}, {lv=20, id=2061, n="快速治疗", i="spell_holy_flashheal", auto=false, d="治疗友方目标，恢复174到214点生命值。"}, {lv=20, id=6075, n="恢复", i="spell_holy_renew", auto=false, d="治疗目标，在15 秒内恢复总计125点生命值。"}, {lv=20, id=18137, n="暗影守卫", i="spell_nature_lightningshield", auto=false, d="施法者被暗影笼罩。如果施法者受到了法术、近战或远程伤害，则攻击者会受到13点暗影伤害。一个攻击者在短期内只会受到一次反噬伤害。这种伤害不会造成威胁值。可使用若干次，持续10 分钟。"}, {lv=20, id=9484, n="束缚亡灵", i="spell_nature_slow", auto=false, d="束缚敌对亡灵单位，最多持续30 秒。被束缚的亡灵无法移动、攻击或施法。任何对其造成伤害的行为都将解除束缚。一个牧师在同一时间内只能束缚一个目标。"}, {lv=20, id=9578, n="渐隐术", i="spell_magic_lesserinvisibilty", auto=false, d="渐渐消失，使敌人不再攻击你，持续10 秒。比渐隐术（等级 1）的效果更好。"}, {lv=20, id=14914, n="神圣之火", i="spell_holy_searinglight", auto=false, d="神圣的烈焰吞噬敌人，对其造成51到65点神圣伤害，并在10 秒内造成20点额外的神圣伤害。"}, {lv=20, id=23455, n="神圣新星", i="spell_holy_holynova", auto=false, d="", tal=true}, {lv=20, id=2651, n="艾露恩的赐福", i="spell_holy_elunesgrace", auto=false, d="使你被近战和远程攻击命中的几率降低50%，持续15 秒，或直到被未命中若干次为止。"}, {lv=20, id=19261, n="虚弱之触", i="spell_shadow_deadofnight", auto=false, d="对施法者进行的下一次近战攻击会使攻击者受到12点暗影伤害，并使其近战攻击强度降低57点，持续2 分钟。"}, {lv=20, id=19281, n="虚弱妖术", i="spell_shadow_fingerofdeath", auto=false, d="削弱目标敌人，使其近战攻击强度降低57点，并使其受到的任何治疗效果降低20%。持续2 分钟。"}, {lv=20, id=6346, n="防护恐惧结界", i="spell_holy_excorcism", auto=false, d="使友方目标获得抵抗恐惧的结界。下一次对该目标施放的恐惧效果会失败并消耗结界。结界持续3 分钟。"}, {lv=20, id=1277324, n="黑暗献祭", i="spell_holy_powerinfusion_shadow", auto=false, d="在15 秒内吞噬自身的400点生命值，以恢复400点法力值。"}, {lv=22, id=2010, n="复活术", i="spell_holy_resurrection", auto=false, d="复活一个死去的玩家，复活后该玩家拥有160点生命值和若干点法力值。无法在战斗中施放。"}, {lv=22, id=2096, n="心灵视界", i="spell_holy_mindvision", auto=false, d="使施法者通过目标的眼睛观察世界，持续1 分钟。"}, {lv=22, id=8103, n="心灵震爆", i="spell_shadow_unholyfrenzy", auto=false, d="用暗影魔法冲击敌人，对其造成98到104点暗影伤害，同时产生很高的威胁值。"}, {lv=22, id=984, n="惩击", i="spell_holy_holysmite", auto=false, d="对单体目标造成55到63点神圣伤害。"}, {lv=22, id=2055, n="治疗术", i="spell_holy_heal", auto=false, d="治疗目标，恢复378到432点生命值。"}, {lv=24, id=8129, n="法力燃烧", i="spell_shadow_manaburn", auto=false, d="从目标身上吸取191到203点法力值，每吸取1点法力值，目标就受到0.5点伤害。"}, {lv=24, id=3747, n="真言术：盾", i="spell_holy_powerwordshield", auto=false, d="立即为队友加上魔法护盾，可吸收226点伤害，持续30 秒。只要护盾存在，受保护者的施法就不会被物理攻击打断。目标在被加上护盾之后的15 秒内无法再被加上护盾。"}, {lv=24, id=1245, n="真言术：韧", i="spell_holy_wordfortitude", auto=false, d="圣洁的能量充满目标全身，令其耐力提高26点，持续1 小时。"}, {lv=24, id=15262, n="神圣之火", i="spell_holy_searinglight", auto=false, d="神圣的烈焰吞噬敌人，对其造成56到70点神圣伤害，并在10 秒内造成25点额外的神圣伤害。"}, {lv=25, id=401937, n="联结治疗", i="spell_holy_blindingheal", auto=false, d="为一个友方目标和施法者本身各恢复223到271点生命值。低威胁值的技能。", tal=true}, {lv=26, id=9472, n="快速治疗", i="spell_holy_flashheal", auto=false, d="治疗友方目标，恢复225到273点生命值。"}, {lv=26, id=6076, n="恢复", i="spell_holy_renew", auto=false, d="治疗目标，在15 秒内恢复总计160点生命值。"}, {lv=26, id=19299, n="星辰碎片", i="spell_arcane_starfire", auto=false, d="召唤群星的碎片攻击敌人，在6 秒内对其造成528点奥术伤害。"}, {lv=26, id=992, n="暗言术：痛", i="spell_shadow_shadowwordpain", auto=false, d="黑暗的咒语，在18 秒内造成总计180点暗影伤害。"}, {lv=26, id=1277372, n="神圣恩典", i="ability_priest_savinggrace", auto=false, d="立即为一名生命值低于50%的友方目标恢复414到502点生命值，并移除该目标身上的虚弱灵魂效果。不能对自己施放。"}, {lv=26, id=19238, n="绝望祷言", i="spell_holy_restoration", auto=false, d="立即为施法者回复414到502点生命值。"}, {lv=28, id=19276, n="噬灵瘟疫", i="spell_shadow_devouringplague", auto=false, d="使目标患上疾病，在24 秒内造成总计232点暗影伤害，并为施法者恢复等量的生命值。"}, {lv=28, id=8124, n="心灵尖啸", i="spell_shadow_psychicscream", auto=false, d="施法者发出心灵尖啸，使附近半径0码范围内的若干个敌人逃跑，持续8 秒。逃跑中的目标受到伤害则可能中断此效果。"}, {lv=28, id=8104, n="心灵震爆", i="spell_shadow_unholyfrenzy", auto=false, d="用暗影魔法冲击敌人，对其造成147到155点暗影伤害，同时产生很高的威胁值。"}, {lv=28, id=19308, n="暗影守卫", i="spell_nature_lightningshield", auto=false, d="施法者被暗影笼罩。如果施法者受到了法术、近战或远程伤害，则攻击者会受到22点暗影伤害。一个攻击者在短期内只会受到一次反噬伤害。这种伤害不会造成威胁值。可使用若干次，持续10 分钟。"}, {lv=28, id=6063, n="治疗术", i="spell_holy_heal02", auto=false, d="治疗目标，恢复490到556点生命值。"}, {lv=28, id=15430, n="神圣新星", i="spell_holy_holynova", auto=false, d="在施法者周围引发神圣光芒爆炸，对0码内所有敌方目标造成45到53点神圣伤害，并为10码内所有小队成员恢复77到87点生命值。这些效果不产生威胁值。\n\n每次神圣之火造成伤害时，你有5%的几率使下一个神圣新星不消耗法力值。", tal=true}, {lv=28, id=17311, n="精神鞭笞", i="spell_shadow_siphonmana", auto=false, d="以暗影能量冲击目标的心灵，在3 秒内造成102点暗影伤害，并使其移动速度降低-50%。", tal=true}, {lv=30, id=19271, n="回馈", i="spell_shadow_ritualofsacrifice", auto=false, d="牧师被一股反魔法能量笼罩。任何对牧师成功施放的敌对法术都会令施法者损失35点法力值，并对其造成等量的暗影伤害。效果持续15 秒。"}, {lv=30, id=1277634, n="应急方案", i="ability_priest_soulwarding", auto=false, d="为一名盟友施加神圣结界，持续30 秒。下一次该盟友受到使其生命值降至35%以下的伤害时，将获得一个可吸收若干点伤害的护盾，并在15 秒内恢复若干点生命值。同一目标只能受到一个应急方案的影响。"}, {lv=30, id=602, n="心灵之火", i="spell_holy_innerfire", auto=false, d="圣洁的能量充满施法者的体内，使的防御值提高720点。每次近战或远程伤害都会使牧师消耗一次防护能量。效果可持续10 分钟，或在若干次防护之后消失。"}, {lv=30, id=1004, n="惩击", i="spell_holy_holysmite", auto=false, d="对单体目标造成76到86点神圣伤害。"}, {lv=30, id=596, n="治疗祷言", i="spell_holy_prayerofhealing02", auto=false, d="强大的祷言，治疗目标及其小队，回复172到184点生命值。小队成员必须位于目标0码范围内。"}, {lv=30, id=9579, n="渐隐术", i="spell_magic_lesserinvisibilty", auto=false, d="渐渐消失，使敌人不再攻击你，持续10 秒。比渐隐术（等级 2）的效果更好。"}, {lv=30, id=6065, n="真言术：盾", i="spell_holy_powerwordshield", auto=false, d="立即为队友加上魔法护盾，可吸收291点伤害，持续30 秒。只要护盾存在，受保护者的施法就不会被物理攻击打断。目标在被加上护盾之后的15 秒内无法再被加上护盾。"}, {lv=30, id=15263, n="神圣之火", i="spell_holy_searinglight", auto=false, d="神圣的烈焰吞噬敌人，对其造成71到89点神圣伤害，并在10 秒内造成30点额外的神圣伤害。"}, {lv=30, id=605, n="精神控制", i="spell_shadow_shadowworddominate", auto=false, d="控制一个最高等级为32的人型目标，但是使其攻击间隔延长25%。最多持续1 分钟。"}, {lv=30, id=402174, n="苦修", i="spell_holy_penance", auto=false, d="向目标释放圣光能量，立即对一名敌人造成81点神圣伤害，或为一名盟友恢复184点生命值，并在接下来的2 秒内每1秒重复一次效果。", tal=true}, {lv=30, id=19262, n="虚弱之触", i="spell_shadow_deadofnight", auto=false, d="对施法者进行的下一次近战攻击会使攻击者受到18点暗影伤害，并使其近战攻击强度降低85点，持续2 分钟。"}, {lv=30, id=19282, n="虚弱妖术", i="spell_shadow_fingerofdeath", auto=false, d="削弱目标敌人，使其近战攻击强度降低85点，并使其受到的任何治疗效果降低20%。持续2 分钟。"}, {lv=30, id=976, n="防护暗影", i="spell_shadow_antishadow", auto=false, d="使目标对暗影法术的抗性提高30点，持续10 分钟。"}, {lv=30, id=1277325, n="黑暗献祭", i="spell_holy_powerinfusion_shadow", auto=false, d="在15 秒内吞噬自身的680点生命值，以恢复680点法力值。"}, {lv=32, id=9473, n="快速治疗", i="spell_holy_flashheal", auto=false, d="治疗友方目标，恢复283到341点生命值。"}, {lv=32, id=6077, n="恢复", i="spell_holy_renew", auto=false, d="治疗目标，在15 秒内恢复总计205点生命值。"}, {lv=32, id=1309595, n="暗言术：灭", i="spell_shadow_demonicfortitude", auto=false, d="黑暗束缚的咒语，对目标造成286到304点暗影伤害。如果你的目标没有被暗言术：灭杀死，你将承受相当于你最大生命值10%的伤害反噬。"}, {lv=32, id=8131, n="法力燃烧", i="spell_shadow_manaburn", auto=false, d="从目标身上吸取309到329点法力值，每吸取1点法力值，目标就受到0.5点伤害。"}, {lv=32, id=1240770, n="联结治疗", i="spell_holy_blindingheal", auto=false, d="为一个友方目标和施法者本身各恢复283到341点生命值。低威胁值的技能。", tal=true}, {lv=32, id=552, n="驱除疾病", i="spell_nature_nullifydisease", auto=false, d="尝试驱散目标身上的1个疾病效果，并每5秒驱散1个疾病效果，持续20 秒。"}, {lv=34, id=10880, n="复活术", i="spell_holy_resurrection", auto=false, d="复活一个死去的玩家，复活后该玩家拥有300点生命值和若干点法力值。无法在战斗中施放。"}, {lv=34, id=8105, n="心灵震爆", i="spell_shadow_unholyfrenzy", auto=false, d="用暗影魔法冲击敌人，对其造成190到202点暗影伤害，同时产生很高的威胁值。"}, {lv=34, id=19302, n="星辰碎片", i="spell_arcane_starfire", auto=false, d="召唤群星的碎片攻击敌人，在6 秒内对其造成762点奥术伤害。"}, {lv=34, id=2767, n="暗言术：痛", i="spell_shadow_shadowwordpain", auto=false, d="黑暗的咒语，在18 秒内造成总计288点暗影伤害。"}, {lv=34, id=6064, n="治疗术", i="spell_holy_heal02", auto=false, d="治疗目标，恢复611到691点生命值。"}, {lv=34, id=1706, n="漂浮术", i="spell_holy_layonhands", auto=false, d="使施法者漂浮在离地数尺的空中。漂浮时，你的下落速度降低，并可在水面等表面上移动。骑乘坐骑或受到任何伤害都会取消该效果。持续2 分钟。"}, {lv=34, id=1277374, n="神圣恩典", i="ability_priest_savinggrace", auto=false, d="立即为一名生命值低于50%的友方目标恢复540到650点生命值，并移除该目标身上的虚弱灵魂效果。不能对自己施放。"}, {lv=34, id=19240, n="绝望祷言", i="spell_holy_restoration", auto=false, d="立即为施法者回复540到650点生命值。"}, {lv=36, id=19277, n="噬灵瘟疫", i="spell_shadow_devouringplague", auto=false, d="使目标患上疾病，在24 秒内造成总计344点暗影伤害，并为施法者恢复等量的生命值。"}, {lv=36, id=8192, n="安抚心灵", i="spell_holy_mindsooth", auto=false, d="安抚目标，使它的警戒范围减少10码。只对若干级及以下等级的人型目标有效。持续15 秒。"}, {lv=36, id=19309, n="暗影守卫", i="spell_nature_lightningshield", auto=false, d="施法者被暗影笼罩。如果施法者受到了法术、近战或远程伤害，则攻击者会受到33点暗影伤害。一个攻击者在短期内只会受到一次反噬伤害。这种伤害不会造成威胁值。可使用若干次，持续10 分钟。"}, {lv=36, id=6066, n="真言术：盾", i="spell_holy_powerwordshield", auto=false, d="立即为队友加上魔法护盾，可吸收368点伤害，持续30 秒。只要护盾存在，受保护者的施法就不会被物理攻击打断。目标在被加上护盾之后的15 秒内无法再被加上护盾。"}, {lv=36, id=2791, n="真言术：韧", i="spell_holy_wordfortitude", auto=false, d="圣洁的能量充满目标全身，令其耐力提高42点，持续1 小时。"}, {lv=36, id=15264, n="神圣之火", i="spell_holy_searinglight", auto=false, d="神圣的烈焰吞噬敌人，对其造成81到103点神圣伤害，并在10 秒内造成35点额外的神圣伤害。"}, {lv=36, id=15431, n="神圣新星", i="spell_holy_holynova", auto=false, d="在施法者周围引发神圣光芒爆炸，对0码内所有敌方目标造成70到80点神圣伤害，并为10码内所有小队成员恢复108到124点生命值。这些效果不产生威胁值。\n\n每次神圣之火造成伤害时，你有5%的几率使下一个神圣新星不消耗法力值。", tal=true}, {lv=36, id=17312, n="精神鞭笞", i="spell_shadow_siphonmana", auto=false, d="以暗影能量冲击目标的心灵，在3 秒内造成153点暗影伤害，并使其移动速度降低-50%。", tal=true}, {lv=36, id=988, n="驱散魔法", i="spell_holy_dispelmagic", auto=false, d="驱散目标身上的魔法效果，从友方身上移除2个有害法术，或是从敌人身上移除2个有益法术。"}, {lv=38, id=9474, n="快速治疗", i="spell_holy_flashheal", auto=false, d="治疗友方目标，恢复349到417点生命值。"}, {lv=38, id=6078, n="恢复", i="spell_holy_renew", auto=false, d="治疗目标，在15 秒内恢复总计270点生命值。"}, {lv=38, id=6060, n="惩击", i="spell_holy_holysmite", auto=false, d="对单体目标造成88到100点神圣伤害。"}, {lv=38, id=1240771, n="联结治疗", i="spell_holy_blindingheal", auto=false, d="为一个友方目标和施法者本身各恢复349到417点生命值。低威胁值的技能。", tal=true}, {lv=40, id=7001, n="光明之泉回复", i="spell_holy_summonlightwell", auto=false, d=""}, {lv=40, id=19273, n="回馈", i="spell_shadow_ritualofsacrifice", auto=false, d="牧师被一股反魔法能量笼罩。任何对牧师成功施放的敌对法术都会令施法者损失54点法力值，并对其造成等量的暗影伤害。效果持续15 秒。"}, {lv=40, id=1277638, n="应急方案", i="ability_priest_soulwarding", auto=false, d="为一名盟友施加神圣结界，持续30 秒。下一次该盟友受到使其生命值降至35%以下的伤害时，将获得一个可吸收若干点伤害的护盾，并在15 秒内恢复若干点生命值。同一目标只能受到一个应急方案的影响。"}, {lv=40, id=2060, n="强效治疗术", i="spell_holy_greaterheal", auto=false, d="施法缓慢的法术，可以为单一目标治疗794到894点伤害。"}, {lv=40, id=1006, n="心灵之火", i="spell_holy_innerfire", auto=false, d="圣洁的能量充满施法者的体内，使的防御值提高945点。每次近战或远程伤害都会使牧师消耗一次防护能量。效果可持续10 分钟，或在若干次防护之后消失。"}, {lv=40, id=8106, n="心灵震爆", i="spell_shadow_unholyfrenzy", auto=false, d="用暗影魔法冲击敌人，对其造成250到266点暗影伤害，同时产生很高的威胁值。"}, {lv=40, id=401859, n="愈合祷言", i="spell_holy_prayerofmendingtga", auto=true, d="向目标施加一个法术，在该目标下一次受到伤害或获得非周期性治疗时为其恢复若干点生命值。这个治疗效果发生之后，愈合祷言会转移到20码范围内的小队或团队成员身上。最多可以转移5次，每次转移之后持续30 秒。每个施法者在同一时间内只能在一名目标身上施放该法术。", tal=true}, {lv=40, id=1309633, n="暗言术：灭", i="spell_shadow_demonicfortitude", auto=false, d="黑暗束缚的咒语，对目标造成359到381点暗影伤害。如果你的目标没有被暗言术：灭杀死，你将承受相当于你最大生命值10%的伤害反噬。"}, {lv=40, id=9485, n="束缚亡灵", i="spell_nature_slow", auto=false, d="束缚敌对亡灵单位，最多持续40 秒。被束缚的亡灵无法移动、攻击或施法。任何对其造成伤害的行为都将解除束缚。一个牧师在同一时间内只能束缚一个目标。"}, {lv=40, id=996, n="治疗祷言", i="spell_holy_prayerofhealing02", auto=false, d="强大的祷言，治疗目标及其小队，回复257到273点生命值。小队成员必须位于目标0码范围内。"}, {lv=40, id=10874, n="法力燃烧", i="spell_shadow_manaburn", auto=false, d="从目标身上吸取442到468点法力值，每吸取1点法力值，目标就受到0.5点伤害。"}, {lv=40, id=9592, n="渐隐术", i="spell_magic_lesserinvisibilty", auto=false, d="渐渐消失，使敌人不再攻击你，持续10 秒。比渐隐术（等级 3）的效果更好。"}, {lv=40, id=14818, n="神圣之灵", i="spell_holy_divinespirit", auto=false, d="圣洁的能量充满目标全身，令其精神提高23点，持续1 小时。"}, {lv=40, id=1240720, n="苦修", i="spell_holy_penance", auto=false, d="向目标释放圣光能量，立即对一名敌人造成113点神圣伤害，或为一名盟友恢复291点生命值，并在接下来的2 秒内每1秒重复一次效果。", tal=true}, {lv=40, id=19264, n="虚弱之触", i="spell_shadow_deadofnight", auto=false, d="对施法者进行的下一次近战攻击会使攻击者受到28点暗影伤害，并使其近战攻击强度降低106点，持续2 分钟。"}, {lv=40, id=19283, n="虚弱妖术", i="spell_shadow_fingerofdeath", auto=false, d="削弱目标敌人，使其近战攻击强度降低106点，并使其受到的任何治疗效果降低20%。持续2 分钟。"}, {lv=40, id=1277326, n="黑暗献祭", i="spell_holy_powerinfusion_shadow", auto=false, d="在15 秒内吞噬自身的980点生命值，以恢复980点法力值。"}, {lv=42, id=10888, n="心灵尖啸", i="spell_shadow_psychicscream", auto=false, d="施法者发出心灵尖啸，使附近半径0码范围内的若干个敌人逃跑，持续8 秒。逃跑中的目标受到伤害则可能中断此效果。"}, {lv=42, id=19303, n="星辰碎片", i="spell_arcane_starfire", auto=false, d="召唤群星的碎片攻击敌人，在6 秒内对其造成1068点奥术伤害。"}, {lv=42, id=10892, n="暗言术：痛", i="spell_shadow_shadowwordpain", auto=false, d="黑暗的咒语，在18 秒内造成总计426点暗影伤害。"}, {lv=42, id=10898, n="真言术：盾", i="spell_holy_powerwordshield", auto=false, d="立即为目标加上魔法护盾，可吸收470点伤害，持续30 秒。只要护盾存在，受保护者的施法就不会被物理攻击打断。目标在被加上护盾之后的15 秒内无法再被加上护盾。"}, {lv=42, id=15265, n="神圣之火", i="spell_holy_searinglight", auto=false, d="神圣的烈焰吞噬敌人，对其造成94到118点神圣伤害，并在10 秒内造成65点额外的神圣伤害。"}, {lv=42, id=1277376, n="神圣恩典", i="ability_priest_savinggrace", auto=false, d="立即为一名生命值低于50%的友方目标恢复781到931点生命值，并移除该目标身上的虚弱灵魂效果。不能对自己施放。"}, {lv=42, id=19241, n="绝望祷言", i="spell_holy_restoration", auto=false, d="立即为施法者回复781到931点生命值。"}, {lv=42, id=10957, n="防护暗影", i="spell_shadow_antishadow", auto=false, d="使目标对暗影法术的抗性提高45点，持续10 分钟。"}, {lv=44, id=19278, n="噬灵瘟疫", i="spell_shadow_devouringplague", auto=false, d="使目标患上疾病，在24 秒内造成总计488点暗影伤害，并为施法者恢复等量的生命值。"}, {lv=44, id=10909, n="心灵视界", i="spell_holy_mindvision", auto=false, d="使施法者通过目标的眼睛观察世界，持续1 分钟。如果该目标身处另一个副本区域或另一块大陆则无法施展。"}, {lv=44, id=10915, n="快速治疗", i="spell_holy_flashheal", auto=false, d="治疗友方目标，恢复463到551点生命值。"}, {lv=44, id=10927, n="恢复", i="spell_holy_renew", auto=false, d="治疗目标，在15 秒内恢复总计370点生命值。"}, {lv=44, id=19310, n="暗影守卫", i="spell_nature_lightningshield", auto=false, d="施法者被暗影笼罩。如果施法者受到了法术、近战或远程伤害，则攻击者会受到50点暗影伤害。一个攻击者在短期内只会受到一次反噬伤害。这种伤害不会造成威胁值。可使用若干次，持续10 分钟。"}, {lv=44, id=27799, n="神圣新星", i="spell_holy_holynova", auto=false, d="在施法者周围引发神圣光芒爆炸，对0码内所有敌方目标造成99到113点神圣伤害，并为10码内所有小队成员恢复147到171点生命值。这些效果不产生威胁值。\n\n每次神圣之火造成伤害时，你有5%的几率使下一个神圣新星不消耗法力值。", tal=true}, {lv=44, id=10911, n="精神控制", i="spell_shadow_shadowworddominate", auto=false, d="控制一个最高等级为47的人型目标，但是使其攻击间隔延长25%。最多持续1 分钟。"}, {lv=44, id=17313, n="精神鞭笞", i="spell_shadow_siphonmana", auto=false, d="以暗影能量冲击目标的心灵，在3 秒内造成225点暗影伤害，并使其移动速度降低-50%。", tal=true}, {lv=44, id=1240772, n="联结治疗", i="spell_holy_blindingheal", auto=false, d="为一个友方目标和施法者本身各恢复463到551点生命值。低威胁值的技能。", tal=true}, {lv=46, id=10881, n="复活术", i="spell_holy_resurrection", auto=false, d="复活一个死去的玩家，复活后该玩家拥有500点生命值和若干点法力值。无法在战斗中施放。"}, {lv=46, id=10963, n="强效治疗术", i="spell_holy_greaterheal", auto=false, d="施法缓慢的法术，可以为单一目标治疗1036到1162点伤害。"}, {lv=46, id=10945, n="心灵震爆", i="spell_shadow_unholyfrenzy", auto=false, d="用暗影魔法冲击敌人，对其造成315到333点暗影伤害，同时产生很高的威胁值。"}, {lv=46, id=10933, n="惩击", i="spell_holy_holysmite", auto=false, d="对单体目标造成119到133点神圣伤害。"}, {lv=48, id=21562, n="坚韧祷言", i="spell_holy_prayeroffortitude", auto=false, d="圣洁的能量充满小队和团队成员的身体，使其耐力提高56点，持续1 小时。"}, {lv=48, id=1309635, n="暗言术：灭", i="spell_shadow_demonicfortitude", auto=false, d="黑暗束缚的咒语，对目标造成391到415点暗影伤害。如果你的目标没有被暗言术：灭杀死，你将承受相当于你最大生命值10%的伤害反噬。"}, {lv=48, id=10875, n="法力燃烧", i="spell_shadow_manaburn", auto=false, d="从目标身上吸取576到610点法力值，每吸取1点法力值，目标就受到0.5点伤害。"}, {lv=48, id=10899, n="真言术：盾", i="spell_holy_powerwordshield", auto=false, d="立即为队友加上魔法护盾，可吸收591点伤害，持续30 秒。只要护盾存在，受保护者的施法就不会被物理攻击打断。目标在被加上护盾之后的15 秒内无法再被加上护盾。"}, {lv=48, id=10937, n="真言术：韧", i="spell_holy_wordfortitude", auto=false, d="圣洁的能量充满目标全身，令其耐力提高56点，持续1 小时。"}, {lv=48, id=15266, n="神圣之火", i="spell_holy_searinglight", auto=false, d="神圣的烈焰吞噬敌人，对其造成123到155点神圣伤害，并在10 秒内造成50点额外的神圣伤害。"}, {lv=50, id=27870, n="光明之泉", i="spell_holy_summonlightwell", auto=false, d="在牧师身边制造一个光明之泉。你所属的小队或团队中的友方单位可以点击光明之泉，在10 秒内恢复1165点生命值。被攻击会中断这个效果。光明之泉在3 分钟或者在被使用5次之后消失。"}, {lv=50, id=27873, n="光明之泉回复", i="spell_holy_summonlightwell", auto=false, d=""}, {lv=50, id=19274, n="回馈", i="spell_shadow_ritualofsacrifice", auto=false, d="牧师被一股反魔法能量笼罩。任何对牧师成功施放的敌对法术都会令施法者损失77点法力值，并对其造成等量的暗影伤害。效果持续15 秒。"}, {lv=50, id=1277639, n="应急方案", i="ability_priest_soulwarding", auto=false, d="为一名盟友施加神圣结界，持续30 秒。下一次该盟友受到使其生命值降至35%以下的伤害时，将获得一个可吸收若干点伤害的护盾，并在15 秒内恢复若干点生命值。同一目标只能受到一个应急方案的影响。"}, {lv=50, id=10951, n="心灵之火", i="spell_holy_innerfire", auto=false, d="圣洁的能量充满施法者的体内，使的防御值提高1170点。每次近战或远程伤害都会使牧师消耗一次防护能量。效果可持续10 分钟，或在若干次防护之后消失。"}, {lv=50, id=10916, n="快速治疗", i="spell_holy_flashheal", auto=false, d="治疗友方目标，恢复589到699点生命值。"}, {lv=50, id=10928, n="恢复", i="spell_holy_renew", auto=false, d="治疗目标，在15 秒内恢复总计510点生命值。"}, {lv=50, id=1240826, n="愈合祷言", i="spell_holy_prayerofmendingtga", auto=true, d="向目标施加一个法术，在该目标下一次受到伤害或获得非周期性治疗时为其恢复若干点生命值。这个治疗效果发生之后，愈合祷言会转移到20码范围内的小队或团队成员身上。最多可以转移5次，每次转移之后持续30 秒。每个施法者在同一时间内只能在一名目标身上施放该法术。", tal=true}, {lv=50, id=19304, n="星辰碎片", i="spell_arcane_starfire", auto=false, d="召唤群星的碎片攻击敌人，在6 秒内对其造成1440点奥术伤害。"}, {lv=50, id=10893, n="暗言术：痛", i="spell_shadow_shadowwordpain", auto=false, d="黑暗的咒语，在18 秒内造成总计582点暗影伤害。"}, {lv=50, id=10960, n="治疗祷言", i="spell_holy_prayerofhealing02", auto=false, d="强大的祷言，治疗目标及其小队，回复390到412点生命值。小队成员必须位于目标0码范围内。"}, {lv=50, id=10941, n="渐隐术", i="spell_magic_lesserinvisibilty", auto=false, d="渐渐消失，使敌人不再攻击你，持续10 秒。比渐隐术（等级 4）的效果更好。"}, {lv=50, id=14819, n="神圣之灵", i="spell_holy_divinespirit", auto=false, d="圣洁的能量充满目标全身，令其精神提高33点，持续1 小时。"}, {lv=50, id=1277377, n="神圣恩典", i="ability_priest_savinggrace", auto=false, d="立即为一名生命值低于50%的友方目标恢复1046到1240点生命值，并移除该目标身上的虚弱灵魂效果。不能对自己施放。"}, {lv=50, id=19242, n="绝望祷言", i="spell_holy_restoration", auto=false, d="立即为施法者回复1046到1240点生命值。"}, {lv=50, id=1240773, n="联结治疗", i="spell_holy_blindingheal", auto=false, d="为一个友方目标和施法者本身各恢复589到699点生命值。低威胁值的技能。", tal=true}, {lv=50, id=1240721, n="苦修", i="spell_holy_penance", auto=false, d="向目标释放圣光能量，立即对一名敌人造成180点神圣伤害，或为一名盟友恢复482点生命值，并在接下来的2 秒内每1秒重复一次效果。", tal=true}, {lv=50, id=19265, n="虚弱之触", i="spell_shadow_deadofnight", auto=false, d="对施法者进行的下一次近战攻击会使攻击者受到40点暗影伤害，并使其近战攻击强度降低155点，持续2 分钟。"}, {lv=50, id=19284, n="虚弱妖术", i="spell_shadow_fingerofdeath", auto=false, d="削弱目标敌人，使其近战攻击强度降低155点，并使其受到的任何治疗效果降低20%。持续2 分钟。"}, {lv=50, id=0, n="野性印记", i="", auto=false, d="", quest=true}, {lv=50, id=1277327, n="黑暗献祭", i="spell_holy_powerinfusion_shadow", auto=false, d="在15 秒内吞噬自身的1290点生命值，以恢复1290点法力值。"}, {lv=52, id=19279, n="噬灵瘟疫", i="spell_shadow_devouringplague", auto=false, d="使目标患上疾病，在24 秒内造成总计656点暗影伤害，并为施法者恢复等量的生命值。"}, {lv=52, id=10953, n="安抚心灵", i="spell_holy_mindsooth", auto=false, d="安抚目标，使它的警戒范围减少10码。只对若干级及以下等级的人型目标有效。持续15 秒。"}, {lv=52, id=10964, n="强效治疗术", i="spell_holy_greaterheal", auto=false, d="施法缓慢的法术，可以为单一目标治疗1324到1482点伤害。"}, {lv=52, id=10946, n="心灵震爆", i="spell_shadow_unholyfrenzy", auto=false, d="用暗影魔法冲击敌人，对其造成394到416点暗影伤害，同时产生很高的威胁值。"}, {lv=52, id=19311, n="暗影守卫", i="spell_nature_lightningshield", auto=false, d="施法者被暗影笼罩。如果施法者受到了法术、近战或远程伤害，则攻击者会受到70点暗影伤害。一个攻击者在短期内只会受到一次反噬伤害。这种伤害不会造成威胁值。可使用若干次，持续10 分钟。"}, {lv=52, id=27800, n="神圣新星", i="spell_holy_holynova", auto=false, d="在施法者周围引发神圣光芒爆炸，对0码内所有敌方目标造成133到153点神圣伤害，并为10码内所有小队成员恢复221到255点生命值。这些效果不产生威胁值。\n\n每次神圣之火造成伤害时，你有5%的几率使下一个神圣新星不消耗法力值。", tal=true}, {lv=52, id=17314, n="精神鞭笞", i="spell_shadow_siphonmana", auto=false, d="以暗影能量冲击目标的心灵，在3 秒内造成294点暗影伤害，并使其移动速度降低-50%。", tal=true}, {lv=54, id=10934, n="惩击", i="spell_holy_holysmite", auto=false, d="对单体目标造成160到180点神圣伤害。"}, {lv=54, id=10900, n="真言术：盾", i="spell_holy_powerwordshield", auto=false, d="立即为目标加上魔法护盾，可吸收749点伤害，持续30 秒。只要护盾存在，受保护者的施法就不会被物理攻击打断。目标在被加上护盾之后的15 秒内无法再被加上护盾。"}, {lv=54, id=15267, n="神圣之火", i="spell_holy_searinglight", auto=false, d="神圣的烈焰吞噬敌人，对其造成152到194点神圣伤害，并在10 秒内造成65点额外的神圣伤害。"}, {lv=56, id=10890, n="心灵尖啸", i="spell_shadow_psychicscream", auto=false, d="施法者发出心灵尖啸，使附近半径0码范围内的若干个敌人逃跑，持续8 秒。逃跑中的目标受到伤害则可能中断此效果。"}, {lv=56, id=10917, n="快速治疗", i="spell_holy_flashheal", auto=false, d="治疗友方目标，恢复757到893点生命值。"}, {lv=56, id=10929, n="恢复", i="spell_holy_renew", auto=false, d="治疗目标，在15 秒内恢复总计670点生命值。"}, {lv=56, id=27683, n="暗影防护祷言", i="spell_holy_prayerofshadowprotection", auto=false, d="力量注入所有队伍和团队成员，使其暗影抗性提高60点，持续20 分钟。"}, {lv=56, id=1309636, n="暗言术：灭", i="spell_shadow_demonicfortitude", auto=false, d="黑暗束缚的咒语，对目标造成434到462点暗影伤害。如果你的目标没有被暗言术：灭杀死，你将承受相当于你最大生命值10%的伤害反噬。"}, {lv=56, id=10876, n="法力燃烧", i="spell_shadow_manaburn", auto=false, d="从目标身上吸取738到780点法力值，每吸取1点法力值，目标就受到0.5点伤害。"}, {lv=56, id=1240774, n="联结治疗", i="spell_holy_blindingheal", auto=false, d="为一个友方目标和施法者本身各恢复757到893点生命值。低威胁值的技能。", tal=true}, {lv=56, id=10958, n="防护暗影", i="spell_shadow_antishadow", auto=false, d="使目标对暗影法术的抗性提高60点，持续10 分钟。"}, {lv=58, id=20770, n="复活术", i="spell_holy_resurrection", auto=false, d="复活一个死去的玩家，复活后该玩家拥有750点生命值和若干点法力值。无法在战斗中施放。"}, {lv=58, id=10965, n="强效治疗术", i="spell_holy_greaterheal", auto=false, d="施法缓慢的法术，可以为单一目标治疗1685到1879点伤害。"}, {lv=58, id=10947, n="心灵震爆", i="spell_shadow_unholyfrenzy", auto=false, d="用暗影魔法冲击敌人，对其造成472到498点暗影伤害，同时产生很高的威胁值。"}, {lv=58, id=19305, n="星辰碎片", i="spell_arcane_starfire", auto=false, d="召唤群星的碎片攻击敌人，在6 秒内对其造成1800点奥术伤害。"}, {lv=58, id=10894, n="暗言术：痛", i="spell_shadow_shadowwordpain", auto=false, d="黑暗的咒语，在18 秒内造成总计762点暗影伤害。"}, {lv=58, id=1277378, n="神圣恩典", i="ability_priest_savinggrace", auto=false, d="立即为一名生命值低于50%的友方目标恢复1269到1497点生命值，并移除该目标身上的虚弱灵魂效果。不能对自己施放。"}, {lv=58, id=10912, n="精神控制", i="spell_shadow_shadowworddominate", auto=false, d="控制一个最高等级为62的人型目标，但是使其攻击间隔延长25%。最多持续1 分钟。"}, {lv=58, id=19243, n="绝望祷言", i="spell_holy_restoration", auto=false, d="立即为施法者回复1269到1497点生命值。"}, {lv=60, id=27871, n="光明之泉", i="spell_holy_summonlightwell", auto=false, d="在牧师身边制造一个光明之泉。你所属的小队或团队中的友方单位可以点击光明之泉，在10 秒内恢复1600点生命值。被攻击会中断这个效果。光明之泉在3 分钟或者在被使用5次之后消失。"}, {lv=60, id=27874, n="光明之泉回复", i="spell_holy_summonlightwell", auto=false, d=""}, {lv=60, id=19280, n="噬灵瘟疫", i="spell_shadow_devouringplague", auto=false, d="使目标患上疾病，在24 秒内造成总计848点暗影伤害，并为施法者恢复等量的生命值。"}, {lv=60, id=19275, n="回馈", i="spell_shadow_ritualofsacrifice", auto=false, d="牧师被一股反魔法能量笼罩。任何对牧师成功施放的敌对法术都会令施法者损失105点法力值，并对其造成等量的暗影伤害。效果持续15 秒。"}, {lv=60, id=21564, n="坚韧祷言", i="spell_holy_prayeroffortitude", auto=false, d="圣洁的能量充满小队和团队成员的身体，使其耐力提高70点，持续1 小时。"}, {lv=60, id=1277640, n="应急方案", i="ability_priest_soulwarding", auto=false, d="为一名盟友施加神圣结界，持续30 秒。下一次该盟友受到使其生命值降至35%以下的伤害时，将获得一个可吸收若干点伤害的护盾，并在15 秒内恢复若干点生命值。同一目标只能受到一个应急方案的影响。"}, {lv=60, id=25314, n="强效治疗术", i="spell_holy_greaterheal", auto=false, d="施法缓慢的法术，可以为单一目标治疗1853到2067点伤害。"}, {lv=60, id=10952, n="心灵之火", i="spell_holy_innerfire", auto=false, d="圣洁的能量充满施法者的体内，使的防御值提高1395点。每次近战或远程伤害都会使牧师消耗一次防护能量。效果可持续10 分钟，或在若干次防护之后消失。"}, {lv=60, id=25315, n="恢复", i="spell_holy_renew", auto=false, d="治疗目标，在15 秒内恢复总计830点生命值。"}, {lv=60, id=1240827, n="愈合祷言", i="spell_holy_prayerofmendingtga", auto=true, d="向目标施加一个法术，在该目标下一次受到伤害或获得非周期性治疗时为其恢复若干点生命值。这个治疗效果发生之后，愈合祷言会转移到20码范围内的小队或团队成员身上。最多可以转移5次，每次转移之后持续30 秒。每个施法者在同一时间内只能在一名目标身上施放该法术。", tal=true}, {lv=60, id=19312, n="暗影守卫", i="spell_nature_lightningshield", auto=false, d="施法者被暗影笼罩。如果施法者受到了法术、近战或远程伤害，则攻击者会受到96点暗影伤害。一个攻击者在短期内只会受到一次反噬伤害。这种伤害不会造成威胁值。可使用若干次，持续10 分钟。"}, {lv=60, id=10955, n="束缚亡灵", i="spell_nature_slow", auto=false, d="束缚敌对亡灵单位，最多持续50 秒。被束缚的亡灵无法移动、攻击或施法。任何对其造成伤害的行为都将解除束缚。一个牧师在同一时间内只能束缚一个目标。"}, {lv=60, id=10961, n="治疗祷言", i="spell_holy_prayerofhealing02", auto=false, d="强大的祷言，治疗目标及其小队，回复567到599点生命值。小队成员必须位于目标0码范围内。"}, {lv=60, id=25316, n="治疗祷言", i="spell_holy_prayerofhealing02", auto=false, d="强大的祷言，治疗目标及其小队，回复631到667点生命值。小队成员必须位于目标0码范围内。"}, {lv=60, id=10942, n="渐隐术", i="spell_magic_lesserinvisibilty", auto=false, d="渐渐消失，使敌人不再攻击你，持续10 秒。比渐隐术（等级 5）的效果更好。"}, {lv=60, id=10901, n="真言术：盾", i="spell_holy_powerwordshield", auto=false, d="立即为目标加上魔法护盾，可吸收928点伤害，持续30 秒。只要护盾存在，受保护者的施法就不会被物理攻击打断。目标在被加上护盾之后的15 秒内无法再被加上护盾。"}, {lv=60, id=10938, n="真言术：韧", i="spell_holy_wordfortitude", auto=false, d="圣洁的能量充满目标全身，令其耐力提高70点，持续1 小时。"}, {lv=60, id=15261, n="神圣之火", i="spell_holy_searinglight", auto=false, d="神圣的烈焰吞噬敌人，对其造成184到232点神圣伤害，并在10 秒内造成75点额外的神圣伤害。"}, {lv=60, id=27841, n="神圣之灵", i="spell_holy_divinespirit", auto=false, d="圣洁的能量充满目标全身，令其精神提高40点，持续1 小时。"}, {lv=60, id=27801, n="神圣新星", i="spell_holy_holynova", auto=false, d="在施法者周围引发神圣光芒爆炸，对0码内所有敌方目标造成174到200点神圣伤害，并为10码内所有小队成员恢复288到334点生命值。这些效果不产生威胁值。\n\n每次神圣之火造成伤害时，你有5%的几率使下一个神圣新星不消耗法力值。", tal=true}, {lv=60, id=27681, n="精神祷言", i="spell_holy_prayerofspirit", auto=false, d="将力量注入所有小队和团队成员体内，使其精神提高40点，持续1 小时。"}, {lv=60, id=18807, n="精神鞭笞", i="spell_shadow_siphonmana", auto=false, d="以暗影能量冲击目标的心灵，在3 秒内造成390点暗影伤害，并使其移动速度降低-50%。", tal=true}, {lv=60, id=1316995, n="苦修", i="spell_holy_penance", auto=false, d="Launches a volley of holy light at the target, causing 131 Holy damage to an enemy, or 673 healing to an ally, instantly and every 1 sec for 2 秒.", tal=true}, {lv=60, id=19266, n="虚弱之触", i="spell_shadow_deadofnight", auto=false, d="对施法者进行的下一次近战攻击会使攻击者受到56点暗影伤害，并使其近战攻击强度降低204点，持续2 分钟。"}, {lv=60, id=19285, n="虚弱妖术", i="spell_shadow_fingerofdeath", auto=false, d="削弱目标敌人，使其近战攻击强度降低204点，并使其受到的任何治疗效果降低20%。持续2 分钟。"}, {lv=60, id=1277328, n="黑暗献祭", i="spell_holy_powerinfusion_shadow", auto=false, d="在15 秒内吞噬自身的1600点生命值，以恢复1600点法力值。"}},
    Shaman = {{lv=1, id=425336, n="先知之怒", i="spell_nature_bloodlust", auto=false, d="使你的近战攻击速度和施法速度提高30%，持续25 秒。", tal=true}, {lv=1, id=331, n="治疗波", i="spell_nature_magicimmunity", auto=true, d="治疗友方目标，恢复34到44点生命值。"}, {lv=1, id=8017, n="石化武器", i="spell_nature_rockbiter", auto=false, d="强化萨满祭司的武器，使其近战攻击强度提高29点，使用该武器对敌人造成近战伤害时产生额外的威胁值。强化效果持续60分钟。"}, {lv=1, id=403, n="闪电箭", i="spell_nature_lightning", auto=true, d="向目标射出闪电箭，对其造成若干点伤害。"}, {lv=4, id=8042, n="地震术", i="spell_nature_earthshock", auto=false, d="立即以震撼性的力量攻击目标，对其造成17到19点自然伤害，同时打断施法，并使其在2 秒内无法施放该系法术。产生大量的威胁值。"}, {lv=4, id=8071, n="石肤图腾", i="spell_nature_stoneskintotem", auto=false, d="在施法者脚下召唤一个拥有5点生命值的石肤图腾。该图腾保护30码内的队伍成员，使其受到的物理伤害降低4点。持续5 分钟。"}, {lv=6, id=2484, n="地缚图腾", i="spell_nature_strengthofearthtotem02", auto=false, d="在施法者身边召唤一个生命值为5点的地缚图腾，持续45 秒。该图腾可以使它周围半径0码内的所有敌人的移动速度降低。"}, {lv=6, id=332, n="治疗波", i="spell_nature_magicimmunity", auto=false, d="治疗友方目标，恢复64到78点生命值。"}, {lv=8, id=8044, n="地震术", i="spell_nature_earthshock", auto=false, d="立即以震撼性的力量攻击目标，对其造成32到34点自然伤害，同时打断施法，并使其在2 秒内无法施放该系法术。产生大量的威胁值。"}, {lv=8, id=8018, n="石化武器", i="spell_nature_rockbiter", auto=false, d="强化萨满祭司的武器，使其近战攻击强度提高58点，使用该武器对敌人造成近战伤害时产生额外的威胁值。强化效果持续60分钟。"}, {lv=8, id=5730, n="石爪图腾", i="spell_nature_stoneclawtotem", auto=false, d="在施法者身边召唤出一个生命值为50的石爪图腾。这个图腾可以吸引半径0码范围内的所有敌人来攻击它，持续15 秒。"}, {lv=8, id=324, n="闪电之盾", i="spell_nature_lightningshield", auto=false, d="施法者被若干个闪电球环绕。如果施法者受到了近战、远程或法术伤害，则攻击者会受到13点自然伤害，并会消耗掉一个闪电球。一个攻击者在短期内只会受到一次反噬伤害。持续10 分钟。"}, {lv=8, id=529, n="闪电箭", i="spell_nature_lightning", auto=false, d="向目标射出闪电箭，对其造成若干点伤害。"}, {lv=10, id=8075, n="大地之力图腾", i="spell_nature_earthbindtotem", auto=false, d="在施法者身边召唤出一个生命值为5的大地之力图腾。这个图腾可以使半径30码范围内所有小队成员的力量提高7，持续5 分钟。"}, {lv=10, id=8024, n="火舌武器", i="spell_fire_flametounge", auto=false, d="给萨满祭司的武器灌注火焰的力量。每次击中敌人都会造成3.23377到13.04点额外的火焰伤害，具体数值取决于武器的攻击速度，越慢的武器所附加的火焰伤害越高。如果施放在主手武器上，你将无法获得火舌图腾的增益效果。持续60分钟。"}, {lv=10, id=3599, n="灼热图腾", i="spell_fire_searingtotem", auto=false, d="在施法者身边召唤出一个生命值为5的灼热图腾，持续30 秒。它可以频繁攻击半径若干码范围内的某个敌人，每次对其造成9到11点火焰伤害。"}, {lv=10, id=8050, n="烈焰震击", i="spell_fire_flameshock", auto=false, d="立刻用火焰燃烧目标，对其造成20点火焰伤害，并在随后的12 秒内造成总计28点火焰伤害。"}, {lv=12, id=2008, n="先祖之魂", i="spell_nature_regenerate", auto=false, d="让已死的目标复活，并恢复65点生命值和若干点法力值。无法在战斗中施放。"}, {lv=12, id=370, n="净化术", i="spell_nature_purge", auto=false, d="净化敌方目标，移除1个魔法效果。"}, {lv=12, id=547, n="治疗波", i="spell_nature_magicimmunity", auto=false, d="治疗友方目标，恢复119到143点生命值。"}, {lv=12, id=408341, n="火焰新星", i="spell_fire_sealoffire", auto=false, d="立即对激活的火焰图腾周围0码内的敌人造成48到56点火焰伤害。"}, {lv=14, id=8045, n="地震术", i="spell_nature_earthshock", auto=false, d="立即以震撼性的力量攻击目标，对其造成47到51点自然伤害，同时打断施法，并使其在2 秒内无法施放该系法术。产生大量的威胁值。"}, {lv=14, id=8154, n="石肤图腾", i="spell_nature_stoneskintotem", auto=false, d="在施法者脚下召唤一个拥有5点生命值的石肤图腾。该图腾保护30码内的队伍成员，使其受到的物理伤害降低7点。持续5 分钟。"}, {lv=14, id=548, n="闪电箭", i="spell_nature_lightning", auto=false, d="向目标射出闪电箭，对其造成若干点伤害。"}, {lv=16, id=526, n="消毒术", i="spell_nature_nullifypoison", auto=false, d="治愈目标身上的1个中毒效果。"}, {lv=16, id=8019, n="石化武器", i="spell_nature_rockbiter", auto=false, d="强化萨满祭司的武器，使其近战攻击强度提高88点，使用该武器对敌人造成近战伤害时产生额外的威胁值。强化效果持续60分钟。"}, {lv=16, id=325, n="闪电之盾", i="spell_nature_lightningshield", auto=false, d="施法者被若干个闪电球环绕。如果施法者受到了近战、远程或法术伤害，则攻击者会受到24点自然伤害，并会消耗掉一个闪电球。一个攻击者在短期内只会受到一次反噬伤害。持续10 分钟。"}, {lv=18, id=8143, n="战栗图腾", i="spell_nature_tremortotem", auto=false, d="在施法者身边召唤一个生命值为5点的战栗图腾，它会震动附近的地面，驱散半径0码范围内所有队友身上的恐惧、魅惑和催眠效果。持续5 分钟。"}, {lv=18, id=913, n="治疗波", i="spell_nature_magicimmunity", auto=false, d="治疗友方目标，恢复235到277点生命值。"}, {lv=18, id=8027, n="火舌武器", i="spell_fire_flametounge", auto=false, d="给萨满祭司的武器灌注火焰的力量。每次击中敌人都会造成5.22078到19.16点额外的火焰伤害，具体数值取决于武器的攻击速度，越慢的武器所附加的火焰伤害越高。如果施放在主手武器上，你将无法获得火舌图腾的增益效果。持续60分钟。"}, {lv=18, id=8052, n="烈焰震击", i="spell_fire_flameshock", auto=false, d="立刻用火焰燃烧目标，对其造成33点火焰伤害，并在随后的12 秒内造成总计32点火焰伤害。"}, {lv=18, id=6390, n="石爪图腾", i="spell_nature_stoneclawtotem", auto=false, d="在施法者身边召唤出一个生命值为150的石爪图腾。这个图腾可以吸引半径0码范围内的所有敌人来攻击它，持续15 秒。"}, {lv=20, id=66842, n="元素的召唤", i="spell_shaman_dropall_01", auto=false, d="同时放置图腾栏中的最多4个指定图腾。"}, {lv=20, id=8033, n="冰封武器", i="spell_frost_frostbrand", auto=false, d="以冰霜的力量加强萨满祭司的武器，每次击中敌人都有一定几率造成32点额外的冰霜伤害，并使目标的移动速度降低25%，减速效果持续8 秒。冰封武器效果持续60分钟。"}, {lv=20, id=8056, n="冰霜震击", i="spell_frost_frostshock", auto=false, d="以冰霜冲击目标，对其造成64到68点伤害，并使其移动速度降低50%，持续8 秒。"}, {lv=20, id=2645, n="幽魂之狼", i="spell_nature_spiritwolf", auto=false, d="将萨满祭司变成一头幽魂之狼，移动速度提高40%。只能在户外使用。"}, {lv=20, id=36936, n="收回图腾", i="spell_shaman_totemrecall", auto=false, d="将你的图腾送回大地中，每个因收回而被摧毁的图腾都可以为你返还召唤该图腾所需法力值的25%。"}, {lv=20, id=8004, n="次级治疗波", i="spell_nature_healingwavelesser", auto=false, d="治疗友方目标，恢复142到164点生命值。"}, {lv=20, id=5394, n="治疗之泉图腾", i="inv_spear_04", auto=false, d="在施法者身边召唤出一个生命值为5点的治疗之泉图腾，每2秒对半径30码范围内的所有小队成员恢复5点生命值，持续5 分钟。"}, {lv=20, id=6363, n="灼热图腾", i="spell_fire_searingtotem", auto=false, d="在施法者身边召唤出一个生命值为5的灼热图腾，持续35 秒。它可以频繁攻击半径若干码范围内的某个敌人，每次对其造成13到17点火焰伤害。"}, {lv=20, id=915, n="闪电箭", i="spell_nature_lightning", auto=false, d="向目标射出闪电箭，对其造成若干点伤害。"}, {lv=22, id=437009, n="图腾投射", i="ability_shaman_totemrelocation", auto=false, d="将你激活的图腾转移到指定位置。"}, {lv=22, id=131, n="水下呼吸", i="spell_shadow_demonbreath", auto=false, d="使目标可以在水下自由呼吸，持续10 分钟。"}, {lv=22, id=8166, n="清毒图腾", i="spell_nature_poisoncleansingtotem", auto=false, d="在施法者身边召唤一个生命值为5点的清毒图腾，每5秒为半径0码范围内的所有队友驱散1个中毒效果。持续5 分钟。"}, {lv=22, id=408342, n="火焰新星", i="spell_fire_sealoffire", auto=false, d="立即对激活的火焰图腾周围0码内的敌人造成102到116点火焰伤害。"}, {lv=22, id=2870, n="祛病术", i="spell_nature_removedisease", auto=false, d="治愈目标身上的1个疾病效果。"}, {lv=24, id=20609, n="先祖之魂", i="spell_nature_regenerate", auto=false, d="让已死的目标复活，并恢复150点生命值和若干点法力值。无法在战斗中施放。"}, {lv=24, id=8046, n="地震术", i="spell_nature_earthshock", auto=false, d="立即以震撼性的力量攻击目标，对其造成78到84点自然伤害，同时打断施法，并使其在2 秒内无法施放该系法术。产生大量的威胁值。"}, {lv=24, id=8160, n="大地之力图腾", i="spell_nature_earthbindtotem", auto=false, d="在施法者身边召唤出一个生命值为5的大地之力图腾。这个图腾可以使半径30码范围内所有小队成员的力量提高14，持续5 分钟。"}, {lv=24, id=8181, n="抗寒图腾", i="spell_frostresistancetotem_01", auto=false, d="在施法者身边召唤一个生命值为5点的抗寒图腾，持续5 分钟。图腾周围半径30码范围内的所有小队和团队成员的冰霜抗性提高30点。"}, {lv=24, id=939, n="治疗波", i="spell_nature_magicimmunity", auto=false, d="治疗友方目标，恢复315到369点生命值。"}, {lv=24, id=10399, n="石化武器", i="spell_nature_rockbiter", auto=false, d="强化萨满祭司的武器，使其近战攻击强度提高129点，使用该武器对敌人造成近战伤害时产生额外的威胁值。强化效果持续60分钟。"}, {lv=24, id=8155, n="石肤图腾", i="spell_nature_stoneskintotem", auto=false, d="在施法者脚下召唤一个拥有5点生命值的石肤图腾。该图腾保护30码内的队伍成员，使其受到的物理伤害降低11点。持续5 分钟。"}, {lv=24, id=905, n="闪电之盾", i="spell_nature_lightningshield", auto=false, d="施法者被若干个闪电球环绕。如果施法者受到了近战、远程或法术伤害，则攻击者会受到40点自然伤害，并会消耗掉一个闪电球。一个攻击者在短期内只会受到一次反噬伤害。持续10 分钟。"}, {lv=26, id=5675, n="法力之泉图腾", i="spell_nature_manaregentotem", auto=false, d="在施法者身边召唤一个生命值为5点的法力之泉图腾，持续5 分钟。它可以为半径30码范围内的小队成员每2秒回复4点法力值。"}, {lv=26, id=8030, n="火舌武器", i="spell_fire_flametounge", auto=false, d="给萨满祭司的武器灌注火焰的力量。每次击中敌人都会造成8.2987到28.64点额外的火焰伤害，具体数值取决于武器的攻击速度，越慢的武器所附加的火焰伤害越高。如果施放在主手武器上，你将无法获得火舌图腾的增益效果。持续60分钟。"}, {lv=26, id=8190, n="熔岩图腾", i="spell_fire_selfdestruct", auto=false, d="在施法者身边召唤一根生命值为5点的熔岩图腾，每2秒对它身边半径0范围内的所有敌人造成20点火焰伤害。持续20 秒。"}, {lv=26, id=6196, n="视界术", i="spell_nature_farsight", auto=false, d="将施法者的视点切换到目标区域，持续1 分钟。只能在户外使用。"}, {lv=26, id=943, n="闪电箭", i="spell_nature_lightning", auto=false, d="向目标射出闪电箭，对其造成若干点伤害。"}, {lv=28, id=8038, n="冰封武器", i="spell_frost_frostbrand", auto=false, d="以冰霜的力量加强萨满祭司的武器，每次击中敌人都有一定几率造成48点额外的冰霜伤害，并使目标的移动速度降低25%，减速效果持续8 秒。冰封武器效果持续60分钟。"}, {lv=28, id=8184, n="抗火图腾", i="spell_fireresistancetotem_01", auto=false, d="在施法者身边召唤一个生命值为5点的抗火图腾，持续5 分钟。图腾周围半径30码范围内的所有小队和团队成员的火焰抗性提高30点。"}, {lv=28, id=8008, n="次级治疗波", i="spell_nature_healingwavelesser", auto=false, d="治疗友方目标，恢复210到238点生命值。"}, {lv=28, id=546, n="水上行走", i="spell_frost_windwalkon", auto=false, d="使友方目标可以在水面上行走，持续10 分钟。任何伤害都会取消水上行走效果。"}, {lv=28, id=8227, n="火舌图腾", i="spell_nature_guardianward", auto=false, d="在施法者脚下召唤一个拥有5点生命值的火舌图腾。该图腾会为30码内所有队伍成员的主手武器附加火焰。每次命中会根据武器速度额外造成6.11688至21.92点火焰伤害。武器速度越慢，每次攻击造成的火焰伤害越高。持续5 分钟。"}, {lv=28, id=8053, n="烈焰震击", i="spell_fire_flameshock", auto=false, d="立刻用火焰燃烧目标，对其造成43点火焰伤害，并在随后的12 秒内造成总计56点火焰伤害。"}, {lv=28, id=6391, n="石爪图腾", i="spell_nature_stoneclawtotem", auto=false, d="在施法者身边召唤出一个生命值为220的石爪图腾。这个图腾可以吸引半径0码范围内的所有敌人来攻击它，持续15 秒。"}, {lv=30, id=66843, n="先祖的召唤", i="spell_shaman_dropall_02", auto=false, d="同时放置图腾栏中的最多4个指定图腾。可以放置与元素的召唤不同的图腾。"}, {lv=30, id=556, n="星界传送", i="spell_nature_astralrecal", auto=false, d="令施法者穿越扭曲虚空，回到若干。与不同地区的旅店老板谈话可以改变你的家所在的位置。"}, {lv=30, id=8177, n="根基图腾", i="spell_nature_groundingtotem", auto=false, d="在施法者身边召唤一个生命值为5点的根基图腾，每10秒为附近的每个队友吸收一个有害法术，但不会吸收区域效果法术。持续45 秒。"}, {lv=30, id=6375, n="治疗之泉图腾", i="inv_spear_04", auto=false, d="在施法者身边召唤出一个生命值为5点的治疗之泉图腾，每2秒对半径30码范围内的所有小队成员恢复6点生命值，持续5 分钟。"}, {lv=30, id=6364, n="灼热图腾", i="spell_fire_searingtotem", auto=false, d="在施法者身边召唤出一个生命值为5的灼热图腾，持续40 秒。它可以频繁攻击半径若干码范围内的某个敌人，每次对其造成19到25点火焰伤害。"}, {lv=30, id=10595, n="自然抗性图腾", i="spell_nature_natureresistancetotem", auto=false, d="在施法者身边召唤一个生命值为5点的自然抗性图腾，持续5 分钟。图腾周围半径30码范围内的所有小队和团队成员的自然抗性提高30点。"}, {lv=30, id=0, n="迅捷之风", i="", auto=false, d="", quest=true}, {lv=30, id=8232, n="风怒武器", i="spell_nature_cyclone", auto=false, d="以风的力量强化萨满祭司的武器。每次击中敌人都有20%的几率使你获得额外的2次攻击，且这些攻击的近战攻击强度提高46点。应用于主手时，会使你无法从风怒图腾获得个人收益。持续60分钟。"}, {lv=32, id=8012, n="净化术", i="spell_nature_purge", auto=false, d="净化敌方目标，移除2个增益魔法效果。"}, {lv=32, id=959, n="治疗波", i="spell_nature_magicimmunity", auto=false, d="治疗友方目标，恢复448到520点生命值。"}, {lv=32, id=408343, n="火焰新星", i="spell_fire_sealoffire", auto=false, d="立即对激活的火焰图腾周围0码内的敌人造成184到208点火焰伤害。"}, {lv=32, id=945, n="闪电之盾", i="spell_nature_lightningshield", auto=false, d="施法者被若干个闪电球环绕。如果施法者受到了近战、远程或法术伤害，则攻击者会受到64点自然伤害，并会消耗掉一个闪电球。一个攻击者在短期内只会受到一次反噬伤害。持续10 分钟。"}, {lv=32, id=6041, n="闪电箭", i="spell_nature_lightning", auto=false, d="向目标射出闪电箭，对其造成若干点伤害。"}, {lv=32, id=421, n="闪电链", i="spell_nature_chainlightning", auto=false, d="向敌人射出一支闪电箭，对其造成82到94点自然伤害，随后这支闪电箭会继续攻击它周围最近的敌人。闪电箭每跳跃一次，伤害就减少，最多可攻击3个目标。"}, {lv=32, id=8512, n="风怒图腾", i="spell_nature_windfury", auto=false, d="在施法者脚下召唤一个拥有5点生命值的风怒图腾。该图腾会强化若干码内所有队伍成员的近战攻击。每次主手命中都有20%的几率使攻击者额外攻击1次，且这些攻击获得95点额外近战攻击强度。持续5 分钟。"}, {lv=34, id=8058, n="冰霜震击", i="spell_frost_frostshock", auto=false, d="以冰霜冲击目标，对其造成120到128点伤害，并使其移动速度降低50%，持续8 秒。"}, {lv=34, id=6495, n="岗哨图腾", i="spell_nature_removecurse", auto=false, d="在你的脚下召唤一个拥有100点生命值、无法移动的岗哨图腾，持续5 分钟。该图腾可提供附近区域的视野，并在有敌人攻击它时发出警报。右键点击增益效果，可在图腾视角和萨满祭司视角之间切换。"}, {lv=34, id=16314, n="石化武器", i="spell_nature_rockbiter", auto=false, d="强化萨满祭司的武器，使其近战攻击强度提高211点，使用该武器对敌人造成近战伤害时产生额外的威胁值。强化效果持续60分钟。"}, {lv=34, id=10406, n="石肤图腾", i="spell_nature_stoneskintotem", auto=false, d="在施法者脚下召唤一个拥有5点生命值的石肤图腾。该图腾保护30码内的队伍成员，使其受到的物理伤害降低16点。持续5 分钟。"}, {lv=36, id=20610, n="先祖之魂", i="spell_nature_regenerate", auto=false, d="让已死的目标复活，并恢复250点生命值和若干点法力值。无法在战斗中施放。"}, {lv=36, id=10412, n="地震术", i="spell_nature_earthshock", auto=false, d="立即以震撼性的力量攻击目标，对其造成128到136点自然伤害，同时打断施法，并使其在2 秒内无法施放该系法术。产生大量的威胁值。"}, {lv=36, id=8010, n="次级治疗波", i="spell_nature_healingwavelesser", auto=false, d="治疗友方目标，恢复285到323点生命值。"}, {lv=36, id=10495, n="法力之泉图腾", i="spell_nature_manaregentotem", auto=false, d="在施法者身边召唤一个生命值为5点的法力之泉图腾，持续5 分钟。它可以为半径30码范围内的小队成员每2秒回复6点法力值。"}, {lv=36, id=16339, n="火舌武器", i="spell_fire_flametounge", auto=false, d="给萨满祭司的武器灌注火焰的力量。每次击中敌人都会造成13.8571到45.76点额外的火焰伤害，具体数值取决于武器的攻击速度，越慢的武器所附加的火焰伤害越高。如果施放在主手武器上，你将无法获得火舌图腾的增益效果。持续60分钟。"}, {lv=36, id=10585, n="熔岩图腾", i="spell_fire_selfdestruct", auto=false, d="在施法者身边召唤一根生命值为5点的熔岩图腾，每2秒对它身边半径0范围内的所有敌人造成35点火焰伤害。持续20 秒。"}, {lv=36, id=15107, n="风墙图腾", i="spell_nature_earthbind", auto=false, d="在施法者身边召唤出一个生命值为5点的风墙图腾，使半径30码范围内的小队成员在被攻击时所受的远程伤害减少32点。持续5 分钟。"}, {lv=38, id=10456, n="冰封武器", i="spell_frost_frostbrand", auto=false, d="以冰霜的力量加强萨满祭司的武器，每次击中敌人都有一定几率造成77点额外的冰霜伤害，并使目标的移动速度降低25%，减速效果持续8 秒。冰封武器效果持续60分钟。"}, {lv=38, id=8161, n="大地之力图腾", i="spell_nature_earthbindtotem", auto=false, d="在施法者身边召唤出一个生命值为5的大地之力图腾。这个图腾可以使半径30码范围内所有小队成员的力量提高25，持续5 分钟。"}, {lv=38, id=10478, n="抗寒图腾", i="spell_frostresistancetotem_01", auto=false, d="在施法者身边召唤一个生命值为5点的抗寒图腾，持续5 分钟。图腾周围半径30码范围内的所有小队和团队成员的冰霜抗性提高45点。"}, {lv=38, id=8249, n="火舌图腾", i="spell_nature_guardianward", auto=false, d="在施法者脚下召唤一个拥有5点生命值的火舌图腾。该图腾会强化30码内所有队伍成员的近战攻击。每次主手命中会根据武器速度额外造成9.14286至31.24点火焰伤害。武器速度越慢，每次攻击造成的火焰伤害越高。持续5 分钟。"}, {lv=38, id=6392, n="石爪图腾", i="spell_nature_stoneclawtotem", auto=false, d="在施法者身边召唤出一个生命值为280的石爪图腾。这个图腾可以吸引半径0码范围内的所有敌人来攻击它，持续15 秒。"}, {lv=38, id=8170, n="祛病图腾", i="spell_nature_diseasecleansingtotem", auto=false, d="在施法者身边召唤一个生命值为5点的祛病图腾，每5秒为半径0码范围内的队友驱散1个疾病效果。持续2 分钟。"}, {lv=38, id=10391, n="闪电箭", i="spell_nature_lightning", auto=false, d="向目标射出闪电箭，对其造成若干点伤害。"}, {lv=40, id=6377, n="治疗之泉图腾", i="inv_spear_04", auto=false, d="在施法者身边召唤出一个生命值为5点的治疗之泉图腾，每2秒对半径30码范围内的所有小队成员恢复7点生命值，持续5 分钟。"}, {lv=40, id=8005, n="治疗波", i="spell_nature_magicimmunity", auto=false, d="治疗友方目标，恢复636到734点生命值。"}, {lv=40, id=1064, n="治疗链", i="spell_nature_healingwavegreater", auto=false, d="为友方目标回复233到269点生命值，然后转而治疗附近的目标。如果对小队成员施法，则治疗链只会继续治疗其队友。治疗链每次跳跃后的治疗效果是上一个目标的。总共可治疗3个目标。"}, {lv=40, id=408521, n="激流", i="spell_nature_riptide", auto=false, d="治疗一个友方目标，为其恢复456到504点生命值，并在15 秒内额外恢复445点，同时使你对该目标直接施放的治疗链效果提高25%。", tal=true}, {lv=40, id=66844, n="灵魂的召唤", i="spell_shaman_dropall_03", auto=false, d="同时放置图腾栏中的最多4个指定图腾。可以放置与元素的召唤或先祖的召唤不同的图腾。"}, {lv=40, id=6365, n="灼热图腾", i="spell_fire_searingtotem", auto=false, d="在施法者身边召唤出一个生命值为5的灼热图腾，持续45 秒。它可以频繁攻击半径若干码范围内的某个敌人，每次对其造成26到34点火焰伤害。"}, {lv=40, id=10447, n="烈焰震击", i="spell_fire_flameshock", auto=false, d="立刻用火焰燃烧目标，对其造成82点火焰伤害，并在随后的12 秒内造成总计84点火焰伤害。"}, {lv=40, id=408490, n="熔岩爆裂", i="spell_shaman_lavaburst", auto=false, d="向目标掷出熔岩，造成99到127点火焰伤害。如果目标受到你的烈焰震击影响，熔岩爆裂造成的伤害提高20%。", tal=true}, {lv=40, id=8134, n="闪电之盾", i="spell_nature_lightningshield", auto=false, d="施法者被若干个闪电球环绕。如果施法者受到了近战、远程或法术伤害，则攻击者会受到96点自然伤害，并会消耗掉一个闪电球。一个攻击者在短期内只会受到一次反噬伤害。持续10 分钟。"}, {lv=40, id=930, n="闪电链", i="spell_nature_chainlightning", auto=false, d="向敌人射出一支闪电箭，对其造成94到106点自然伤害，随后这支闪电箭会继续攻击它周围最近的敌人。闪电箭每跳跃一次，伤害就减少，最多可攻击3个目标。"}, {lv=40, id=8235, n="风怒武器", i="spell_nature_cyclone", auto=false, d="以风的力量强化萨满祭司的武器。每次击中敌人都有20%的几率使你获得额外的2次攻击，且这些攻击的近战攻击强度提高119点。应用于主手时，会使你无法从风怒图腾获得个人收益。持续60分钟。"}, {lv=42, id=10537, n="抗火图腾", i="spell_fireresistancetotem_01", auto=false, d="在施法者身边召唤一个生命值为5点的抗火图腾，持续5 分钟。图腾周围半径30码范围内的所有小队和团队成员的火焰抗性提高45点。"}, {lv=42, id=408344, n="火焰新星", i="spell_fire_sealoffire", auto=false, d="立即对激活的火焰图腾周围0码内的敌人造成281到317点火焰伤害。"}, {lv=42, id=8835, n="风之优雅图腾", i="spell_nature_invisibilitytotem", auto=false, d="在施法者身边召唤一个生命值为5的风之优雅图腾。这个图腾可以使半径30码范围内的小队成员的敏捷提高49点，持续5 分钟。"}, {lv=42, id=10613, n="风怒图腾", i="spell_nature_windfury", auto=false, d="在施法者脚下召唤一个拥有5点生命值的风怒图腾。该图腾会强化若干码内所有队伍成员的近战攻击。每次主手命中都有20%的几率使攻击者额外攻击1次，且这些攻击获得179点额外近战攻击强度。持续5 分钟。"}, {lv=44, id=10466, n="次级治疗波", i="spell_nature_healingwavelesser", auto=false, d="治疗友方目标，恢复401到451点生命值。"}, {lv=44, id=16315, n="石化武器", i="spell_nature_rockbiter", auto=false, d="强化萨满祭司的武器，使其近战攻击强度提高393点，使用该武器对敌人造成近战伤害时产生额外的威胁值。强化效果持续60分钟。"}, {lv=44, id=10407, n="石肤图腾", i="spell_nature_stoneskintotem", auto=false, d="在施法者脚下召唤一个拥有5点生命值的石肤图腾。该图腾保护30码内的队伍成员，使其受到的物理伤害降低22点。持续5 分钟。"}, {lv=44, id=10600, n="自然抗性图腾", i="spell_nature_natureresistancetotem", auto=false, d="在施法者身边召唤一个生命值为5点的自然抗性图腾，持续5 分钟。图腾周围半径30码范围内的所有小队和团队成员的自然抗性提高45点。"}, {lv=44, id=10392, n="闪电箭", i="spell_nature_lightning", auto=false, d="向目标射出闪电箭，对其造成若干点伤害。"}, {lv=46, id=10472, n="冰霜震击", i="spell_frost_frostshock", auto=false, d="以冰霜冲击目标，对其造成183到193点伤害，并使其移动速度降低50%，持续8 秒。"}, {lv=46, id=10622, n="治疗链", i="spell_nature_healingwavegreater", auto=false, d="为友方目标回复312到358点生命值，然后转而治疗附近的目标。如果对小队成员施法，则治疗链只会继续治疗其队友。治疗链每次跳跃后的治疗效果是上一个目标的。总共可治疗3个目标。"}, {lv=46, id=10496, n="法力之泉图腾", i="spell_nature_manaregentotem", auto=false, d="在施法者身边召唤一个生命值为5点的法力之泉图腾，持续5 分钟。它可以为半径30码范围内的小队成员每2秒回复8点法力值。"}, {lv=46, id=16341, n="火舌武器", i="spell_fire_flametounge", auto=false, d="给萨满祭司的武器灌注火焰的力量。每次击中敌人都会造成23.3636到75.04点额外的火焰伤害，具体数值取决于武器的攻击速度，越慢的武器所附加的火焰伤害越高。如果施放在主手武器上，你将无法获得火舌图腾的增益效果。持续60分钟。"}, {lv=46, id=10586, n="熔岩图腾", i="spell_fire_selfdestruct", auto=false, d="在施法者身边召唤一根生命值为5点的熔岩图腾，每2秒对它身边半径0范围内的所有敌人造成52点火焰伤害。持续20 秒。"}, {lv=46, id=15111, n="风墙图腾", i="spell_nature_earthbind", auto=false, d="在施法者身边召唤出一个生命值为5点的风墙图腾，使半径30码范围内的小队成员在被攻击时所受的远程伤害减少50点。持续5 分钟。"}, {lv=48, id=20776, n="先祖之魂", i="spell_nature_regenerate", auto=false, d="让已死的目标复活，并恢复400点生命值和若干点法力值。无法在战斗中施放。"}, {lv=48, id=16355, n="冰封武器", i="spell_frost_frostbrand", auto=false, d="以冰霜的力量加强萨满祭司的武器，每次击中敌人都有一定几率造成127点额外的冰霜伤害，并使目标的移动速度降低25%，减速效果持续8 秒。冰封武器效果持续60分钟。"}, {lv=48, id=10413, n="地震术", i="spell_nature_earthshock", auto=false, d="立即以震撼性的力量攻击目标，对其造成199到211点自然伤害，同时打断施法，并使其在2 秒内无法施放该系法术。产生大量的威胁值。"}, {lv=48, id=10395, n="治疗波", i="spell_nature_magicimmunity", auto=false, d="治疗友方目标，恢复905到1039点生命值。"}, {lv=48, id=17354, n="法力之潮图腾", i="spell_frost_summonwaterelemental", auto=false, d="在施法者身边召唤一个生命值为5点的法力之潮图腾，持续12秒。它可以为半径30码范围内的小队成员每3秒回复197点法力值。", tal=true}, {lv=48, id=10526, n="火舌图腾", i="spell_nature_guardianward", auto=false, d="在施法者脚下召唤一个拥有5点生命值的火舌图腾。该图腾会强化30码内所有队伍成员的近战攻击。每次主手命中会根据武器速度额外造成12.7792至42.44点火焰伤害。武器速度越慢，每次攻击造成的火焰伤害越高。持续5 分钟。"}, {lv=48, id=10427, n="石爪图腾", i="spell_nature_stoneclawtotem", auto=false, d="在施法者身边召唤出一个生命值为390的石爪图腾。这个图腾可以吸引半径0码范围内的所有敌人来攻击它，持续15 秒。"}, {lv=48, id=10431, n="闪电之盾", i="spell_nature_lightningshield", auto=false, d="施法者被若干个闪电球环绕。如果施法者受到了近战、远程或法术伤害，则攻击者会受到134点自然伤害，并会消耗掉一个闪电球。一个攻击者在短期内只会受到一次反噬伤害。持续10 分钟。"}, {lv=48, id=2860, n="闪电链", i="spell_nature_chainlightning", auto=false, d="向敌人射出一支闪电箭，对其造成106到118点自然伤害，随后这支闪电箭会继续攻击它周围最近的敌人。闪电箭每跳跃一次，伤害就减少，最多可攻击3个目标。"}, {lv=50, id=10462, n="治疗之泉图腾", i="inv_spear_04", auto=false, d="在施法者身边召唤出一个生命值为5点的治疗之泉图腾，每2秒对半径30码范围内的所有小队成员恢复9点生命值，持续5 分钟。"}, {lv=50, id=1239242, n="激流", i="spell_nature_riptide", auto=false, d="治疗一个友方目标，为其恢复581到643点生命值，并在15 秒内额外恢复575点，同时使你对该目标直接施放的治疗链效果提高25%。", tal=true}, {lv=50, id=10437, n="灼热图腾", i="spell_fire_searingtotem", auto=false, d="在施法者身边召唤出一个生命值为5的灼热图腾，持续50 秒。它可以频繁攻击半径若干码范围内的某个敌人，每次对其造成33到45点火焰伤害。"}, {lv=50, id=1238299, n="熔岩爆裂", i="spell_shaman_lavaburst", auto=false, d="向目标掷出熔岩，造成156到202点火焰伤害。如果目标受到你的烈焰震击影响，熔岩爆裂造成的伤害提高20%。", tal=true}, {lv=50, id=15207, n="闪电箭", i="spell_nature_lightning", auto=false, d="向目标射出闪电箭，对其造成若干点伤害。"}, {lv=50, id=10486, n="风怒武器", i="spell_nature_cyclone", auto=false, d="以风的力量强化萨满祭司的武器。每次击中敌人都有20%的几率使你获得额外的2次攻击，且这些攻击的近战攻击强度提高249点。应用于主手时，会使你无法从风怒图腾获得个人收益。持续60分钟。"}, {lv=52, id=10442, n="大地之力图腾", i="spell_nature_earthbindtotem", auto=false, d="在施法者身边召唤出一个生命值为5的大地之力图腾。这个图腾可以使半径30码范围内所有小队成员的力量提高42，持续5 分钟。"}, {lv=52, id=10467, n="次级治疗波", i="spell_nature_healingwavelesser", auto=false, d="治疗友方目标，恢复574到642点生命值。"}, {lv=52, id=408345, n="火焰新星", i="spell_fire_sealoffire", auto=false, d="立即对激活的火焰图腾周围0码内的敌人造成396到442点火焰伤害。"}, {lv=52, id=10448, n="烈焰震击", i="spell_fire_flameshock", auto=false, d="立刻用火焰燃烧目标，对其造成128点火焰伤害，并在随后的12 秒内造成总计136点火焰伤害。"}, {lv=52, id=10614, n="风怒图腾", i="spell_nature_windfury", auto=false, d="在施法者脚下召唤一个拥有5点生命值的风怒图腾。该图腾会强化若干码内所有队伍成员的近战攻击。每次主手命中都有20%的几率使攻击者额外攻击1次，且这些攻击获得246点额外近战攻击强度。持续5 分钟。"}, {lv=54, id=10479, n="抗寒图腾", i="spell_frostresistancetotem_01", auto=false, d="在施法者身边召唤一个生命值为5点的抗寒图腾，持续5 分钟。图腾周围半径30码范围内的所有小队和团队成员的冰霜抗性提高60点。"}, {lv=54, id=10623, n="治疗链", i="spell_nature_healingwavegreater", auto=false, d="为友方目标回复458到522点生命值，然后转而治疗附近的目标。如果对小队成员施法，则治疗链只会继续治疗其队友。治疗链每次跳跃后的治疗效果是上一个目标的。总共可治疗3个目标。"}, {lv=54, id=16316, n="石化武器", i="spell_nature_rockbiter", auto=false, d="强化萨满祭司的武器，使其近战攻击强度提高554点，使用该武器对敌人造成近战伤害时产生额外的威胁值。强化效果持续60分钟。"}, {lv=54, id=10408, n="石肤图腾", i="spell_nature_stoneskintotem", auto=false, d="在施法者脚下召唤一个拥有5点生命值的石肤图腾。该图腾保护30码内的队伍成员，使其受到的物理伤害降低30点。持续5 分钟。"}, {lv=56, id=10396, n="治疗波", i="spell_nature_magicimmunity", auto=false, d="治疗友方目标，恢复1255到1433点生命值。"}, {lv=56, id=10497, n="法力之泉图腾", i="spell_nature_manaregentotem", auto=false, d="在施法者身边召唤一个生命值为5点的法力之泉图腾，持续5 分钟。它可以为半径30码范围内的小队成员每2秒回复10点法力值。"}, {lv=56, id=16342, n="火舌武器", i="spell_fire_flametounge", auto=false, d="给萨满祭司的武器灌注火焰的力量。每次击中敌人都会造成31.4416到99.92点额外的火焰伤害，具体数值取决于武器的攻击速度，越慢的武器所附加的火焰伤害越高。如果施放在主手武器上，你将无法获得火舌图腾的增益效果。持续60分钟。"}, {lv=56, id=10587, n="熔岩图腾", i="spell_fire_selfdestruct", auto=false, d="在施法者身边召唤一根生命值为5点的熔岩图腾，每2秒对它身边半径0范围内的所有敌人造成73点火焰伤害。持续20 秒。"}, {lv=56, id=10432, n="闪电之盾", i="spell_nature_lightningshield", auto=false, d="施法者被若干个闪电球环绕。如果施法者受到了近战、远程或法术伤害，则攻击者会受到178点自然伤害，并会消耗掉一个闪电球。一个攻击者在短期内只会受到一次反噬伤害。持续10 分钟。"}, {lv=56, id=15208, n="闪电箭", i="spell_nature_lightning", auto=false, d="向目标射出闪电箭，对其造成若干点伤害。"}, {lv=56, id=10605, n="闪电链", i="spell_nature_chainlightning", auto=false, d="向敌人射出一支闪电箭，对其造成116到130点自然伤害，随后这支闪电箭会继续攻击它周围最近的敌人。闪电箭每跳跃一次，伤害就减少，最多可攻击3个目标。"}, {lv=56, id=10627, n="风之优雅图腾", i="spell_nature_invisibilitytotem", auto=false, d="在施法者身边召唤一个生命值为5的风之优雅图腾。这个图腾可以使半径30码范围内的小队成员的敏捷提高77点，持续5 分钟。"}, {lv=56, id=15112, n="风墙图腾", i="spell_nature_earthbind", auto=false, d="在施法者身边召唤出一个生命值为5点的风墙图腾，使半径30码范围内的小队成员在被攻击时所受的远程伤害减少64点。持续5 分钟。"}, {lv=58, id=16356, n="冰封武器", i="spell_frost_frostbrand", auto=false, d="以冰霜的力量加强萨满祭司的武器，每次击中敌人都有一定几率造成158点额外的冰霜伤害，并使目标的移动速度降低25%，减速效果持续8 秒。冰封武器效果持续60分钟。"}, {lv=58, id=10473, n="冰霜震击", i="spell_frost_frostshock", auto=false, d="以冰霜冲击目标，对其造成275到291点伤害，并使其移动速度降低50%，持续8 秒。"}, {lv=58, id=10538, n="抗火图腾", i="spell_fireresistancetotem_01", auto=false, d="在施法者身边召唤一个生命值为5点的抗火图腾，持续5 分钟。图腾周围半径30码范围内的所有小队和团队成员的火焰抗性提高60点。"}, {lv=58, id=17359, n="法力之潮图腾", i="spell_frost_summonwaterelemental", auto=false, d="在施法者身边召唤一个生命值为5点的法力之潮图腾，持续12秒。它可以为半径30码范围内的小队成员每3秒回复290点法力值。", tal=true}, {lv=58, id=16387, n="火舌图腾", i="spell_nature_guardianward", auto=false, d="在施法者脚下召唤一个拥有5点生命值的火舌图腾。该图腾会强化30码内所有队伍成员的近战攻击。每次主手命中会根据武器速度额外造成16.7013至54.52点火焰伤害。武器速度越慢，每次攻击造成的火焰伤害越高。持续5 分钟。"}, {lv=58, id=10428, n="石爪图腾", i="spell_nature_stoneclawtotem", auto=false, d="在施法者身边召唤出一个生命值为480的石爪图腾。这个图腾可以吸引半径0码范围内的所有敌人来攻击它，持续15 秒。"}, {lv=60, id=20777, n="先祖之魂", i="spell_nature_regenerate", auto=false, d="让已死的目标复活，并恢复600点生命值和若干点法力值。无法在战斗中施放。"}, {lv=60, id=10414, n="地震术", i="spell_nature_earthshock", auto=false, d="立即以震撼性的力量攻击目标，对其造成293到309点自然伤害，同时打断施法，并使其在2 秒内无法施放该系法术。产生大量的威胁值。"}, {lv=60, id=25361, n="大地之力图腾", i="spell_nature_earthbindtotem", auto=false, d="在施法者身边召唤出一个生命值为5的大地之力图腾。这个图腾可以使半径30码范围内所有小队成员的力量提高53，持续5 分钟。"}, {lv=60, id=10468, n="次级治疗波", i="spell_nature_healingwavelesser", auto=false, d="治疗友方目标，恢复775到865点生命值。"}, {lv=60, id=10463, n="治疗之泉图腾", i="inv_spear_04", auto=false, d="在施法者身边召唤出一个生命值为5点的治疗之泉图腾，每2秒对半径30码范围内的所有小队成员恢复11点生命值，持续5 分钟。"}, {lv=60, id=25357, n="治疗波", i="spell_nature_magicimmunity", auto=false, d="为友方目标回复1508到1722点生命值。"}, {lv=60, id=1239243, n="激流", i="spell_nature_riptide", auto=false, d="治疗一个友方目标，为其恢复799到883点生命值，并在15 秒内额外恢复805点，同时使你对该目标直接施放的治疗链效果提高25%。", tal=true}, {lv=60, id=10438, n="灼热图腾", i="spell_fire_searingtotem", auto=false, d="在施法者身边召唤出一个生命值为5的灼热图腾，持续55 秒。它可以频繁攻击半径若干码范围内的某个敌人，每次对其造成40到54点火焰伤害。"}, {lv=60, id=29228, n="烈焰震击", i="spell_fire_flameshock", auto=false, d="立刻用火焰燃烧目标，对其造成166点火焰伤害，并在随后的12 秒内造成总计176点火焰伤害。"}, {lv=60, id=1238300, n="熔岩爆裂", i="spell_shaman_lavaburst", auto=false, d="向目标掷出熔岩，造成192到248点火焰伤害。如果目标受到你的烈焰震击影响，熔岩爆裂造成的伤害提高20%。", tal=true}, {lv=60, id=10601, n="自然抗性图腾", i="spell_nature_natureresistancetotem", auto=false, d="在施法者身边召唤一个生命值为5点的自然抗性图腾，持续5 分钟。图腾周围半径30码范围内的所有小队和团队成员的自然抗性提高60点。"}, {lv=60, id=25359, n="风之优雅图腾", i="spell_nature_invisibilitytotem", auto=false, d="在施法者身边召唤一个生命值为5的风之优雅图腾。这个图腾可以使半径30码范围内的小队成员的敏捷提高89点，持续5 分钟。"}, {lv=60, id=16362, n="风怒武器", i="spell_nature_cyclone", auto=false, d="以风的力量强化萨满祭司的武器。每次击中敌人都有20%的几率使你获得额外的2次攻击，且这些攻击的近战攻击强度提高333点。应用于主手时，会使你无法从风怒图腾获得个人收益。持续60分钟。"}},
    Mage = {{lv=1, id=29077, n="元素大师", i="spell_fire_masterofelements", auto=false, d="回复1点法力值。", tal=true}, {lv=1, id=12484, n="冰冻", i="spell_frost_icestorm", auto=false, d="令目标被冻僵，持续1.5 秒。"}, {lv=1, id=1459, n="奥术智慧", i="spell_holy_magicalsentry", auto=false, d="使目标的智力提高2点，持续1 小时。"}, {lv=1, id=133, n="火球术", i="spell_fire_flamebolt", auto=true, d="发射一枚火球攻击目标，对其造成14到22点火焰伤害，并在4 秒内造成额外的2点伤害。"}, {lv=1, id=168, n="霜甲术", i="spell_frost_frostarmor02", auto=true, d="使护甲值提高30点。如果敌人使用近战武器攻击施法者，他们的移动速度就有可能被降低30%，攻击间隔延长25%，冰冻效果持续5 秒。法师在同一时间内只能保有一种魔法护甲效果。持续30 分钟。"}, {lv=4, id=116, n="寒冰箭", i="spell_frost_frostbolt02", auto=false, d="向目标射出一支寒冰箭，对其造成18至20点冰霜伤害并使其移动速度降低40%，持续5 秒。"}, {lv=4, id=5504, n="造水术", i="inv_drink_06", auto=false, d="用魔法合成2瓶魔法水以供法师和的盟友饮用。\n\n这些物品会在持有者登出游戏超过15分钟之后消失。"}, {lv=6, id=2136, n="火焰冲击", i="spell_fire_fireball", auto=false, d="施放火焰冲击敌人，对其造成24到32点火焰伤害。"}, {lv=6, id=143, n="火球术", i="spell_fire_flamebolt", auto=false, d="发射一枚火球攻击目标，对其造成30到44点火焰伤害，并在6 秒内造成额外的3点伤害。"}, {lv=6, id=587, n="造食术", i="inv_misc_food_10", auto=false, d="用魔法合成2块魔法松饼以供法师和的盟友食用。\n\n这些物品会在持有者登出游戏超过15分钟之后消失。"}, {lv=8, id=118, n="变形术", i="spell_nature_polymorph", auto=false, d="将敌人变成绵羊，使其在周围到处闲逛，最多持续20 秒。在这个过程中，绵羊无法攻击或施法，但会以极快的速度恢复生命值，任何伤害都会让绵羊恢复正常状态。每个法师在同一时间内只能将一个目标变成绵羊，只能对野兽、人型生物和小动物施放。"}, {lv=8, id=5143, n="奥术飞弹", i="spell_nature_starfall", auto=false, d="向目标射出数枚奥术飞弹，对其造成每秒24点伤害，持续3 秒。"}, {lv=8, id=205, n="寒冰箭", i="spell_frost_frostbolt02", auto=false, d="向目标射出一支寒冰箭，对其造成31至35点冰霜伤害并使其移动速度降低40%，持续6 秒。"}, {lv=10, id=122, n="冰霜新星", i="spell_frost_frostnova", auto=false, d="冲击施法者附近的所有敌人，对它们造成19至21点冰霜伤害并将其冻结在原地，最多持续8 秒。对被冻结的目标造成伤害可能打断这个效果。"}, {lv=10, id=12355, n="冲击", i="spell_fire_meteorstorm", auto=false, d="火焰法术有几率使目标昏迷2 秒。", tal=true}, {lv=10, id=12536, n="节能施法", i="spell_shadow_manaburn", auto=false, d=""}, {lv=10, id=5505, n="造水术", i="inv_drink_07", auto=false, d="用魔法合成2瓶魔法淡水以供法师和的盟友饮用。\n\n这些物品会在持有者登出游戏超过15分钟之后消失。"}, {lv=10, id=12494, n="霜寒刺骨", i="spell_frost_frostarmor", auto=false, d="", tal=true}, {lv=10, id=7300, n="霜甲术", i="spell_frost_frostarmor02", auto=false, d="使护甲值提高110点。如果敌人使用近战武器攻击施法者，他们的移动速度就有可能被降低30%，攻击间隔延长25%，冰冻效果持续5 秒。法师在同一时间内只能保有一种魔法护甲效果。持续30 分钟。"}, {lv=12, id=145, n="火球术", i="spell_fire_flamebolt", auto=false, d="发射一枚火球攻击目标，对其造成45到61点火焰伤害，并在6 秒内造成额外的6点伤害。"}, {lv=12, id=130, n="缓落术", i="spell_magic_featherfall", auto=false, d="减慢下落速度，持续30 秒。"}, {lv=12, id=597, n="造食术", i="inv_misc_food_09", auto=false, d="用魔法合成2块魔法面包以供法师和的盟友食用。\n\n这些物品会在持有者登出游戏超过15分钟之后消失。"}, {lv=12, id=604, n="魔法抑制", i="spell_nature_abolishmagic", auto=false, d="降低施放于目标小队成员身上的魔法效果，使其受到的法术伤害降低最多15点，治疗法术恢复生命值的效果降低最多30点，持续10 分钟。"}, {lv=14, id=1460, n="奥术智慧", i="spell_holy_magicalsentry", auto=false, d="使目标的智力提高7点，持续1 小时。"}, {lv=14, id=837, n="寒冰箭", i="spell_frost_frostbolt02", auto=false, d="向目标射出一支寒冰箭，对其造成43至49点冰霜伤害并使其移动速度降低40%，持续6 秒。"}, {lv=14, id=2137, n="火焰冲击", i="spell_fire_fireball", auto=false, d="施放火焰冲击敌人，对其造成52到64点火焰伤害。"}, {lv=14, id=1449, n="魔爆术", i="spell_nature_wispsplode", auto=false, d="制造一次以施法者为中心的魔法爆炸，对半径0码范围内的所有目标造成30到34点奥术伤害。"}, {lv=16, id=5144, n="奥术飞弹", i="spell_nature_starfall", auto=false, d="向目标射出数枚奥术飞弹，对其造成每秒31点伤害，持续4 秒。"}, {lv=16, id=2120, n="烈焰风暴", i="spell_fire_selfdestruct", auto=false, d="召唤一根火柱，对区域内所有敌人造成52到68点火焰伤害，并在8 秒内额外造成44点火焰伤害。每名法师同时只能有一个烈焰风暴生效。"}, {lv=18, id=3140, n="火球术", i="spell_fire_flamebolt", auto=false, d="发射一枚火球攻击目标，对其造成62到86点火焰伤害，并在8 秒内造成额外的12点伤害。"}, {lv=18, id=475, n="解除次级诅咒", i="spell_nature_removecurse", auto=false, d="从一个友方目标身上移除1个诅咒或灾祸。"}, {lv=18, id=1008, n="魔法增效", i="spell_holy_flashheal", auto=false, d="增强施放于目标小队成员身上的魔法效果，使其受到的法术伤害最多提高23点，治疗法术所恢复的生命值最多提高45点，持续10 分钟。"}, {lv=20, id=3567, n="传送：奥格瑞玛", i="spell_arcane_teleportorgrimmar", auto=false, d="将施法者传送到奥格瑞玛。"}, {lv=20, id=3563, n="传送：幽暗城", i="spell_arcane_teleportundercity", auto=false, d="将施法者传送到幽暗城。"}, {lv=20, id=3561, n="传送：暴风城", i="spell_arcane_teleportstormwind", auto=false, d="将施法者传送到暴风城。"}, {lv=20, id=3562, n="传送：铁炉堡", i="spell_arcane_teleportironforge", auto=false, d="将施法者传送到铁炉堡。"}, {lv=20, id=1312002, n="冰枪术", i="spell_frost_frostblast", auto=false, d="对一个敌方目标造成26到30点冰霜伤害。对被冰冻的目标造成的伤害提高300%。", tal=true}, {lv=20, id=12824, n="变形术", i="spell_nature_polymorph", auto=false, d="将敌人变成绵羊，使其在周围到处闲逛，最多持续30 秒。在这个过程中，绵羊无法攻击或施法，但会以极快的速度恢复生命值，任何伤害都会让绵羊恢复正常状态。每个法师在同一时间内只能将一个目标变成绵羊，只能对野兽、人型生物和小动物施放。"}, {lv=20, id=12051, n="唤醒", i="spell_nature_purge", auto=false, d="在引导此法术时，你的法力值回复速度提高1500%。持续8 秒。"}, {lv=20, id=400574, n="奥术冲击", i="spell_arcane_blast", auto=false, d="用能量冲击目标，造成50到58点奥术伤害。每次施放奥术冲击，所有其他法术的伤害提高10%，奥术冲击的法力消耗提高175%。该效果最多叠加若干次，持续8 秒，或直到施放任何其他伤害法术。", tal=true}, {lv=20, id=7322, n="寒冰箭", i="spell_frost_frostbolt02", auto=false, d="向目标射出一支寒冰箭，对其造成57至63点冰霜伤害并使其移动速度降低40%，持续7 秒。"}, {lv=20, id=10, n="暴风雪", i="spell_frost_icestorm", auto=false, d="破碎的冰块从天而降，在8 秒内对目标区域中的敌人造成192点冰霜伤害。"}, {lv=20, id=1463, n="法力护盾", i="spell_shadow_detectlesserinvisibility", auto=false, d="吸收120点物理伤害，同时消耗法力值。每吸收1点物理伤害，就消耗若干点法力值。持续1 分钟。"}, {lv=20, id=5506, n="造水术", i="inv_drink_milk_02", auto=false, d="用魔法合成2瓶魔法纯净水以供法师和的盟友饮用。\n\n这些物品会在持有者登出游戏超过15分钟之后消失。"}, {lv=20, id=1953, n="闪现术", i="spell_arcane_blink", auto=false, d="将施法者向前传送20码，除非途中有障碍物。同时解除施法者的昏迷和定身效果。"}, {lv=20, id=543, n="防护火焰结界", i="spell_fire_firearmor", auto=false, d="吸收162点火焰伤害。持续30 秒。"}, {lv=20, id=7301, n="霜甲术", i="spell_frost_frostarmor02", auto=false, d="使护甲值提高200点。如果敌人使用近战武器攻击施法者，他们的移动速度就有可能被降低30%，攻击间隔延长25%，冰冻效果持续5 秒。法师在同一时间内只能保有一种魔法护甲效果。持续30 分钟。"}, {lv=22, id=2138, n="火焰冲击", i="spell_fire_fireball", auto=false, d="施放火焰冲击敌人，对其造成90到110点火焰伤害。"}, {lv=22, id=2948, n="灼烧", i="spell_fire_soulburn", auto=false, d="灼烧敌人，对其造成35到43点火焰伤害。"}, {lv=22, id=990, n="造食术", i="inv_misc_food_12", auto=false, d="用魔法合成2块魔法黑面包以供法师和的盟友食用。\n\n这些物品会在持有者登出游戏超过15分钟之后消失。"}, {lv=22, id=6143, n="防护冰霜结界", i="spell_frost_frostward", auto=false, d="吸收162点冰霜伤害。持续30 秒。"}, {lv=22, id=8437, n="魔爆术", i="spell_nature_wispsplode", auto=false, d="制造一次以施法者为中心的魔法爆炸，对半径0码范围内的所有目标造成52到58点奥术伤害。"}, {lv=24, id=5145, n="奥术飞弹", i="spell_nature_starfall", auto=false, d="向目标射出数枚奥术飞弹，对其造成每秒44点伤害，持续5 秒。"}, {lv=24, id=2139, n="法术反制", i="spell_frost_iceshock", auto=false, d="反制敌人的法术，使其在10 秒内无法施放任何与该法术属于同一类别的法术。产生很高的威胁值。"}, {lv=24, id=8400, n="火球术", i="spell_fire_flamebolt", auto=false, d="发射一枚火球攻击目标，对其造成92到124点火焰伤害，并在8 秒内造成额外的16点伤害。"}, {lv=24, id=12505, n="炎爆术", i="spell_fire_fireball02", auto=false, d="发射一枚巨大的火球，对目标造成116到152点火焰伤害，并在12 秒内造成总计56点额外伤害。", tal=true}, {lv=24, id=2121, n="烈焰风暴", i="spell_fire_selfdestruct", auto=false, d="召唤一根火柱，对区域内所有敌人造成96到122点火焰伤害，并在8 秒内额外造成84点火焰伤害。每名法师同时只能有一个烈焰风暴生效。"}, {lv=24, id=8450, n="魔法抑制", i="spell_nature_abolishmagic", auto=false, d="降低施放于目标小队成员身上的魔法效果，使其受到的法术伤害降低最多30点，治疗法术恢复生命值的效果降低最多60点，持续10 分钟。"}, {lv=26, id=120, n="冰锥术", i="spell_frost_glacier", auto=false, d="施法者面前锥形范围内的目标受到92至102点冰霜伤害，移动速度降低40%，持续6 秒。"}, {lv=26, id=865, n="冰霜新星", i="spell_frost_frostnova", auto=false, d="冲击施法者附近的所有敌人，对它们造成32至36点冰霜伤害并将其冻结在原地，最多持续8 秒。对被冻结的目标造成伤害可能打断这个效果。"}, {lv=26, id=8406, n="寒冰箭", i="spell_frost_frostbolt02", auto=false, d="向目标射出一支寒冰箭，对其造成91至99点冰霜伤害并使其移动速度降低40%，持续7 秒。"}, {lv=28, id=400640, n="冰枪术", i="spell_frost_frostblast", auto=false, d="对一个敌方目标造成33到39点冰霜伤害。对被冰冻的目标造成的伤害提高300%。", tal=true}, {lv=28, id=759, n="制造魔法玛瑙", i="inv_misc_gem_emerald_01", auto=false, d="制造一颗魔法玛瑙，使用后可以立刻恢复375到425点法力值。\n\n这些物品会在持有者登出游戏超过15分钟之后消失。"}, {lv=28, id=1461, n="奥术智慧", i="spell_holy_magicalsentry", auto=false, d="使目标的智力提高15点，持续1 小时。"}, {lv=28, id=6141, n="暴风雪", i="spell_frost_icestorm", auto=false, d="破碎的冰块从天而降，在8 秒内对目标区域中的敌人造成336点冰霜伤害。"}, {lv=28, id=8494, n="法力护盾", i="spell_shadow_detectlesserinvisibility", auto=false, d="吸收210点物理伤害，同时消耗法力值。每吸收1点物理伤害，就消耗若干点法力值。持续1 分钟。"}, {lv=28, id=8444, n="灼烧", i="spell_fire_soulburn", auto=false, d="灼烧敌人，对其造成50到60点火焰伤害。"}, {lv=30, id=3565, n="传送：达纳苏斯", i="spell_arcane_teleportdarnassus", auto=false, d="将施法者传送到达纳苏斯。"}, {lv=30, id=3566, n="传送：雷霆崖", i="spell_arcane_teleportthunderbluff", auto=false, d="将施法者传送到雷霆崖。"}, {lv=30, id=7302, n="冰甲术", 