  questSeries = {
    Warrior = {["防御之道"]={min=10, variants={{zone="暴风城", q={{t="醉鬼巴特莱比", lv=10, o="和巴特莱比谈一谈。", g={{n="哈里·伯加德", z="暴风城", x=74.3, y=37.3}}}, {t="击败巴特莱比", lv=10, o="打败巴特莱比，然后再和他谈一谈。", g={{n="巴特莱比", z="暴风城", x=73.8, y=36.3}}}, {t="巴特莱比的酒杯", lv=10, o="把巴特莱比的酒杯交给伯加德。", g={{n="巴特莱比", z="暴风城", x=73.8, y=36.3}}}, {t="治安官哈迦德", lv=10, o="和治安官哈迦德谈一谈。", g={{n="哈里·伯加德", z="暴风城", x=74.3, y=37.3}}}, {t="蛀牙杰克", lv=10, o="从蛀牙杰克的营地里取回治安官哈迦德的徽章，把它交给治安官哈迦德。", g={{n="治安官哈迦德", z="艾尔文森林", x=84.6, y=69.4}}}}}, {zone="达纳苏斯", q={{t="沃鲁斯·邪蹄", lv=10, o="将沃鲁斯的角交给达纳苏斯的艾兰娜瑞。", g={{n="艾兰娜瑞", z="达纳苏斯", x=57.3, y=34.6}}}, {t="艾鲁拉的阴影", lv=10, o="将艾鲁拉的徽章和8块月神矿石交给达纳苏斯的艾兰娜瑞。", g={{n="艾兰娜瑞", z="达纳苏斯", x=57.3, y=34.6}}}, {t="铁匠玛希尔", lv=10, o="把这箱月神矿石交给铁匠玛希尔。", g={{n="艾兰娜瑞", z="达纳苏斯", x=57.3, y=34.6}}}, {t="月神武器", lv=10, o="", g={{n="玛希尔", z="达纳苏斯", x=59.5, y=45.4}}}}}, {zone="杜隆塔尔", q={{t="防御之道", lv=10, o="给贫瘠之地前沿哨所的犹塞克带回5块烧焦的鳞片。", g={{n="犹塞克", z="杜隆塔尔", x=30.9, y=46.0}}}, {t="索恩格瑞姆·火眼", lv=10, o="与贫瘠之地的索恩格瑞姆·火眼谈一谈。", g={{n="犹塞克", z="杜隆塔尔", x=30.9, y=46.0}}}, {t="锻造好的钢锭", lv=10, o="把锻造好的钢锭带给贫瘠之地的索恩格瑞姆·火眼。", g={{n="索恩格瑞姆·火眼", z="杜隆塔尔", x=23.0, y=63.7}}}}}}}, ["狂战士之道"]={min=30, variants={{zone="雷霆崖", q={{t="岛民", lv=30, o="和克兰诺克·马克雷德谈一谈。", g={{n="托姆·狂暴图腾", z="雷霆崖", x=57.2, y=87.4}, {n="索瑞克", z="奥格瑞玛", x=80.4, y=32.4}}}, {t="格斗考验", lv=30, o="杀掉比格维尔，然后向勇士岛的克兰诺克·马克雷德回复。", g={{n="克兰诺克·马克雷德", z="杜隆塔尔", x=44.8, y=99.8}}}, {t="捕风者", lv=30, o="和捕风者巴斯拉谈一谈。", g={{n="克兰诺克·马克雷德", z="杜隆塔尔", x=44.8, y=99.8}}}, {t="塞克隆尼亚", lv=40, o="把巴斯拉的羊皮纸上列出的东西交给奥特兰克的捕风者巴斯拉。", g={{n="捕风者巴斯拉", z="奥特兰克山脉", x=80.5, y=66.9}}}, {t="召唤", lv=40, o="将旋风之心带给捕风者巴斯拉。", g={{n="捕风者巴斯拉", z="奥特兰克山脉", x=80.5, y=66.9}}}, {t="旋风武器", lv=40, o="", g={{n="捕风者巴斯拉", z="奥特兰克山脉", x=80.5, y=66.9}}}}}}}},
    Paladin = {["召唤军马"]={min=40, variants={{zone="暴风城", q={{t="高贵之书", lv=40, o="与暴风城的达索瑞恩·拉尔谈一谈。", g={{n="达索瑞恩·拉尔", z="暴风城", x=39.8, y=29.8}}}}}}}, ["召唤战马"]={min=60, variants={{zone="暴风城", q={{t="上古圣马之魂", lv=60, o="你需要特殊的饲料来喂养灵魂马。南海镇的梅丽德丝·卡尔森可以为你提供这样的粮草。$B$B到菲拉斯的厄运之槌去，杀掉特迪斯·扭木，释放上古圣马之魂。用特殊的粮草喂养它，这样可以安抚它的灵魂。最后，把奥金马铠交给它就可以完成祝福。", g={{n="格雷森·沙东布瑞克公爵", z="暴风城", x=37.2, y=33.3}}}, {t="被祝福的奥金马铠", lv=60, o="将被祝福的奥金马铠交给暴风城教堂区的格雷森·沙东布瑞克公爵。", g={{n="上古圣马之魂", z="", x=0, y=0}}}, {t="预言水晶球", lv=60, o="把一块艾泽拉斯钻石和一块原始黑钻石交给暴风城教堂区的格雷森·沙东布瑞克公爵。", g={{n="格雷森·沙东布瑞克公爵", z="暴风城", x=37.2, y=33.3}}}, {t="审判和救赎", lv=60, o="在通灵学院尸骨储藏所地下室的中心使用预言水晶球。将你要审判的灵魂引领出来。将这些灵魂击败然后死亡骑士达克雷尔就将被召唤出来。将其击败然后获得堕落战马的灵魂。$B$B把赎罪的战马之魂和被祝福的奥金马铠一起附在达克雷尔的堕落战马身上。", g={{n="格雷森·沙东布瑞克公爵", z="暴风城", x=37.2, y=33.3}}}, {t="重回尸骨储藏所", lv=60, o="", g={{n="格雷森·沙东布瑞克公爵", z="暴风城", x=37.2, y=33.3}}}}}}}},
