    Rogue = {["毒药"]={min=20, variants={{zone="暴风城", q={{t="马迪亚斯和迪菲亚盗贼", lv=20, o="去西部荒野和密探吉尔妮谈一谈。", g={{n="马迪亚斯·肖尔", z="暴风城", x=75.8, y=59.8}}}, {t="克拉文之塔", lv=24, o="偷取迪菲亚塔楼钥匙，进入迪菲亚塔楼，看看暮色森林的箱子里到底有什么东西，然后向暴风城的马迪亚斯·肖尔汇报。", g={{n="密探吉尔妮", z="暮色森林", x=7.9, y=73.3}}}, {t="赞吉尔之触", lv=20, o="到兵营的地窖里去和道克·米希匹克斯谈一谈。", g={{n="马迪亚斯·肖尔", z="暴风城", x=75.8, y=59.8}}}}}}}},
    Priest = {["星辰碎片"]={min=10, variants={{zone="达纳苏斯", q={{t="艾露恩之星*", lv=10, o="同阿兰希雅再次交谈，学习一种新的法术!", g={{n="女祭司阿兰希雅", z="达纳苏斯", x=39.5, y=81.2}}}}}}}, ["绝望祷言"]={min=10, variants={{zone="暴风城", q={{t="绝望祷言", lv=10, o="", g={{n="高阶牧师劳瑞娜", z="暴风城", x=38.6, y=26.1}}}}}}}, ["虚弱妖术"]={min=10, variants={{zone="奥格瑞玛", q={{t="虚弱妖术", lv=10, o="", g={{n="乌尔库", z="奥格瑞玛", x=35.6, y=87.8}}}}}}}, ["虚弱之触"]={min=10, variants={{zone="幽暗城", q={{t="虚弱之触", lv=10, o="", g={{n="艾萨莱斯特", z="幽暗城", x=49.0, y=18.3}}}}}}}, ["防护恐惧结界"]={min=20, variants={{zone="铁炉堡", q={{t="毫无畏惧", lv=20, o="与铁炉堡的高阶牧师洛汉谈一谈。", g={{n="高阶牧师洛汉", z="铁炉堡", x=24.7, y=8.2}}}}}}}, ["暗影守卫"]={min=20, variants={{zone="雷霆崖", q={{t="暗影守卫", lv=20, o="与奥格瑞玛的乌尔库谈一谈。", g={{n="麦尔斯·威尔什", z="雷霆崖", x=25.3, y=15.3}}}}}}}, ["噬灵瘟疫"]={min=20, variants={{zone="雷霆崖", q={{t="噬灵瘟疫", lv=20, o="与幽暗城的艾萨莱斯特谈一谈。", g={{n="麦尔斯·威尔什", z="雷霆崖", x=25.3, y=15.3}}}}}}}, ["艾露恩的赐福"]={min=20, variants={{zone="达纳苏斯", q={{t="艾露恩的赐福", lv=20, o="与达纳苏斯的女祭司阿兰希雅谈一谈。", g={{n="女祭司阿兰希雅", z="达纳苏斯", x=39.5, y=81.2}}}}}}}, ["回馈"]={min=20, variants={{zone="暴风城", q={{t="奥术回馈者*", lv=20, o="与暴风城的高阶牧师劳瑞娜谈一谈。", g={{n="高阶牧师劳瑞娜", z="暴风城", x=38.6, y=26.1}}}}}}}, ["野性印记"]={min=50, variants={{zone="暴风城", q={{t="塞纳里奥议会的求助", lv=52, o="找到艾萨拉的奥汀克。", g={{n="乔舒修士", z="暴风城", x=38.5, y=26.9}, {n="乌尔库", z="奥格瑞玛", x=35.6, y=87.8}}}, {t="苔蹄快步者", lv=52, o="收集4份健康的野鹿腺体，把它们交给艾萨拉的奥汀克。奥汀克住在埃达拉斯废墟东北部悬崖的顶部。", g={{n="奥汀克", z="艾萨拉", x=42.4, y=42.6}}}, {t="亡灵的腐液", lv=52, o="为艾萨拉的奥汀克带回一份亡灵腐液。奥汀克住在埃达拉斯废墟东北部悬崖的顶端。", g={{n="奥汀克", z="艾萨拉", x=42.4, y=42.6}}}, {t="摩弗拉斯之血", lv=52, o="前往沉没的阿塔哈卡神庙，杀死绿龙摩弗拉斯，将他的血液交给费伍德森林中的格雷塔·苔蹄。沉没的神庙的入口就在悲伤沼泽中。", g={{n="奥汀克", z="艾萨拉", x=42.4, y=42.6}}}}}}}},
    Shaman = {["迅捷之风"]={min=30, variants={{zone="奥格瑞玛", q={{t="空气的召唤", lv=30, o="到千针石林去找普拉特·白云。", g={{n="希尔恩·火结", z="奥格瑞玛", x=38.0, y=37.7}}}}}}}},
    Mage = {["传送到艾萨拉之塔"]={min=50, variants={{zone="暴风城", q={{t="法师的会见", lv=52, o="找到萨纳斯，让他将你传送到大法师克希雷姆那儿。", g={{n="玛吉诺·仲马", z="暴风城", x=38.2, y=81.9}, {n="大法师山姆", z="雷霆崖", x=22.8, y=14.5}}}, {t="魔法的尘埃", lv=52, o="为大法师克希雷姆收集10份闪光尘埃。", g={{n="大法师克希雷姆", z="艾萨拉", x=29.2, y=40.2}}}, {t="纳迦的珊瑚", lv=52, o="收集6块魔化珊瑚，然后把它们交给大法师克希雷姆。", g={{n="大法师克希雷姆", z="艾萨拉", x=29.2, y=40.2}}}, {t="毁灭摩弗拉斯", lv=52, o="从摩弗拉斯身上取回奥术碎片，然后返回大法师克希雷姆那儿。", g={{n="大法师克希雷姆", z="艾萨拉", x=29.2, y=40.2}}}}}}}, ["变形术"]={min=60, variants={{zone="艾萨拉", q={{t="军阀克雷利安", lv=60, o="为大法师克希雷姆夺回虹彩贝壳。大法师克希雷姆就居住在艾萨拉北部悬崖上的一座塔中。", g={{n="大法师克希雷姆", z="艾萨拉", x=29.2, y=40.2}}}, {t="魔法的碎片", lv=60, o="对艾萨拉的恶鞭纳迦使用变形术，然后杀死几秒钟后出现的相似体。当你杀了50个相似体后，回去向大法师克希雷姆复命。", g={{n="大法师克希雷姆", z="艾萨拉", x=29.2, y=40.2}}}}}}}, ["造水术"]={min=60, variants={{zone="", q={{t="久违的法师", lv=60, o="到厄运之槌的扭木广场去杀掉水元素海多斯博恩。把海多斯博恩精华交给图书馆的博学者莱德罗斯。", g={{n="博学者莱德罗斯", z="", x=0, y=0}}}}}}}},
    Warlock = {["召唤小鬼"]={min=1, variants={{zone="提瑞斯法林地", q={{t="控制小鬼", lv=4, o="收集3个断骨骷髅的颅骨，把它们交给温雅·玛山德。", g={{n="温雅·玛山德", z="提瑞斯法林地", x=31.0, y=66.4}}}}}}}, ["召唤虚空行者"]={min=10, variants={{zone="幽暗城", q={{t="誓缚", lv=10, o="召唤并征服一只虚空行者，然后将召唤符文还给诅咒神庙中的凯伦丁·哈加尔。", g={{n="凯伦丁·哈加尔", z="幽暗城", x=85.1, y=26.0}}}}}}}, ["召唤魅魔"]={min=20, variants={{zone="幽暗城", q={{t="噬魂者", lv=20, o="与诅咒神殿中的高德瑞克·法杉谈一谈。", g={{n="凯伦丁·哈加尔", z="幽暗城", x=85.1, y=26.0}}}, {t="纯洁者之心", lv=20, o="将达林和科马的心脏交给诅咒神殿里的凯伦丁·哈加尔。", g={{n="高德瑞克·法杉", z="幽暗城", x=84.8, y=14.8}}}, {t="誓缚", lv=20, o="召唤并征服一只魅魔，然后将纯洁的心还给诅咒神庙里的凯伦丁·哈加尔。", g={{n="凯伦丁·哈加尔", z="幽暗城", x=85.1, y=26.0}}}}}}}, ["召唤地狱猎犬"]={min=30, variants={{zone="杜隆塔尔", q={{t="誓缚", lv=30, o="召唤地狱猎犬并打败它，然后把阴谋之书交给棘齿城的斯坦哈德·法尔杉。", g={{n="斯坦哈德·法尔杉", z="杜隆塔尔", x=33.3, y=73.6}}}}}}}, ["地狱火"]={min=50, variants={{zone="费伍德森林", q={{t="尼比的助手", lv=50, o="与费伍德森林的伊普斯谈一谈。", g={{n="万能的尼比", z="费伍德森林", x=41.4, y=44.9}}}, {t="无暇的恶魔精华", lv=55, o="费伍德的伊普斯要求你从三个不同的地区收集三块无暇的恶魔精华，然后把它们交给他。$B$B艾萨拉的雷加斯萨特、费伍德森林的加德纳尔军团士兵和诅咒之地的地狱卫士斥候分别拥有一种无暇的恶魔精华。", g={{n="伊普斯", z="费伍德森林", x=41.4, y=45.0}}}, {t="克罗苏斯的恶魔之核", lv=55, o="在费伍德森林的碎痕谷中搜寻克罗苏斯的尸体。当你找到尸体后，在他身上使用魔火，并等待克罗苏斯复生。当这个地狱火被唤醒之后，干掉他，从他的身上拿取克罗苏斯的恶魔之核。$B$B把克罗苏斯的恶魔之核交给费伍德森林的尼比。", g={{n="伊普斯", z="费伍德森林", x=41.4, y=45.0}}}}}}}, ["召唤恐惧战马"]={min=60, variants={{zone="暴风城", q={{t="莫苏尔·召血者", lv=58, o="与燃烧平原的莫苏尔·召血者谈一谈。", g={{n="斯巴克尔", z="暴风城", x=25.7, y=77.6}, {n="马尔萨·斯坦恩", z="幽暗城", x=85.7, y=16.1}}}, {t="血之狂暴", lv=58, o="把30瓶狂暴野兽的血交给燃烧平原的莫苏尔·召血者。", g={{n="莫苏尔·召血者", z="燃烧平原", x=12.7, y=31.6}}}, {t="戈瑟奇·邪眼", lv=58, o="把血箱交给燃烧平原的戈瑟奇·邪眼。", g={{n="莫苏尔·召血者", z="燃烧平原", x=12.7, y=31.6}}}, {t="魔王贝恩霍勒", lv=58, o="从燃烧平原的戈瑟奇那里购买暗影药水。$B$B使用这种药剂进入加德纳尔，然后与魔王贝恩霍勒谈一谈。", g={{n="戈瑟奇·邪眼", z="燃烧平原", x=12.4, y=31.6}}}, {t="背叛者乌拉泰克", lv=58, o="找到并杀死乌拉泰克，然后把叛徒之心交给加德纳尔的魔王贝恩霍勒。", g={{n="魔王贝恩霍勒", z="费伍德森林", x=35.9, y=44.4}}}, {t="克索诺斯星尘", lv=60, o="从乌尔丹那里购买克索诺斯星尘，把它交给燃烧平原的戈瑟奇·邪眼。", g={{n="魔王贝恩霍勒", z="费伍德森林", x=35.9, y=44.4}}}, {t="瓶中的小鬼", lv=60, o="把瓶中的小鬼带到通灵学院的炼金实验室中。在小鬼制造出羊皮纸之后，把瓶子还给戈瑟奇·邪眼。", g={{n="戈瑟奇·邪眼", z="燃烧平原", x=12.4, y=31.6}}}, {t="克索诺斯恐惧战马", lv=60, o="阅读莫苏尔的指南，并召唤出一匹克索诺斯恐惧战马，击败它，然后控制它的灵魂。", g={{n="莫苏尔·召血者", z="燃烧平原", x=12.7, y=31.6}}}}}}}, ["末日仪式"]={min=60, variants={{zone="诅咒之地", q={{t="监牢之链", lv=60, o="到菲拉斯的厄运之槌去，从扭木广场的荒野萨特身上找到15份萨特之血，然后把它们交给腐烂之痕的戴奥。", g={{n="衰老的戴奥", z="诅咒之地", x=34.1, y=50.1}}}, {t="压制", lv=60, o="在腐烂之痕中找到一个末日守卫指挥官。$B$B对其使用光芒水晶监牢。你要做好承受疯狂攻击的准备，那个恶魔会拼命挣扎试图逃脱。$B$B如果你成功了，就把被囚禁的末日守卫交给腐烂之痕的戴奥。", g={{n="衰老的戴奥", z="诅咒之地", x=34.1, y=50.1}}}}}}}},
    Druid = {["熊形态"]={min=10, variants={{zone="达纳苏斯", q={{t="月光林地", lv=10, o="使用法术“传送：月光林地”抵达月光林地，在那里与永夜港的德迪利特·星焰谈一谈。", g={{n="玛斯雷·驭熊者", z="达纳苏斯", x=35.4, y=8.4}}}, {t="巨熊之灵", lv=10, o="到月光林地的西北部去寻找巨熊之灵，向它学习关于熊的知识，然后回到月光林地的永夜港去找德迪利特·星焰。", g={{n="德迪利特·星焰", z="月光林地", x=56.2, y=30.6}}}, {t="返回达纳苏斯", lv=10, o="回到达纳苏斯，与塞纳里奥区的玛斯雷·驭熊者谈一谈。", g={{n="德迪利特·星焰", z="月光林地", x=56.2, y=30.6}}}, {t="身心之力", lv=10, o="使用奥伯丁的月夜枭兽之石上面的塞纳里奥月尘引出月爪枭兽，然后击败月爪枭兽并吸取它所拥有的身心之力。$B$B任务完成之后，与达纳苏斯的玛斯雷·驭熊者谈一谈。", g={{n="玛斯雷·驭熊者", z="达纳苏斯", x=35.4, y=8.4}}}}}}}, ["消毒术"]={min=14, variants={{zone="达纳苏斯", q={{t="新的课程", lv=14, o="到月光林地去，与永夜港的德迪利特·星焰谈一谈。", g={{n="玛斯雷·驭熊者", z="达纳苏斯", x=35.4, y=8.4}}}, {t="毒水之源", lv=14, o="使用空的峭壁之泉取样器在瀑布洞口获得水样。$B$B将盛满的峭壁之泉取样器送到黑海岸奥伯丁的奥兰达利亚·夜歌那里。", g={{n="德迪利特·星焰", z="月光林地", x=56.2, y=30.6}}}, {t="收集解药", lv=14, o="收集5个地根草和12个月亮菇，把它们交给奥伯丁的奥兰达利亚·夜歌，这样她就可以制作解药了。", g={{n="奥兰达利亚·夜歌", z="费伍德森林", x=20.3, y=15.0}}}, {t="消除疾病", lv=14, o="对黑海岸的10头生病的鹿使用动物医疗药膏，以此来治疗它们。从壁泉河到奥伯丁，直到最南端靠近灰谷的地区都有生病的鹿出没。", g={{n="奥兰达利亚·夜歌", z="费伍德森林", x=20.3, y=15.0}}}, {t="解毒之术", lv=14, o="回到达纳苏斯塞纳里奥区的玛斯雷·驭熊者那里。", g={{n="德迪利特·星焰", z="月光林地", x=56.2, y=30.6}}}}}}}, ["水栖形态"]={min=16, variants={{zone="达纳苏斯", q={{t="必修的课程", lv=16, o="与月光林地永夜港的德迪利特·星焰谈一谈。", g={{n="玛斯雷·驭熊者", z="达纳苏斯", x=35.4, y=8.4}}}, {t="湖中试炼", lv=16, o="在月神湖寻找神殿灵珠，把它带到月光林地西北部的雷姆洛斯神殿去。在神殿中使用神殿灵珠，然后与神殿中的塔加里谈话来完成试炼。", g={{n="德迪利特·星焰", z="月光林地", x=56.2, y=30.6}}}, {t="海狮试炼", lv=16, o="寻找水兽耐力坠饰和水兽敏捷坠饰。与月光林地的居民谈一谈，找出这些东西可能被放在哪里。$B$B在雷姆洛斯神殿附近将海狮坠饰的两部分合而为一。$B$B将合并好的坠饰交给月光林地永夜港中的德迪利特·星焰。", g={{n="塔加里", z="月光林地", x=36.5, y=40.1}}}, {t="水栖形态", lv=16, o="回到达纳苏斯，让玛斯雷·驭熊者看看你的海狮坠饰。", g={{n="德迪利特·星焰", z="月光林地", x=56.2, y=30.6}}}}}}}},
  },
}
